sp_widget.client_script:
/* ==========================================================================
   Key Customer Limit Request (Central SPOC) - Client Script  v2.0
   UI-only changes (no calculation / validation / submit logic touched):
   - Group-code dropdown tree for the three hierarchy tables (Step 1, 3, 4):
       c.tree (search text per table), treeRows() row builder, loadGroupLive(),
       c.treeAnyOpen(kind), c.treeToggleAll(kind)  (Collapse all / Expand all)
   - rebuildHier / rebuildEp / rebuildRev now build rows {kind: G | S | ZT} with group and
     zone row-spans; toggleGroup / toggleEpGroup / toggleRevGroup open a group (all its zones
     and sites show underneath). Zone-level toggles were removed (no longer used).
   - c.rvReqCount(r): number of requested sites under a row (for the "N requested" chip).
   - resetForm also clears the tree search boxes.
   v2.4 (Grandparent lock): showLockWarning now explains Grandparent-level locks (an open request or a pending
        limit swap on any site of the Grandparent blocks every site of that Grandparent). The locks themselves
        are computed on the server and arrive as flags on each site (gp_req_lock / gp_swap_lock).
   v2.3 (safe limit fix): Safe Limit block now compares the updated Grandparent limit with the safe limit
        (c.isWithinSafe / c.getDeviationGap) like the Non-Trade script; c.getToolWorking() feeds the
        "Tool working not triggered" note; isDeviation (approval trigger) logic unchanged.
        External rating: BB / BB+ / BB- now = B (as Non-Trade), proxy bands no longer rounded.
   v2.3b: Step 4 top result row waits for the live limits ("Calculating") before showing Standard / Deviation and
          states the reason (tool working trigger / Grandparent net exposure vs safe limit).
   v2.2 (UI text only): c.terrText(name, code) -> "NAME (code)" for the Step 1 Territory column.
   v2.1 (UI text only): c.locText(name, code) -> "NAME(code)" for the Z / R / D lines; MACL rows carry
   zTxt / rTxt / dTxt (zone / region / depot text of requested sites) for the Site-wise Position table.
   ========================================================================== */
api.controller = function($scope, $timeout, $interval, nowAttachmentHandler) {
    var c = this;

    c.data.currentStep = 1;
    c.data.distinctGPCodes = [];
    c.data.distinctGroupCodes = [];
    c.data.selectedGPCode = '';
    c.data.selectedGroupCode = '';
    c.data.activeDraft = null;
    c.data.calc = { p1: 0, p2: 0, p3: 0, safeLimit: 0 };
    c.data.submitting = false;
    c.data.businessJustification = '';
    c.data.deviationJustification = '';
    c.data.reviewConfirmed = false;
    c.allSelected = false;
    c.data.isFetchingGroups = false;
    c.data.loadingSites = false;
    c.data.loadError = '';
    c.data.lockWarning = '';

    // Grandparent overview / hierarchy
    c.data.gpOverview = null;
    c.data.gpLive = { loading: false, limit: 0, bg: 0, activeBg: 0 };
    c.data.hierRows = [];
    c.data.overviewLoading = false;
    c.data.overviewError = '';

    // Group code tree tables: search text of each table (Step 1 = hier, Step 3 = ep, Step 4 = rev)
    c.tree = { hier: { q: '' }, ep: { q: '' }, rev: { q: '' } };

    // Step 3 / Step 4 data
    c.data.epRows = [];
    c.data.epTotals = { exp: 0, req: 0 };
    c.data.revRows = [];
    c.data.gpMacl = { groups: [], totalExpected: 0, macl: 0, siteCount: 0, unit: 'MT', segments: [] };
    c.data.revComposite = { common: { groups: [], pts: 0, wPct: 0 }, segRows: [], segments: [], totalContrib: 0 };
    c.data.aiSummaryPoints = [];
    c.data.p1Breakdown = [];
    c.data.p2Breakdown = [];

    // Step 4 MACL table: scope (requested / all sites), search and paging
    c.macl = { page: 1, size: 10, search: '', scope: 'requested' };
    var maclView = { src: null, key: null, groups: [], total: 0, pages: 1, start: 0, end: 0,
                     totals: { sites: 0, expected: 0, macl: 0 } };

    // Site table paging / search
    c.data.localSearch = '';
    c.data.currentPage = 1;
    c.data.itemsPerPage = 10;

    c.data.tw = {
        documentType: 'No Document', fileName: '', fileData: null,
        targetTable: '', ocrSysId: null, ocrProcessing: false, ocrDone: false,
        ocrError: '', statusMsg: '', lastOcrResult: null, groupedParameters: {}
    };

    var twPollTimer = null;
    var twPollCount = 0;
    var TW_MAX_POLLS = 15;
    var DEFAULT_CREDIT_TENOR = 45;
    var SEGMENT_ORDER = ['Cement', 'RMC', 'BPD'];
    // SAP keeps a placeholder limit of Rs 1 on sites without a real limit. It is treated as nil when working out
    // how much a request changes the Zonal / Group / Grandparent limit. Set to 0 to switch this off.
    var SAP_PLACEHOLDER_LIMIT = 1;
    var liveCache = {};

    $scope.attachments = [];
    $scope.attachmentHandler = new nowAttachmentHandler(function(attachments) {
        $scope.attachments = attachments;
        $scope.$evalAsync();
    }, function(error) {
        alert(error.msg || 'Failed to upload attachment.');
        $scope.$evalAsync();
    });
    $scope.attachmentHandler.setParams(c.data.table, c.data.sys_id, 1024 * 1024 * 20);

    c.server.get({ action: 'fetch_draft_gps' }).then(function(r) {
        c.data.isAuthorized = r.data.isAuthorized;
        c.data.distinctGPCodes = r.data.distinctGPCodes || [];
    });

    function scrollToTop() {
        $timeout(function() {
            var el = document.querySelector('.clm-widget');
            if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 50);
    }

    // ---------- helpers ----------
    function num(v) { return parseFloat(v) || 0; }
    function up(v) { return (v || '').toString().trim().toUpperCase(); }
    function segKey(t) {
        t = (t || '').toString().toLowerCase();
        if (t.indexOf('cement') !== -1) return 'Cement';
        if (t.indexOf('rmc') !== -1) return 'RMC';
        if (t.indexOf('bpd') !== -1) return 'BPD';
        return null;
    }

    // Only the copies of Potential / Current SOB % for the OTHER segments are hidden in the Risk Parameters step
    // (they are scored automatically and shown in the review). The selected group's own Potential / SOB are shown.
    function isHiddenParam(p) {
        return !!(p && p.extraSeg);
    }

    // segment level parameters (selected segment + other segments)
    function isSegParam(p) {
        return !!(p && (p.extraSeg || p.k === 'segment_potential' || p.k === 'current_share'));
    }

    // current limit used when working out the change a request makes (SAP placeholder limit counts as nil)
    c.effLimit = function(v) {
        var n = parseFloat(v) || 0;
        return (n > 0 && n <= SAP_PLACEHOLDER_LIMIT) ? 0 : n;
    };

    // "NAME (code)" text for the Territory column (Depot / Region · Zone)
    c.terrText = function(name, code) {
        name = (name || '').toString().trim(); code = (code || '').toString().trim();
        if (name && code) return name + ' (' + code + ')';
        return name || code || '—';
    };

    // "NAME(code)" text for the Z / R / D lines under a customer name
    c.locText = function(name, code) {
        name = (name || '').toString().trim(); code = (code || '').toString().trim();
        if (name && code) return name + '(' + code + ')';
        return name || code || '—';
    };

    c.formatINR = function(val) {
        if (val === undefined || val === null || val === '') return '0.00';
        var n = parseFloat(val);
        if (isNaN(n)) return '0.00';
        return n.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    };

    c.pct = function(v, dp) {
        var n = parseFloat(v);
        if (isNaN(n)) return '0';
        return n.toFixed(dp === undefined ? 2 : dp);
    };

    c.ne = function(node) {
        return (parseFloat(node && node.limit) || 0) - (parseFloat(node && node.activeBg) || 0);
    };

    c.getGpSelectedSegment = function() {
        var sites = c.data.activeDraft && c.data.activeDraft.sites;
        if (!sites || !sites.length) return '';
        return segKey(sites[0].segment) || '';
    };

    c.getQtyUnit = function() {
        return c.getGpSelectedSegment() === 'RMC' ? 'CuM' : 'MT';
    };

    c.epUnit = function(n) {
        var s = ((n && n.segment) || '').toLowerCase();
        return (s.indexOf('rmc') !== -1 && s.indexOf('cement') === -1 && s.indexOf('bpd') === -1) ? 'CuM' : 'MT';
    };

    // External rating proxy from Composite Index points (same bands as the Non-Trade script): >= 61 A, >= 31 B, else C
    c.ratingFromPts = function(pts) {
        var r = parseFloat(pts) || 0;
        if (r >= 61) return 'A';
        if (r >= 31) return 'B';
        return 'C';
    };

    // Credit Index (P3) factor from Internal x External rating
    c.p3FactorFor = function(internal, external) {
        if (internal === 'A' && external === 'A') return 1.0;
        if ((internal === 'A' && external === 'B') || (internal === 'B' && external === 'A')) return 0.75;
        if (internal === 'B' && external === 'B') return 0.60;
        return 0.0;
    };

    // External rating actually entered / read from the uploaded document, mapped to A/B/C. '' when none.
    c.enteredExternalRating = function() {
        var r = c.data.tw.lastOcrResult;
        if (!r) return '';
        var s = (((r.rating || '') + ' ' + (r.risk_index || '')).trim()).toUpperCase();
        if (!s) return '';
        if (/4\/5|5\/5|\bLOW\b/.test(s)) return 'A';
        if (/3\/5|\bMEDIUM\b/.test(s)) return 'B';
        if (/1\/5|2\/5|\bHIGH\b/.test(s)) return 'C';
        var m = s.match(/\b(AAA|AA|A|BBB|BB|B|CCC|CC|C|D)(?=[+\-\s]|$)/);
        if (m) {
            var g = m[1];
            if (g === 'AAA' || g === 'AA' || g === 'A') return 'A';
            if (g === 'BBB' || g === 'BB') return 'B';
            return 'C';
        }
        return '';
    };

    // internal rating comes from the server (6-month average ageing). External = entered rating (worst of all entries) else proxy.
    c.getCredit = function() {
        var cr = c.data.gpOverview && c.data.gpOverview.credit;
        if (!cr) return { buckets: [], total: 0, internal: 'A', external: 'C', extSource: '', pctSafe: 0, pctCritical: 0, p3Factor: 0, customers: 0, months: 0 };
        var rank = { A: 1, B: 2, C: 3 };
        var cands = [c.enteredExternalRating(), cr.prevExtRating].filter(function(x) { return !!x; });
        var ext = c.ratingFromPts((c.data.calc.p2 || 0) * 100), src = 'Proxy (Composite Index)';
        if (cands.length) {
            ext = cands.reduce(function(w, x) { return rank[x] > rank[w] ? x : w; });   // lowest rating wins
            src = 'Entered / document';
        }
        return angular.extend({}, cr, { external: ext, extSource: src, p3Factor: c.p3FactorFor(cr.internal, ext) });
    };

    // ---------- live (WSDL) fetch with cache ----------
    c.fetchLive = function(code, salesOrg, extra, done) {
        var key = code + '|' + (salesOrg || '') + '|' + ((extra && extra.custSysId) ? 1 : 0);
        var entry = liveCache[key];
        if (entry && entry.result) { done(entry.result); return; }
        if (entry && entry.waiters) { entry.waiters.push(done); return; }

        entry = liveCache[key] = { waiters: [done], result: null };
        var req = angular.extend({ action: 'fetch_live', code: code, salesOrg: salesOrg || '' }, extra || {});

        function finish(res, cacheIt) {
            var w = entry.waiters || [];
            entry.waiters = null;
            if (cacheIt) entry.result = res; else delete liveCache[key];
            w.forEach(function(fn) { fn(res); });
        }

        c.server.get(req).then(function(r) {
            finish(r.data.liveData || { limit: 0, bg: 0, activeBg: 0, bgExpiry: '', nod: 0 }, true);
        }, function() {
            finish({ limit: 0, bg: 0, activeBg: 0, bgExpiry: '', nod: 0 }, false);
        });
    };

    c.loadNodeLive = function(node) {
        node.loading = true;
        node.live = false;
        c.fetchLive(node.code, node.salesOrg, null, function(res) {
            node.limit = res.limit; node.bg = res.bg; node.activeBg = res.activeBg;
            node.loading = false; node.live = true;
        });
    };

    // ---------- group code dropdown tree (shared by Step 1 / 3 / 4) ----------
    // Row kinds: G = group code row, S = site row, ZT = zone total row.
    // An open group shows every zone of the group: its site rows, then the zone total row.
    // The first row under a group carries gFirst/gSpan (group blank cell), the first row of a zone
    // carries zFirst/zSpan (zone cell spanning its sites and its total row).
    // r.level is the level used by the rv* helpers of Step 4 (G / Z / S).
    function treeRows(q, flag) {
        var rows = [];
        var ov = c.data.gpOverview;
        var ql = (q || '').toString().toLowerCase().trim();
        if (!ov || !ov.groups) return rows;

        ov.groups.forEach(function(g) {
            if (ql && (g.code || '').toString().toLowerCase().indexOf(ql) === -1) return;
            var open = !!g[flag];
            rows.push({ key: 'G' + g.code, kind: 'G', level: 'G', node: g, gcode: g.code, open: open });
            if (!open) return;

            var first = rows.length;
            g.zonals.forEach(function(z) {
                var zStart = rows.length;
                z.sites.forEach(function(s) {
                    rows.push({ key: 'S' + g.code + '|' + z.code + '|' + s.code, kind: 'S', level: 'S', node: s, znode: z, gcode: g.code });
                });
                rows.push({ key: 'T' + g.code + '|' + z.code, kind: 'ZT', level: 'Z', node: z, znode: z, gcode: g.code });
                rows[zStart].zFirst = true;
                rows[zStart].zSpan = rows.length - zStart;
            });
            if (rows.length > first) {
                rows[first].gFirst = true;
                rows[first].gSpan = rows.length - first;
            }
        });
        return rows;
    }

    // live limit / BG for every zonal parent and site of a group (needed once the group is opened)
    function loadGroupLive(g) {
        g.zonals.forEach(function(z) {
            if (!z.live && !z.loading) c.loadNodeLive(z);
            z.sites.forEach(function(s) { if (!s.live && !s.loading) c.loadNodeLive(s); });
        });
    }

    var TREE_KINDS = {
        hier: { flag: 'expanded',   live: true },
        ep:   { flag: 'epExpanded', live: false },
        rev:  { flag: 'rExpanded',  live: true }
    };

    function treeGroups() {
        return (c.data.gpOverview && c.data.gpOverview.groups) || [];
    }

    function treeRebuild(kind) {
        if (kind === 'hier') c.rebuildHier();
        else if (kind === 'ep') c.rebuildEp(false);
        else c.rebuildRev();
    }

    // true when at least one group of the table is open (button shows "Collapse all", else "Expand all")
    c.treeAnyOpen = function(kind) {
        var flag = TREE_KINDS[kind].flag, any = false;
        treeGroups().forEach(function(g) { if (g[flag]) any = true; });
        return any;
    };

    c.treeToggleAll = function(kind) {
        var t = TREE_KINDS[kind];
        var open = !c.treeAnyOpen(kind);
        treeGroups().forEach(function(g) {
            g[t.flag] = open;
            if (open && t.live) loadGroupLive(g);
        });
        treeRebuild(kind);
    };

    // ---------- Grandparent overview / hierarchy (step 1) ----------
    c.rebuildHier = function() {
        c.data.hierRows = treeRows(c.tree.hier.q, 'expanded');
    };

    c.toggleGroup = function(g) {
        g.expanded = !g.expanded;
        if (g.expanded) loadGroupLive(g);
        c.rebuildHier();
    };

    c.loadOverview = function(gp) {
        c.data.gpOverview = null;
        c.data.hierRows = [];
        c.data.overviewError = '';
        c.data.gpLive = { loading: true, limit: 0, bg: 0, activeBg: 0 };
        c.data.overviewLoading = true;

        c.server.get({ action: 'fetch_gp_overview', gpCode: gp }).then(function(r) {
            if (c.data.selectedGPCode !== gp) return;
            c.data.overviewLoading = false;

            if (r.data.error) {
                c.data.overviewError = r.data.error;
                c.data.gpLive.loading = false;
                return;
            }
            var ov = r.data.gpOverview;
            c.data.gpOverview = ov;

            c.fetchLive(gp, ov.salesOrg, null, function(res) {
                c.data.gpLive = { loading: false, limit: res.limit, bg: res.bg, activeBg: res.activeBg };
            });

            ov.groups.forEach(function(g) {
                g.expanded = false;
                c.loadNodeLive(g);
            });
            c.rebuildHier();
            if (c.data.activeDraft) c.recalculate(true);
        }, function() {
            c.data.overviewLoading = false;
            c.data.gpLive.loading = false;
            c.data.overviewError = 'Server request failed while loading the grandparent summary.';
        });
    };

    // ---------- GP / group selection ----------
    c.loadGroupsForGP = function() {
        c.data.selectedGroupCode = '';
        c.data.distinctGroupCodes = null;
        c.data.activeDraft = null;
        c.data.loadError = '';
        c.data.lockWarning = '';
        c.allSelected = false;
        c.data.isFetchingGroups = true;
        c.data.gpOverview = null;
        c.data.hierRows = [];
        c.data.overviewError = '';
        c.tree.hier.q = '';
        c.tree.ep.q = '';
        c.tree.rev.q = '';

        if (c.data.selectedGPCode) {
            c.loadOverview(c.data.selectedGPCode);
            c.server.get({ action: 'fetch_draft_groups', gpCode: c.data.selectedGPCode }).then(function(r) {
                c.data.distinctGroupCodes = r.data.distinctGroupCodes || [];
                c.data.isFetchingGroups = false;
            });
        } else {
            c.data.distinctGroupCodes = [];
            c.data.isFetchingGroups = false;
        }
    };

    c.loadDraftDetails = function() {
        c.allSelected = false;
        c.data.businessJustification = '';
        c.data.deviationJustification = '';
        c.data.reviewConfirmed = false;
        c.data.activeDraft = null;
        c.data.loadError = '';
        c.data.lockWarning = '';
        c.data.localSearch = '';
        c.data.currentPage = 1;

        if (!c.data.selectedGroupCode || !c.data.selectedGPCode) return;

        c.data.loadingSites = true;

        c.server.get({
            action: 'load_draft_by_group',
            gpCode: c.data.selectedGPCode,
            groupCode: c.data.selectedGroupCode
        }).then(function(r) {
            c.data.loadingSites = false;

            if (r.data.error) {
                c.data.loadError = r.data.error;
                c.data.activeDraft = null;
                return;
            }

            c.data.activeDraft = r.data.draftDetails || null;
            if (r.data.groupedParameters) c.data.tw.groupedParameters = r.data.groupedParameters;

            if (c.data.activeDraft && c.data.activeDraft.sites && c.data.activeDraft.sites.length > 0) {
                c.data.activeDraft.sites.forEach(function(s) {
                    s.selected = false;
                    s.expanded = false;
                    s.limit = 0; s.bg = 0; s.activeBg = 0; s.bgExpiry = ''; s.nod = 0;
                    s.isLiveLoading = true;
                    c.fetchLive(s.site_code, s.salesorg, {
                        custSysId: s.cust_sys_id,
                        segment: s.segment,
                        outstanding: s.outstanding,
                        bgExpiryRaw: s.bg_expiry_raw
                    }, function(res) {
                        s.limit = res.limit; s.bg = res.bg; s.activeBg = res.activeBg;
                        s.bgExpiry = res.bgExpiry; s.nod = res.nod;
                        s.isLiveLoading = false;
                    });
                });
            }
        }, function() {
            c.data.loadingSites = false;
            c.data.loadError = 'Server request failed while loading sites.';
        });
    };

    // ---------- site table (step 1) ----------
    // A site is selectable only if it is not locked and is either a Pending SPOC CRM draft or has no CRM draft.
    // Locked = under a pending limit swap or inside an open request, either on the site itself or (Grandparent-level
    // lock) on any other site of the same Grandparent Code.
    c.isSelectable = function(site) {
        if (site.swap_locked || site.req_locked) return false;
        return site.status !== 'Processed';
    };

    c.getLockedSites = function() {
        var s = (c.data.activeDraft && c.data.activeDraft.sites) || [];
        return s.filter(function(x) { return x.swap_locked || x.req_locked; });
    };

    c.showLockWarning = function(site) {
        var gp = c.data.selectedGPCode;
        if (site.swap_locked) {
            if (site.gp_swap_lock) {
                c.data.lockWarning = 'A Limit Swap (' + site.swap_ref + ') is in progress for site ' + site.swap_site +
                    ' under Grandparent ' + gp + '. No request can be raised for any site of this Grandparent until the swap is Approved, Rejected or Returned.';
            } else {
                c.data.lockWarning = 'Site ' + site.site_code + ' is the ' + (site.swap_role === 'donor' ? 'DONOR' : 'DONEE') +
                    ' in an active Limit Swap request (' + site.swap_ref + '). No request can be raised for any site of Grandparent ' + gp +
                    ' until the swap is Approved, Rejected or Returned.';
            }
        } else if (site.gp_req_lock) {
            c.data.lockWarning = 'Request ' + site.req_ref + (site.req_group ? ' (Group ' + site.req_group + ')' : '') +
                ' is in process under Grandparent ' + gp + '. No new request can be raised for any site of this Grandparent until it is Approved, Rejected or Returned.';
        } else {
            c.data.lockWarning = 'Site ' + site.site_code + ' is already part of an open request (' + site.req_ref +
                '). No new request can be raised for any site of Grandparent ' + gp + ' until it is Approved, Rejected or Returned.';
        }
        $timeout(function() { c.data.lockWarning = ''; }, 10000);
    };

    c.getSelectableSites = function() {
        if (!c.data.activeDraft || !c.data.activeDraft.sites) return [];
        return c.data.activeDraft.sites.filter(function(s) { return c.isSelectable(s); });
    };

    c.isAnySiteLoading = function() {
        return !!(c.data.activeDraft && c.data.activeDraft.sites && c.data.activeDraft.sites.some(function(s) { return s.isLiveLoading; }));
    };

    c.getFilteredSites = function() {
        if (!c.data.activeDraft || !c.data.activeDraft.sites) return [];
        var q = (c.data.localSearch || '').toLowerCase();
        if (!q) return c.data.activeDraft.sites;
        return c.data.activeDraft.sites.filter(function(s) {
            return (s.customer_name || '').toLowerCase().indexOf(q) !== -1 ||
                   (s.site_code || '').toLowerCase().indexOf(q) !== -1 ||
                   (s.zonal_parent_code || '').toLowerCase().indexOf(q) !== -1;
        });
    };

    c.getPaginatedSites = function() {
        var f = c.getFilteredSites();
        var start = (c.data.currentPage - 1) * c.data.itemsPerPage;
        return f.slice(start, start + c.data.itemsPerPage);
    };

    c.totalPages = function() {
        return Math.ceil(c.getFilteredSites().length / c.data.itemsPerPage) || 1;
    };

    c.toggleSiteAgeing = function(s) {
        s.expanded = !s.expanded;
        if (s.expanded && !s.buckets && s.cust_sys_id) {
            s.bucketsLoading = true;
            c.server.get({ action: 'fetch_buckets', custSysId: s.cust_sys_id }).then(function(r) {
                s.buckets = r.data.buckets || [];
                s.bucketsLoading = false;
            }, function() {
                s.buckets = [];
                s.bucketsLoading = false;
            });
        }
    };

    c.toggleAllSites = function() {
        if (c.data.activeDraft && c.data.activeDraft.sites) {
            c.data.activeDraft.sites.forEach(function(s) {
                if (c.isSelectable(s)) s.selected = c.allSelected;
            });
        }
    };

    c.rowClick = function(site) {
        if (site.swap_locked || site.req_locked) { c.showLockWarning(site); return; }
        if (c.isSelectable(site)) {
            site.selected = !site.selected;
            c.updateSelection();
        }
    };

    c.updateSelection = function() {
        var selectable = c.getSelectableSites();
        var total = selectable.length;
        var selectedCount = selectable.filter(function(s) { return s.selected; }).length;
        c.allSelected = (total > 0 && selectedCount === total);
    };

    c.getSelectedSites = function() {
        return c.getSelectableSites().filter(function(s) { return s.selected; });
    };

    c.hasNoDraftSelected = function() {
        return c.getSelectedSites().some(function(s) { return s.status === 'No CRM Draft'; });
    };

    // live Group Code values (from the hierarchy summary) of the selected group
    c.getGroupLive = function() {
        var gsel = up(c.data.selectedGroupCode), n = null;
        ((c.data.gpOverview && c.data.gpOverview.groups) || []).forEach(function(g) { if (up(g.code) === gsel) n = g; });
        return n ? { limit: n.limit || 0, activeBg: n.activeBg || 0 } : { limit: 0, activeBg: 0 };
    };

    // true once the live Group Code and Grandparent values have been loaded
    c.isLiveReady = function() {
        var gsel = up(c.data.selectedGroupCode), ok = false;
        ((c.data.gpOverview && c.data.gpOverview.groups) || []).forEach(function(g) { if (up(g.code) === gsel && g.live) ok = true; });
        return ok && !c.data.gpLive.loading;
    };

    // live zonal values (from the hierarchy summary) for every zonal parent among the selected sites.
    // Used by the server only as a fallback when its own live call fails.
    c.getZonalPayload = function() {
        var out = [], seen = {};
        var grpCode = up(c.data.selectedGroupCode);
        var groups = (c.data.gpOverview && c.data.gpOverview.groups) || [];

        c.getSelectedSites().forEach(function(s) {
            var zc = s.zonal_parent_code;
            if (!zc || zc === '-' || seen[zc]) return;
            seen[zc] = true;

            var node = null;
            groups.forEach(function(g) {
                if (node) return;
                if (up(g.code) !== grpCode) return;
                g.zonals.forEach(function(z) { if (!node && z.code === zc) node = z; });
            });
            if (!node) {
                groups.forEach(function(g) {
                    g.zonals.forEach(function(z) { if (!node && z.code === zc) node = z; });
                });
            }
            out.push({
                code: zc,
                salesOrg: node ? node.salesOrg : '',
                limit: node && node.live ? node.limit : 0,
                bg: node && node.live ? node.bg : 0,
                activeBg: node && node.live ? node.activeBg : 0
            });
        });
        return out;
    };

    // ---------- step navigation ----------
    c.goToEditor = function() {
        if (c.getSelectedSites().length === 0) return;
        c.getSelectedSites().forEach(function(s) {
            var t = s.credit_tenor;
            if (t === null || t === undefined || t === '' || isNaN(Number(t))) {
                s.credit_tenor = DEFAULT_CREDIT_TENOR;
            }
        });
        c.data.currentStep = 2;
        c.recalculate(true);
        scrollToTop();
    };

    c.goBack = function() { c.data.currentStep = 1; scrollToTop(); };

    c.goToProjections = function() { c.data.currentStep = 2; scrollToTop(); };

    c.isDocReady = function() {
        var t = c.data.tw.documentType;
        if (!t) return false;
        if (t === 'No Document') return true;
        return !!c.data.tw.fileName;
    };

    c.canProceedToRisk = function() {
        return !c.hasValidationErrors() && c.isDocReady() &&
               !!(c.data.businessJustification && c.data.businessJustification.trim());
    };

    c.goToRisk = function() {
        if (!c.canProceedToRisk()) return;
        c.ensureSegmentParams();
        c.recalculate(true);
        c.rebuildEp(true);
        c.applyDefaults();
        c.data.currentStep = 3;
        scrollToTop();
    };

    // risk parameters are not mandatory (unselected ones get the lowest default).
    c.canProceedToReview = function() {
        if (c.data.tw.ocrProcessing) return false;
        if (c.getTotalParamsCount() === 0) return false;
        if (!c.isLiveReady()) return false;
        return true;
    };

    c.goToReview = function() {
        if (!c.canProceedToReview()) return;
        c.computeGpMacl();
        c.resetMaclPaging();
        c.computeP2();
        c.buildReviewData();
        c.data.reviewConfirmed = false;
        c.data.currentStep = 4;
        scrollToTop();
    };

    c.backToEdit = function() {
        if (c.data.submitting) return;
        c.data.currentStep = 3;
        scrollToTop();
    };

    // ---------- field validation ----------
    var SITE_FIELDS = [
        { key: 'monthly_potential',  label: 'Monthly Potential' },
        { key: 'current_potential',  label: 'Current Potential' },
        { key: 'expected_potential', label: 'Expected Potential' },
        { key: 'order_rate',         label: 'Order Rate' },
        { key: 'credit_tenor',       label: 'Credit Tenor' },
        { key: 'requested_limit',    label: 'Desired Limit' }
    ];

    c.fieldError = function(site, key) {
        var v = site[key];
        if (v === null || v === undefined || v === '') return 'Required';
        var n = Number(v);
        if (isNaN(n)) return 'Invalid number';
        if (n <= 0) return 'Must be greater than 0';
        if (key === 'current_potential' || key === 'expected_potential') {
            var mp = Number(site.monthly_potential);
            if (!isNaN(mp) && mp > 0 && n > mp) return 'Cannot exceed Monthly Potential (' + mp + ')';
        }
        return '';
    };

    c.getValidationErrors = function() {
        var errs = [];
        c.getSelectedSites().forEach(function(s) {
            SITE_FIELDS.forEach(function(f) {
                var m = c.fieldError(s, f.key);
                if (m) errs.push(s.site_code + ' – ' + f.label + ': ' + m);
            });
        });
        return errs;
    };

    c.hasValidationErrors = function() { return c.getValidationErrors().length > 0; };

    c.siteNetExposure = function(s) {
        return (parseFloat(s.requested_limit) || 0) - (parseFloat(s.activeBg) || 0);
    };

    // ---------- grandparent level data (all sites under the GP) ----------
    // Sites in the request -> values entered in Step 2 (CRM value, else master), current CL = live site limit, updated CL = requested limit.
    // All other sites -> last approved SPOC value, else customer master, else 0 (resolved on the server).
    // Their current / updated CL are fetched live on demand (see ensureMaclLive).
    c.getEffectiveRows = function() {
        var sel = {}, rows = [], seen = {};
        c.getSelectedSites().forEach(function(s) { sel[s.site_code] = s; });
        var ov = c.data.gpOverview;

        if (ov && ov.groups) {
            ov.groups.forEach(function(g) {
                g.zonals.forEach(function(z) {
                    z.sites.forEach(function(s) {
                        var sl = sel[s.code];
                        var inp = s.inp || {};
                        seen[s.code] = true;
                        rows.push({
                            code: s.code, name: s.name, group: g.code, zonal: z.code,
                            segment: s.segment, seg: segKey(s.segment), inReq: !!sl,
                            salesOrg: s.salesOrg || '',
                            curCl: sl ? num(sl.limit) : null,
                            updCl: sl ? num(sl.requested_limit) : null,
                            monthly:  sl ? num(sl.monthly_potential)  : num(inp.monthly),
                            current:  sl ? num(sl.current_potential)  : num(inp.current),
                            expected: sl ? num(sl.expected_potential) : num(inp.expected),
                            rate:     sl ? num(sl.order_rate)         : num(inp.rate),
                            tenor:    sl ? num(sl.credit_tenor)       : num(inp.tenor),
                            src: sl ? 'Request' : (inp.src || 'None'),
                            zTxt: sl ? c.locText(sl.zone_name, sl.zone_code) : '',
                            rTxt: sl ? c.locText(sl.region_name, sl.region_code) : '',
                            dTxt: sl ? c.locText(sl.depot_name, sl.depot_code) : ''
                        });
                    });
                });
            });
        }
        // safety: selected sites that are not part of the overview
        c.getSelectedSites().forEach(function(sl) {
            if (seen[sl.site_code]) return;
            rows.push({
                code: sl.site_code, name: sl.customer_name, group: sl.group_code, zonal: sl.zonal_parent_code,
                segment: sl.segment, seg: segKey(sl.segment), inReq: true,
                salesOrg: sl.salesorg || '',
                curCl: num(sl.limit), updCl: sl ? num(sl.requested_limit) : null,
                monthly: num(sl.monthly_potential), current: num(sl.current_potential), expected: num(sl.expected_potential),
                rate: num(sl.order_rate), tenor: num(sl.credit_tenor), src: 'Request',
                zTxt: c.locText(sl.zone_name, sl.zone_code), rTxt: c.locText(sl.region_name, sl.region_code), dTxt: c.locText(sl.depot_name, sl.depot_code)
            });
        });
        return rows;
    };

    // P1 at GP level = sum over every site of: expected x its own rate x (its own tenor / 30). Also segment-wise breakdown.
    c.computeGpMacl = function() {
        var rows = c.getEffectiveRows();
        var groups = {}, order = [], segAgg = {};
        var totalExpected = 0, totalMacl = 0;

        rows.forEach(function(r) {
            var tenorUsed = r.tenor > 0 ? r.tenor : DEFAULT_CREDIT_TENOR;   // only when the site has no tenor anywhere
            r.tenorUsed = tenorUsed;
            r.macl = r.expected * r.rate * (tenorUsed / 30.0);

            var sk = r.seg || 'Other';
            var sa = segAgg[sk] || (segAgg[sk] = { segment: sk, unit: sk === 'RMC' ? 'CuM' : 'MT', qty: 0, macl: 0, sites: 0 });
            sa.qty += r.expected; sa.macl += r.macl; sa.sites++;

            var k = r.group || '-';
            if (!groups[k]) { groups[k] = { code: k, sites: [], expected: 0, macl: 0, inReq: 0 }; order.push(k); }
            var g = groups[k];
            g.sites.push(r);
            g.expected += r.expected;
            g.macl += r.macl;
            if (r.inReq) g.inReq++;

            totalExpected += r.expected;
            totalMacl += r.macl;
        });

        var groupList = order.map(function(k) { return groups[k]; });

        c.data.gpMacl = {
            groups: groupList,
            siteCount: rows.length,
            totalExpected: totalExpected,
            unit: c.getQtyUnit(),
            macl: totalMacl,
            segments: Object.keys(segAgg).map(function(k) { return segAgg[k]; })
        };
        c.data.p1Breakdown = c.data.gpMacl.segments;
        return c.data.gpMacl;
    };

    // ---------- step 4: MACL table (Requested sites / All sites) ----------
    c.getMaclCounts = function() {
        var n = 0, req = 0;
        ((c.data.gpMacl && c.data.gpMacl.groups) || []).forEach(function(g) { n += g.sites.length; req += g.inReq; });
        return { all: n, requested: req };
    };

    c.setMaclScope = function(scope) {
        c.macl.scope = scope;
        c.macl.page = 1;
    };

    // current / updated CL for sites that are not in the request: live SAP limit (updated = current, nothing changes)
    c.ensureMaclLive = function(r) {
        if (r.inReq || r.curLoading) return;
        if (r.curCl !== null && r.curCl !== undefined) return;
        r.curLoading = true;
        c.fetchLive(r.code, r.salesOrg, null, function(res) {
            r.curCl = num(res.limit);
            r.updCl = num(res.limit);
            r.curLoading = false;
        });
    };

    // total current / updated CL of the rows in the chosen scope; ready = false until every row has its live value
    c.getMaclLimitTotals = function() {
        var scope = c.macl.scope === 'all' ? 'all' : 'requested';
        var cur = 0, upd = 0, ready = true;
        ((c.data.gpMacl && c.data.gpMacl.groups) || []).forEach(function(g) {
            g.sites.forEach(function(r) {
                if (scope !== 'all' && !r.inReq) return;
                if (r.curCl === null || r.curCl === undefined) { ready = false; return; }
                cur += num(r.curCl);
                upd += num(r.updCl);
            });
        });
        return { cur: cur, upd: upd, ready: ready };
    };
    // current / updated CL of one Group Code in the MACL table (sum of its sites in the chosen scope)
    c.maclGroupLimits = function(g) {
        var cur = 0, upd = 0, ready = true;
        (g.rows || []).forEach(function(r) {
            if (r.curCl === null || r.curCl === undefined) { ready = false; return; }
            cur += num(r.curCl);
            upd += num(r.updCl);
        });
        return { cur: cur, upd: upd, ready: ready };
    };

    // One page of MACL rows, regrouped by Group Code, for the chosen scope.
    c.getMaclPage = function() {
        var src = c.data.gpMacl;
        var all = (src && src.groups) || [];
        var scope = c.macl.scope === 'all' ? 'all' : 'requested';
        var q = (c.macl.search || '').toLowerCase().trim();
        var size = parseInt(c.macl.size, 10) || 10;
        var key = [c.macl.page, size, q, scope].join('|');
        if (maclView.src === src && maclView.key === key) return maclView;

        var totals = { sites: 0, expected: 0, macl: 0 };
        var scoped = [];
        all.forEach(function(g) {
            var rows = scope === 'all' ? g.sites : g.sites.filter(function(r) { return r.inReq; });
            if (!rows.length) return;
            var sg = { code: g.code, rows: rows, inReq: 0, expected: 0, macl: 0 };
            rows.forEach(function(r) {
                if (r.inReq) sg.inReq++;
                sg.expected += num(r.expected);
                sg.macl     += num(r.macl);
            });
            totals.sites += rows.length; totals.expected += sg.expected; totals.macl += sg.macl;
            rows.forEach(function(rr) { c.ensureMaclLive(rr); });   // live limit of every site in scope
            scoped.push(sg);
        });

        var flat = [];
        scoped.forEach(function(g) {
            g.rows.forEach(function(r) {
                if (!q || (r.name || '').toLowerCase().indexOf(q) !== -1 || (r.code || '').toLowerCase().indexOf(q) !== -1) {
                    flat.push({ g: g, r: r });
                }
            });
        });

        var pages = Math.max(1, Math.ceil(flat.length / size));
        if (c.macl.page > pages) c.macl.page = pages;
        if (c.macl.page < 1) c.macl.page = 1;

        var startIdx = (c.macl.page - 1) * size;
        var groups = [];
        flat.slice(startIdx, startIdx + size).forEach(function(item) {
            var last = groups[groups.length - 1];
            if (!last || last.full !== item.g) {
                last = { code: item.g.code, full: item.g, rows: [] };
                groups.push(last);
            }
            last.rows.push(item.r);
            c.ensureMaclLive(item.r);   // load the live limit of the rows on this page
        });

        maclView.src    = src;
        maclView.key    = [c.macl.page, size, q, scope].join('|');
        maclView.groups = groups;
        maclView.totals = totals;
        maclView.total  = flat.length;
        maclView.pages  = pages;
        maclView.start  = flat.length ? startIdx + 1 : 0;
        maclView.end    = Math.min(startIdx + size, flat.length);
        return maclView;
    };

    c.maclGo = function(p) {
        var pages = c.getMaclPage().pages;
        c.macl.page = Math.min(Math.max(1, p), pages);
    };

    c.resetMaclPaging = function() {
        c.macl.page = 1; c.macl.size = 10; c.macl.search = ''; c.macl.scope = 'requested';
        maclView.key = null;
    };

    // segment metrics at GP level for a given segment (default: the selected group's segment)
    c.getSegMetrics = function(segArg) {
        var seg = (segArg !== undefined) ? segArg : c.getGpSelectedSegment();
        var pot = 0, cur = 0, mon = 0;
        c.getEffectiveRows().forEach(function(r) {
            if (seg && r.seg !== seg) return;
            pot += r.expected; cur += r.current; mon += r.monthly;
        });
        return { potential: pot, sharePct: mon > 0 ? Math.round((cur / mon) * 1000) / 10 : 0 };
    };

    // ---------- step 3: group code wise expected potential ----------
    c.rebuildEp = function(init) {
        var ov = c.data.gpOverview;
        var totExp = 0, totReq = 0;
        var eff = {};
        c.getEffectiveRows().forEach(function(r) { eff[r.group + '|' + r.zonal + '|' + r.code] = r; });
        var gsel = up(c.data.selectedGroupCode);

        if (ov && ov.groups) {
            ov.groups.forEach(function(g) {
                g.epExp = 0; g.epReq = 0;
                if (init) g.epExpanded = (up(g.code) === gsel);
                g.zonals.forEach(function(z) {
                    z.epExp = 0; z.epReq = 0;
                    z.sites.forEach(function(s) {
                        var r = eff[g.code + '|' + z.code + '|' + s.code] || {};
                        s.epExp = num(r.expected);
                        s.epReq = r.inReq ? 1 : 0;
                        z.epExp += s.epExp; z.epReq += s.epReq;
                    });
                    g.epExp += z.epExp; g.epReq += z.epReq;
                });
                totExp += g.epExp; totReq += g.epReq;
            });
        }
        c.data.epRows = treeRows(c.tree.ep.q, 'epExpanded');
        c.data.epTotals = { exp: totExp, req: totReq };
    };

    c.toggleEpGroup = function(g) { g.epExpanded = !g.epExpanded; c.rebuildEp(false); };

    // ---------- step 4: review data ----------
    function selUnder(r) {
        var sel = c.getSelectedSites();
        var gc = up(r.gcode);
        if (r.level === 'S') return sel.filter(function(s) { return s.site_code === r.node.code && up(s.group_code) === gc; });
        if (r.level === 'Z') return sel.filter(function(s) { return s.zonal_parent_code === r.node.code && up(s.group_code) === gc; });
        return sel.filter(function(s) { return up(s.group_code) === up(r.node.code); });
    }
    function sum(arr, key) { return arr.reduce(function(t, s) { return t + num(s[key]); }, 0); }
    // sum of the current site limits that this request replaces (SAP placeholder limit counts as nil)
    function sumEff(arr) { return arr.reduce(function(t, s) { return t + c.effLimit(s.limit); }, 0); }

    c.rebuildRev = function() {
        c.data.revRows = treeRows(c.tree.rev.q, 'rExpanded');
    };

    c.toggleRevGroup = function(g) {
        g.rExpanded = !g.rExpanded;
        if (g.rExpanded) loadGroupLive(g);
        c.rebuildRev();
    };

    c.rvInReq = function(r) { return r.level === 'S' && selUnder(r).length > 0; };

    // number of requested sites under a group / zone / site row ("N requested" chip)
    c.rvReqCount = function(r) { return selUnder(r).length; };

    c.rvCur = function(r) {
        if (r.level === 'S') { var s = selUnder(r); if (s.length) return num(s[0].limit); }
        return num(r.node.limit);
    };

    c.rvBg = function(r) {
        if (r.level === 'S') { var s = selUnder(r); if (s.length) return num(s[0].activeBg); }
        return num(r.node.activeBg);
    };

    // ---- Updated CL = sum of the updated CL of the sites below ----
    // requested site -> requested limit ; non-requested site -> its current live limit
    function reqSiteOf(code, gc) {
        var f = null;
        c.getSelectedSites().forEach(function(s) {
            if (!f && s.site_code === code && up(s.group_code) === up(gc)) f = s;
        });
        return f;
    }
    function siteUpd(s, gc) {
        var q = reqSiteOf(s.code, gc);
        return q ? num(q.requested_limit) : num(s.limit);
    }
    function siteReady(s, gc) { return !!reqSiteOf(s.code, gc) || !!s.live; }
    function sitesOfRow(r) {
        if (r.level === 'S') return [r.node];
        if (r.level === 'Z') return r.node.sites;
        var out = [];
        r.node.zonals.forEach(function(z) { out = out.concat(z.sites); });
        return out;
    }

    // a row is ready when its own live limit and the live limit of every site below it are loaded
    c.rvReady = function(r) {
        if (r.level === 'S') return siteReady(r.node, r.gcode);
        return !!r.node.live && sitesOfRow(r).every(function(s) { return siteReady(s, r.gcode); });
    };

    c.rvUpd = function(r) {
        return sitesOfRow(r).reduce(function(t, s) { return t + siteUpd(s, r.gcode); }, 0);
    };

    // Grandparent updated limit = sum of the updated CL of ALL sites under the Grandparent
    c.rvGpUpdated = function() {
        var t = 0, ov = c.data.gpOverview;
        if (ov && ov.groups) ov.groups.forEach(function(g) {
            g.zonals.forEach(function(z) { z.sites.forEach(function(s) { t += siteUpd(s, g.code); }); });
        });
        return t;
    };

    // updated limit of the selected Group Code (sum of its sites)
    c.rvGroupUpdated = function() {
        var t = 0, gsel = up(c.data.selectedGroupCode), ov = c.data.gpOverview;
        if (ov && ov.groups) ov.groups.forEach(function(g) {
            if (up(g.code) !== gsel) return;
            g.zonals.forEach(function(z) { z.sites.forEach(function(s) { t += siteUpd(s, g.code); }); });
        });
        return t;
    };

    // true when the live limit of every site under the Grandparent is loaded
    c.rvGpReady = function() {
        if (c.data.gpLive.loading) return false;
        var ok = true, ov = c.data.gpOverview;
        if (!ov || !ov.groups) return false;
        ov.groups.forEach(function(g) {
            g.zonals.forEach(function(z) { z.sites.forEach(function(s) { if (!siteReady(s, g.code)) ok = false; }); });
        });
        return ok;
    };

    c.CREDIT_GROUPS = [
        { key: 'safe', label: '0 – 60 Days' },
        { key: 'warn', label: '61 – 90 Days' },
        { key: 'risk', label: 'Above 90 Days' }
    ];
    c.bucketsIn = function(groupKey) {
        return (c.getCredit().buckets || []).filter(function(b) { return b.group === groupKey; });
    };

    function optionOf(p) {
        var o = null;
        (p.options || []).forEach(function(x) { if (x.sys_id === p.selectedValue) o = x; });
        return o;
    }
    function statusOf(p) {
        return p.isChanged ? 'over' : (p.isDefault ? 'default' : (p.autoMapped && p.mappingType === 'AI' ? 'ai' : (p.autoMapped && p.mappingType === 'Input' ? 'input' : 'manual')));
    }
    function compRow(p, label, wPct) {
        var opt = optionOf(p);
        var score = opt ? num(opt.score) : 0;
        return { name: label, label: opt ? opt.label : '—', src: p.extractedValue, score: score, wPct: wPct, pts: score * wPct / 10, status: statusOf(p) };
    }

    // Composite index (P2) review:
    //  1. Common parameters (Grandparent level) -> "Common Points (all segments)". Segment Potential / SOB are NOT in here.
    //  2. Segment parameters (Current SOB % and Potential) per segment.
    //  3. Grandparent composite index = composite index of each segment x its share of (segment MPQ x average order rate).
    c.buildReviewData = function() {
        var ov = c.data.gpOverview;
        var gsel = up(c.data.selectedGroupCode);
        var sel = c.getSelectedSites();

        if (ov && ov.groups) {
            ov.groups.forEach(function(g) {
                var isSel = (up(g.code) === gsel);
                g.rExpanded = isSel;
                g.zonals.forEach(function(z) {
                    var has = isSel && sel.some(function(s) { return s.zonal_parent_code === z.code; });
                    z.rExpanded = has;
                    // every zonal parent and site is loaded live: the updated limits are sums of the site limits
                    if (!z.live && !z.loading) c.loadNodeLive(z);
                    z.sites.forEach(function(s) { if (!s.live && !s.loading) c.loadNodeLive(s); });
                });
            });
        }
        c.rebuildRev();

        // 1. common parameters (segment level parameters are scored per segment below)
        var groups = [], commonPts = 0, commonW = 0;
        c.getParamGroups().forEach(function(g) {
            var rows = [], gw = 0, gp = 0;
            g.params.forEach(function(p) {
                if (isSegParam(p)) return;
                var wPct = num(p.weight) * 100;
                var row = compRow(p, c.paramLabel(p), wPct);
                rows.push(row);
                gw += wPct; gp += row.pts;
            });
            if (!rows.length) return;
            groups.push({ label: g.label, wPct: gw, pts: gp, rows: rows });
            commonPts += gp; commonW += gw;
        });

        // 2. segment parameters
        var selSeg = c.getGpSelectedSegment() || 'Segment';
        var segMap = {};
        angular.forEach(c.data.tw.groupedParameters, function(arr) {
            arr.forEach(function(p) {
                var seg, kind;
                if (p.extraSeg) { seg = p.seg; kind = p.baseKey; }
                else if (p.k === 'segment_potential' || p.k === 'current_share') { seg = selSeg; kind = p.k; }
                else return;
                if (!segMap[seg]) segMap[seg] = {};
                segMap[seg][kind] = p;
            });
        });
        var segNames = Object.keys(segMap).sort(function(a, b) {
            var ia = SEGMENT_ORDER.indexOf(a), ib = SEGMENT_ORDER.indexOf(b);
            if (ia === -1) ia = 99;
            if (ib === -1) ib = 99;
            return ia - ib;
        });

        var segRows = [], segments = [];
        segNames.forEach(function(seg) {
            var unit = seg === 'RMC' ? 'CuM' : 'MT';
            var list = [];
            [['current_share', 'Current SOB %'], ['segment_potential', 'Potential']].forEach(function(def) {
                var p = segMap[seg][def[0]];
                if (!p) return;
                var baseW = (p.baseWeight !== undefined ? p.baseWeight : p.weight);
                var row = compRow(p, def[1], num(baseW) * 100);
                row.segment = seg; row.unit = unit;
                list.push(row);
            });
            var segPts = 0;
            list.forEach(function(r, i) { r.first = (i === 0); r.span = list.length; segPts += r.pts; segRows.push(r); });
            var index = commonPts + segPts;
            segments.push({ segment: seg, unit: unit, index: index, commonPts: commonPts, segPts: segPts, share: 0, contrib: 0 });
        });

        // 3. weights = segment MPQ x average order rate (FRS)
        var fwts = c.segmentFinancialWeights(), totFw = 0;
        segments.forEach(function(s) {
            var f = fwts[s.segment];
            s.mpq = f ? f.mpq : 0; s.rate = f ? f.rate : 0; s.fw = f ? f.weight : 0;
            totFw += s.fw;
        });
        segments.forEach(function(s) {
            s.share = totFw > 0 ? (s.fw / totFw) * 100 : (100 / (segments.length || 1));
            s.contrib = s.index * s.share / 100;
        });
        c.data.p2Breakdown = segments.map(function(s) {
            return { segment: s.segment, index: s.index, mpq: s.mpq, avg_rate: s.rate, weight_share: s.share };
        });

        c.data.revComposite = {
            common: { groups: groups, wPct: commonW, pts: commonPts },
            segRows: segRows,
            segments: segments,
            totalContrib: segments.reduce(function(t, s) { return t + s.contrib; }, 0)
        };
    };

    c.getTotals = function() {
        var t = { monthly: 0, current: 0, expected: 0, limit: 0, p1: 0, currentCl: 0, activeBg: 0, netExposure: 0 };
        c.getSelectedSites().forEach(function(s) {
            t.monthly   += parseFloat(s.monthly_potential)  || 0;
            t.current   += parseFloat(s.current_potential)  || 0;
            t.expected  += parseFloat(s.expected_potential) || 0;
            t.limit     += parseFloat(s.requested_limit)    || 0;
            t.currentCl += parseFloat(s.limit)              || 0;
            t.activeBg  += parseFloat(s.activeBg)           || 0;
            t.p1        += c.siteP1(s);
        });
        t.netExposure = t.limit - t.activeBg;
        return t;
    };

    // Safe limit check (same as the Non-Trade script, at Grandparent level):
    // updated Grandparent credit limit compared with the Safe Allowable Credit Limit.
    c.isWithinSafe = function() {
        return c.rvGpUpdated() <= (c.data.calc.safeLimit || 0);
    };

    c.getDeviationGap = function() {
        return Math.max(0, c.rvGpUpdated() - (c.data.calc.safeLimit || 0));
    };

    // status counts / totals only cover the parameters shown in the Risk Parameters step
    c.getStatusCounts = function() {
        var r = { ai: 0, input: 0, over: 0, manual: 0, def: 0 };
        angular.forEach(c.data.tw.groupedParameters, function(arr) {
            arr.forEach(function(p) {
                if (isHiddenParam(p)) return;
                if (!p.selectedValue) return;
                if (p.isChanged) r.over++;
                else if (p.isDefault) r.def++;
                else if (p.autoMapped && p.mappingType === 'AI') r.ai++;
                else if (p.autoMapped && p.mappingType === 'Input') r.input++;
                else r.manual++;
            });
        });
        return r;
    };

    c.getTotalParamsCount = function() {
        var count = 0;
        angular.forEach(c.data.tw.groupedParameters, function(arr) {
            arr.forEach(function(p) { if (!isHiddenParam(p)) count++; });
        });
        return count;
    };

    // ---------- risk matrix grouping / labels ----------
    var PARAM_GROUPS = [
        { key: 'business', label: 'Business Profile',
          keys: ['age_of_company', 'segment_potential', 'current_share', 'sector_of_operation', 'corporate_body', 'mgmt_competence'] },
        { key: 'perf', label: 'Financial Performance',
          keys: ['revenue', 'sales_growth', 'gross_profit', 'ebitda'] },
        { key: 'strength', label: 'Financial Strength',
          keys: ['dept_to_equity', 'int_coverage'] },
        { key: 'wcc', label: 'Working Capital Cycle',
          keys: ['net_wcc_days', 'ar_days', 'inventory_days', 'ap_days'] },
        { key: 'credit', label: 'Credit & Compliance',
          keys: ['ext_rating', 'gst_delay', 'court_cases', 'mca_compliance', 'social_media_score'] }
    ];
    var OTHER_GROUP = { key: 'other', label: 'Other Segments (Grandparent Level)', keys: [] };

    var groupCache = { src: null, groups: [] };
    c.getParamGroups = function() {
        if (groupCache.src === c.data.tw.groupedParameters && groupCache.groups.length) return groupCache.groups;
        var byKey = {};
        PARAM_GROUPS.concat([OTHER_GROUP]).forEach(function(g) { byKey[g.key] = { key: g.key, label: g.label, params: [] }; });
        angular.forEach(c.data.tw.groupedParameters, function(arr) {
            arr.forEach(function(p) {
                if (isHiddenParam(p)) return;
                var gk = 'other';
                PARAM_GROUPS.forEach(function(g) { if (g.keys.indexOf(p.k) !== -1) gk = g.key; });
                byKey[gk].params.push(p);
            });
        });
        groupCache.src = c.data.tw.groupedParameters;
        groupCache.groups = PARAM_GROUPS.concat([OTHER_GROUP]).map(function(g) { return byKey[g.key]; }).filter(function(g) { return g.params.length > 0; });
        return groupCache.groups;
    };

    // weight shown for a parameter: a segment parameter shows its full weight (it is scored per segment)
    c.paramWeight = function(p) {
        return (p && p.baseWeight !== undefined) ? num(p.baseWeight) : num(p && p.weight);
    };

    c.getGroupWeightPct = function(grp) {
        var w = 0;
        grp.params.forEach(function(p) { w += c.paramWeight(p); });
        return Math.round(w * 100);
    };

    // parameter label with the segment of the selected group (e.g. "Cement Potential", "Cement Current SOB %")
    c.paramLabel = function(p) {
        if (p.extraSeg) return p.label;
        var seg = c.getGpSelectedSegment();
        if (seg && p.k === 'segment_potential') return seg + ' Potential';
        if (seg && p.k === 'current_share') return seg + ' Current SOB %';
        return p.label;
    };

    c.getSelectedLabel = function(param) {
        if (!param.selectedValue) return '— Not selected —';
        var o = param.options.find(function(x) { return x.sys_id === param.selectedValue; });
        return o ? o.label : '—';
    };

    c.getSelectedScore = function(param) {
        if (!param.selectedValue) return '-';
        var o = param.options.find(function(x) { return x.sys_id === param.selectedValue; });
        return o ? o.score : '-';
    };

    // add Potential / Current SOB parameters for every other segment under the Grandparent.
    // The base weights (10% / 8%) are split between segments for display; the P2 maths uses baseWeight per segment.
    c.ensureSegmentParams = function() {
        var gp = c.data.tw.groupedParameters;
        var list = gp && gp['Risk Parameter Matrix'];
        if (!list) return;

        var selSeg = c.getGpSelectedSegment();
        var segs = {};
        var ov = c.data.gpOverview;
        if (ov && ov.groups) {
            ov.groups.forEach(function(g) {
                g.zonals.forEach(function(z) {
                    z.sites.forEach(function(s) { var k = segKey(s.segment); if (k) segs[k] = true; });
                });
            });
        }
        if (selSeg) segs[selSeg] = true;
        var others = Object.keys(segs).filter(function(k) { return k !== selSeg; }).sort();
        var N = (selSeg ? 1 : 0) + others.length;
        if (N < 1) N = 1;

        var byK = {};
        list.forEach(function(p) { byK[p.k] = p; });
        var basePot = byK['segment_potential'], baseShr = byK['current_share'];
        if (!basePot || !baseShr) return;

        if (basePot.baseWeight === undefined) basePot.baseWeight = basePot.weight;
        if (baseShr.baseWeight === undefined) baseShr.baseWeight = baseShr.weight;
        basePot.weight = basePot.baseWeight / N;
        baseShr.weight = baseShr.baseWeight / N;

        list = list.filter(function(p) { return !p.extraSeg || others.indexOf(p.seg) !== -1; });
        byK = {};
        list.forEach(function(p) { byK[p.k] = p; });

        function mk(base, key, label, seg, baseKey) {
            return {
                k: key, label: label, weight: base.baseWeight / N, baseWeight: base.baseWeight,
                extraSeg: true, seg: seg, baseKey: baseKey,
                selectedValue: '', autoMapped: false, isChanged: false, isDefault: false,
                originalValue: '', originalLabel: '', mappingType: '', extractedValue: '',
                options: base.options
            };
        }

        others.forEach(function(seg) {
            var kp = 'segment_potential_' + seg, ks = 'current_share_' + seg;
            if (byK[kp]) { byK[kp].weight = basePot.baseWeight / N; }
            else list.push(mk(basePot, kp, seg + ' Potential', seg, 'segment_potential'));
            if (byK[ks]) { byK[ks].weight = baseShr.baseWeight / N; }
            else list.push(mk(baseShr, ks, seg + ' Current SOB %', seg, 'current_share'));
        });

        gp['Risk Parameter Matrix'] = list;
        groupCache.src = null;   // rebuild the grouped view
    };

    function lowestOption(p) {
        var low = null;
        (p.options || []).forEach(function(o) { if (!low || num(o.score) < num(low.score)) low = o; });
        return low;
    }

    // every parameter that has no AI / input mapping gets the lowest option by default (not mandatory)
    c.applyDefaults = function() {
        angular.forEach(c.data.tw.groupedParameters, function(arr) {
            arr.forEach(function(p) {
                if (!p.selectedValue) {
                    var low = lowestOption(p);
                    if (low) {
                        p.selectedValue = low.sys_id;
                        p.isDefault = true;
                        p.autoMapped = false;
                        p.isChanged = false;
                        p.mappingType = '';
                    }
                }
            });
        });
        c.computeP2();
    };

    // ---------- OCR ----------
    c.buildAiSummary = function(res) {
        var labels = {
            rating: 'External Rating', risk_index: 'Risk Index', court_cases: 'Court Cases', net_revenue: 'Net Revenue',
            ap_days: 'A/P Days', ar_days: 'A/R Days', ebitda: 'EBITDA %', gross_profit: 'Gross Profit %',
            debt_equity: 'Debt / Equity', int_coverage: 'Interest Coverage', inventory_days: 'Inventory Days',
            net_wcc_days: 'Net WCC Days', sales_growth: 'Sales Growth %', net_worth: 'Net Worth', loans_advances: 'Loans & Advances'
        };
        var pts = [];
        angular.forEach(labels, function(lbl, k) {
            var v = res && res[k];
            if (v !== undefined && v !== null && v !== '') pts.push({ key: lbl, val: v });
        });
        c.data.aiSummaryPoints = pts;
    };

    c.handleDocTypeChange = function() {
        c.stopTwPolling();
        c.data.tw.fileName = '';
        c.data.tw.fileData = null;
        c.data.tw.ocrSysId = null;
        c.data.tw.targetTable = '';
        c.data.tw.ocrProcessing = false;
        c.data.tw.ocrDone = false;
        c.data.tw.ocrError = '';
        c.data.tw.statusMsg = '';
        c.data.tw.lastOcrResult = null;
        c.data.aiSummaryPoints = [];

        angular.forEach(c.data.tw.groupedParameters, function(paramsArray) {
            paramsArray.forEach(function(p) {
                p.selectedValue = ''; p.autoMapped = false; p.isChanged = false; p.isDefault = false;
                p.extractedValue = ''; p.originalValue = ''; p.mappingType = '';
            });
        });

        c.autoMapMatrix(null);
        c.recalculate(false);
    };

    c.triggerTwFileInput = function() { document.getElementById('twFileInput').click(); };

    c.handleFileUpload = function(element) {
        var file = element.files[0];
        if (!file) return;

        if (file.size > 5 * 1024 * 1024) {
            c.data.tw.ocrError = 'File exceeds 5MB limit.'; element.value = ''; return;
        }

        $timeout(function() {
            c.data.tw.fileName = file.name;
            c.data.tw.fileType = file.type || 'application/pdf';
            c.data.tw.ocrError = '';
            c.data.tw.ocrProcessing = true;
            c.data.tw.ocrDone = false;
            c.data.tw.statusMsg = 'Uploading attachment and invoking OCR engine...';
        });

        var reader = new FileReader();
        reader.onload = function(e) {
            var base64Data = e.target.result.split(',')[1];
            $timeout(function() {
                c.data.tw.fileData = base64Data;
                c.server.get({
                    action: 'createOcrRecord',
                    fileName: file.name,
                    fileType: c.data.tw.fileType,
                    fileData: base64Data,
                    documentType: c.data.tw.documentType
                }).then(function(r) {
                    $timeout(function() {
                        if (r.data.sysId) {
                            c.data.tw.ocrSysId = r.data.sysId;
                            c.data.tw.targetTable = r.data.targetTable;
                            c.startTwPolling();
                        } else {
                            c.data.tw.ocrProcessing = false;
                            c.data.tw.ocrError = r.data.error || 'Failed to start OCR session.';
                        }
                    });
                });
            });
        };
        reader.readAsDataURL(file);
        element.value = '';
    };

    c.startTwPolling = function() {
        twPollCount = 0;
        c.stopTwPolling();
        twPollTimer = $interval(function() {
            twPollCount++;
            c.server.get({ action: 'pollOcrRecord', sysId: c.data.tw.ocrSysId, targetTable: c.data.tw.targetTable }).then(function(r) {
                if (r.data.ocrStatus === 'success' || r.data.ocrStatus === 'failed' || twPollCount >= TW_MAX_POLLS) {
                    c.stopTwPolling();
                    $timeout(function() {
                        c.data.tw.ocrProcessing = false;
                        c.data.tw.statusMsg = '';
                        if (r.data.ocrStatus === 'success') {
                            c.data.tw.ocrDone = true;
                            c.buildAiSummary(r.data.result || null);
                            c.autoMapMatrix(r.data.result || null);
                        } else {
                            c.data.tw.ocrError = 'AI extraction timed out or failed. Please fill manually.';
                        }
                        if (c.data.currentStep === 3) c.applyDefaults();
                    });
                } else {
                    c.data.tw.statusMsg = 'Extracting fields (' + (twPollCount * 10) + 's elapsed)...';
                }
            });
        }, 10000);
    };

    c.stopTwPolling = function() {
        if (angular.isDefined(twPollTimer)) {
            $interval.cancel(twPollTimer); twPollTimer = undefined; twPollCount = 0;
        }
    };

    // ---------- P1 (site level, display only) ----------
    c.siteVolume = function(s) { return parseFloat(s.expected_potential) || 0; };

    c.siteP1 = function(s) {
        var rate = parseFloat(s.order_rate) || 0;
        var tenor = parseFloat(s.credit_tenor);
        if (!tenor || tenor <= 0) tenor = 45;
        return c.siteVolume(s) * rate * (tenor / 30.0);
    };

    function parseOcrNumber(raw) {
        if (raw === undefined || raw === null || raw === '') return NaN;
        return parseFloat(raw.toString().replace(/,/g, '').trim());
    }

    // ---------- matrix auto-mapping ----------
    c.autoMapMatrix = function(ocrResult, inputFieldsOnly) {
        var isAiActive = (ocrResult !== null && c.data.tw.documentType && c.data.tw.documentType !== 'No Document');
        if (ocrResult) { c.data.tw.lastOcrResult = ocrResult; }

        var segCache = {};
        function segM(seg) {
            if (!segCache[seg]) segCache[seg] = c.getSegMetrics(seg);
            return segCache[seg];
        }
        var selSeg = c.getGpSelectedSegment();

        var ov = c.data.gpOverview || {};
        var companyAgeInYears = Math.floor((num(ov.vintageDays)) / 365);
        var calculatedArDays = 0;
        if (num(ov.avgMonthlySales) > 0) {
            calculatedArDays = Math.round((num(ov.outstanding) / num(ov.avgMonthlySales)) * 30);
        }

        var courtCases     = isAiActive ? (c.data.tw.lastOcrResult.court_cases || '') : '';
        var externalRating = isAiActive ? (c.data.tw.lastOcrResult.rating || '') : '';
        var riskIndex      = isAiActive ? (c.data.tw.lastOcrResult.risk_index || '') : '';

        angular.forEach(c.data.tw.groupedParameters, function(paramsArray) {
            for (var i = 0; i < paramsArray.length; i++) {
                var p = paramsArray[i];
                var pName = (p.k || p.name).toLowerCase();
                var pBase = p.baseKey ? p.baseKey : pName;
                var pSeg  = p.extraSeg ? p.seg : selSeg;

                var isPotential = pBase === 'segment_potential';
                var isShare     = pBase === 'current_share';
                var isAge       = pName === 'age_of_company';
                var isArDays    = pName === 'ar_days';

                var isInputRow  = isPotential || isShare || isAge || (isArDays && !isAiActive);

                if (inputFieldsOnly && !isInputRow) continue;

                if (!inputFieldsOnly && isAiActive && c.data.tw.lastOcrResult && !isInputRow) {

                    if (pName === 'ext_rating' && (externalRating || riskIndex)) {
                        var combinedStr = (externalRating + ' ' + riskIndex).toLowerCase();
                        var rOpt;
                        if (combinedStr.match(/4\/5|5\/5|low/)) rOpt = p.options.find(function(o) { return o.label.indexOf('Best') === 0; });
                        else if (combinedStr.match(/3\/5|medium/)) rOpt = p.options.find(function(o) { return o.label.indexOf('Good') === 0; });
                        else if (combinedStr.match(/2\/5|unrated/)) rOpt = p.options.find(function(o) { return o.label.indexOf('Average') === 0; });
                        else if (combinedStr.match(/1\/5|prop/)) rOpt = p.options.find(function(o) { return o.label.indexOf('Poor') === 0; });

                        if (rOpt) c.twApplyMap(p, rOpt.sys_id, externalRating + (riskIndex ? ' (' + riskIndex + ')' : ''), 'AI');
                        continue;
                    }

                    if (pName === 'court_cases') {
                        var courtStr = (courtCases || '').toLowerCase();
                        if (courtStr.match(/no|none|0/)) {
                            var cOpt = p.options.find(function(o) { return o.label.toLowerCase().match(/no|none|best/); });
                            if (cOpt) c.twApplyMap(p, cOpt.sys_id, courtCases || 'No Cases found', 'AI');
                        }
                        continue;
                    }

                    var isBalanceSheet = (c.data.tw.documentType === 'Balance Sheet');
                    var revenueSuffix  = isBalanceSheet ? 'Cr' : '';

                    var NUMERIC_FIELD_MAP = [
                        ['ap_days', 'ap_days', ' Days'],
                        ['ar_days', 'ar_days', ' Days'],
                        ['dept_to_equity', 'debt_equity', ' Ratio'],
                        ['ebitda', 'ebitda', ' %'],
                        ['gross_profit', 'gross_profit', ' %'],
                        ['int_coverage', 'int_coverage', ' Ratio'],
                        ['inventory_days', 'inventory_days', ' Days'],
                        ['net_wcc_days', 'net_wcc_days', ' Days'],
                        ['sales_growth', 'sales_growth', ' %'],
                        ['revenue', 'net_revenue', revenueSuffix]
                    ];

                    for (var j = 0; j < NUMERIC_FIELD_MAP.length; j++) {
                        if (pName === NUMERIC_FIELD_MAP[j][0]) {
                            var resultKey = NUMERIC_FIELD_MAP[j][1];
                            var suffix    = NUMERIC_FIELD_MAP[j][2];
                            var raw = c.data.tw.lastOcrResult[resultKey];

                            if (raw !== undefined && raw !== null && raw !== '') {
                                var n = parseOcrNumber(raw);
                                if (!isNaN(n)) {
                                    var matchVal = n;
                                    var displayVal = '';

                                    if (suffix === 'Cr' || resultKey === 'net_revenue') {
                                        matchVal = n / 10000000;
                                        displayVal = '₹' + n.toLocaleString('en-IN') + ' (' + matchVal.toFixed(2) + ' Cr)';
                                    } else {
                                        displayVal = n + suffix;
                                    }
                                    c.twApplyMap(p, c.evaluateNumberCondition(p.options, matchVal), displayVal, 'AI');
                                }
                            }
                            break;
                        }
                    }
                }

                if (isPotential) {
                    var mp = segM(pSeg);
                    var unitP = pSeg === 'RMC' ? 'CuM' : 'MT';
                    c.twApplyMap(p, c.evaluateNumberCondition(p.options, mp.potential), mp.potential.toFixed(0) + ' ' + unitP, 'Input');
                }
                else if (isShare) {
                    var ms = segM(pSeg);
                    c.twApplyMap(p, c.evaluateNumberCondition(p.options, ms.sharePct), ms.sharePct + ' %', 'Input');
                }
                else if (isAge) {
                    c.twApplyMap(p, c.evaluateNumberCondition(p.options, companyAgeInYears), companyAgeInYears + ' Years', 'Input');
                }
                else if (isArDays && !isAiActive) {
                    c.twApplyMap(p, c.evaluateNumberCondition(p.options, calculatedArDays), calculatedArDays + ' Days', 'Input');
                }
            }
        });
        c.computeP2();
    };

    c.twApplyMap = function(paramObj, matchSysId, rawValueStr, mappingType) {
        if (rawValueStr) paramObj.extractedValue = rawValueStr;
        var refreshInput = (mappingType === 'Input' && paramObj.autoMapped && paramObj.mappingType === 'Input' && !paramObj.isChanged);
        if (matchSysId && (!paramObj.selectedValue || refreshInput || paramObj.isDefault)) {
            paramObj.selectedValue = matchSysId;
            paramObj.autoMapped = true;
            paramObj.isDefault = false;
            paramObj.mappingType = mappingType || 'AI';
            paramObj.originalValue = matchSysId;
            paramObj.isChanged = false;
        }
    };

    c.evaluateNumberCondition = function(optionsArray, valueToCheck) {
        var val = parseFloat(valueToCheck);
        if (isNaN(val)) return '';

        function cleanNum(str) {
            var s = str.replace(/,/g, '');
            s = s.replace(/([\d.]+)\s*k/gi, function(mm, n) { return parseFloat(n) * 1000; });
            return s;
        }

        for (var i = 0; i < optionsArray.length; i++) {
            var cleanLabel = cleanNum(optionsArray[i].label.toLowerCase().split('(score')[0].trim());
            var rangeMatch = cleanLabel.match(/([\d.]+)\s*(?:-|to|and)\s*([\d.]+)/);
            if (rangeMatch) {
                if (val >= parseFloat(rangeMatch[1]) && val <= parseFloat(rangeMatch[2])) return optionsArray[i].sys_id;
                continue;
            }
            var singleMatch = cleanLabel.match(/([\d.]+)/);
            if (singleMatch) {
                var numVal = parseFloat(singleMatch[1]);
                if (cleanLabel.indexOf('>=') !== -1 && val >= numVal) return optionsArray[i].sys_id;
                else if (cleanLabel.indexOf('<=') !== -1 && val <= numVal) return optionsArray[i].sys_id;
                else if ((cleanLabel.indexOf('>') !== -1 || cleanLabel.indexOf('above') !== -1) && cleanLabel.indexOf('=') === -1 && val > numVal) return optionsArray[i].sys_id;
                else if ((cleanLabel.indexOf('<') !== -1 || cleanLabel.indexOf('below') !== -1) && cleanLabel.indexOf('=') === -1 && val < numVal) return optionsArray[i].sys_id;
                else if (val === numVal) return optionsArray[i].sys_id;
            }
        }
        return '';
    };

    c.trackParamChange = function(param) {
        param.isDefault = false;
        if (param.autoMapped) {
            param.isChanged = (param.selectedValue !== param.originalValue);
        }
        c.computeP2();
    };

    c.recalculate = function(isUserEdit) {
        if (!c.data.activeDraft) return;

        if (isUserEdit) {
            var mc = c.computeGpMacl();
            c.data.calc.p1 = mc.macl;

            if (c.data.tw.groupedParameters) {
                var ocrSnapshot = (c.data.tw.documentType && c.data.tw.documentType !== 'No Document' && c.data.tw.ocrDone) ? c.data.tw.lastOcrResult : null;
                c.autoMapMatrix(ocrSnapshot, true);
            }
        }
        c.computeP2();
    };

    // ---------- P2 (FRS): per-segment index, weighted by segment MPQ x average order rate ----------
    // MPQ and average order rate per segment, over ALL sites of that segment under the Grandparent
    c.segmentFinancialWeights = function() {
        var out = {};
        c.getEffectiveRows().forEach(function(r) {
            if (!r.seg) return;
            var o = out[r.seg] || (out[r.seg] = { mpq: 0, rateSum: 0, rateN: 0 });
            o.mpq += r.expected;
            if (r.rate > 0) { o.rateSum += r.rate; o.rateN++; }
        });
        angular.forEach(out, function(o) { o.rate = o.rateN ? o.rateSum / o.rateN : 0; o.weight = o.mpq * o.rate; });
        return out;
    };

    // composite index (0..1) of each segment = common params + that segment's own Potential / SOB params (full base weights)
    c.computeSegmentIndexes = function() {
        var selSeg = c.getGpSelectedSegment();
        var common = { raw: 0, w: 0 }, segs = {};
        angular.forEach(c.data.tw.groupedParameters, function(arr) {
            arr.forEach(function(p) {
                var opt = p.selectedValue ? optionOf(p) : null;
                if (!opt) return;
                var segParam = isSegParam(p);
                if (!segParam) { common.raw += num(opt.score) * p.weight; common.w += p.weight; return; }
                var seg = p.extraSeg ? p.seg : selSeg;
                var w = (p.baseWeight !== undefined) ? p.baseWeight : p.weight;
                var s = segs[seg] || (segs[seg] = { raw: 0, w: 0 });
                s.raw += num(opt.score) * w; s.w += w;
            });
        });
        var out = {};
        angular.forEach(segs, function(s, seg) {
            var den = (common.w + s.w) * 10;
            out[seg] = den > 0 ? (common.raw + s.raw) / den : 0;
        });
        return out;
    };

    // P2 = sum(SegIndex x SegMPQ x SegAvgRate) / sum(SegMPQ x SegAvgRate)
    c.computeP2Value = function() {
        var idx = c.computeSegmentIndexes(), fw = c.segmentFinancialWeights();
        var names = Object.keys(idx);
        if (!names.length) return 0;
        var totW = 0, acc = 0, plain = 0;
        names.forEach(function(s) {
            var w = fw[s] ? fw[s].weight : 0;
            totW += w; acc += idx[s] * w; plain += idx[s];
        });
        return totW > 0 ? acc / totW : plain / names.length;
    };

    // P2, P3 (Internal x External) and Safe Limit = P1 x P2 x P3
    c.computeP2 = function() {
        var base = parseFloat(c.computeP2Value().toFixed(4));
        c.data.calc.p2 = (c.data.calc.p1 > 0) ? base : 0;

        var p3Factor = 0.0;
        var cr = c.data.gpOverview && c.data.gpOverview.credit;
        if (c.data.calc.p2 > 0 && cr) {
            p3Factor = c.p3FactorFor(cr.internal, c.getCredit().external);
        }

        c.data.calc.p3 = p3Factor;
        c.data.calc.safeLimit = (c.data.calc.p1 * c.data.calc.p2 * c.data.calc.p3);
    };

    c.getCompletedCount = function() {
        var count = 0;
        angular.forEach(c.data.tw.groupedParameters, function(arr) {
            arr.forEach(function(p) { if (!isHiddenParam(p) && p.selectedValue) count++; });
        });
        return count;
    };

    c.getTotalRequested = function() {
        var tot = 0;
        c.getSelectedSites().forEach(function(s) { tot += (parseFloat(s.requested_limit) || 0); });
        return tot;
    };

    // Tool working trigger: Group Code net exposure after this request against the segment threshold
    // (Rs 50 L Cement, Rs 25 L RMC / BPD). Also returns the Grandparent net exposure used for the deviation check.
    c.getToolWorking = function() {
        var gsel = up(c.data.selectedGroupCode);
        var grpUpdLimit = 0, grpBg = 0;

        // read straight from the overview groups (the review table may be filtered by the search box)
        ((c.data.gpOverview && c.data.gpOverview.groups) || []).forEach(function(g) {
            if (up(g.code) === gsel) {
                var gr = { level: 'G', node: g, gcode: g.code };
                grpUpdLimit = c.rvUpd(gr);
                grpBg = c.rvBg(gr);
            }
        });

        var grpNetExp = grpUpdLimit - grpBg;
        var seg = up(c.getGpSelectedSegment());

        var threshold = 0;
        if (seg === 'CEMENT') {
            threshold = 5000000; // Rs 50 Lakhs for Cement
        } else if (seg === 'RMC' || seg === 'BPD') {
            threshold = 2500000; // Rs 25 Lakhs for RMC and BPD
        }

        var gpNetExp = c.rvGpUpdated() - (c.data.gpLive.activeBg || 0);

        return {
            segment: c.getGpSelectedSegment(),
            threshold: threshold,
            groupNe: grpNetExp,
            gpNe: gpNetExp,
            triggered: (threshold > 0) && (grpNetExp >= threshold)
        };
    };

    // Deviation (approval / justification): tool working triggered AND Grandparent net exposure above the safe limit
    c.isDeviation = function() {
        var total = c.getTotalParamsCount();
        if (total === 0 || c.getCompletedCount() !== total) return false;
        if (!c.isLiveReady() || !c.rvGpReady()) return false;

        var tw = c.getToolWorking();
        return tw.triggered && (tw.gpNe > (c.data.calc.safeLimit || 0));
    };

    // ---------- submit ----------
    c.submit = function() {
        if (c.data.submitting) return;

        if (c.hasValidationErrors()) {
            alert('Please correct the site line item errors before submitting.');
            c.data.currentStep = 2;
            return;
        }
        if (!c.data.businessJustification || !c.data.businessJustification.trim()) {
            alert('Please enter the Grandparent Level Remarks / Justification.');
            return;
        }
        if (c.isDeviation() && (!c.data.deviationJustification || !c.data.deviationJustification.trim())) {
            alert('A deviation was detected. Please enter the Deviation Justification.');
            return;
        }

        if (!c.rvGpReady()) {
            alert('Live site limits are still loading. Please wait a moment and try again.');
            return;
        }

        c.data.submitting = true;

        var flatParams = [];
        angular.forEach(c.data.tw.groupedParameters, function(arr) {
            arr.forEach(function(p) {
                var sVal = 0;
                if (p.selectedValue) {
                    var opt = p.options.find(function(o) { return o.sys_id === p.selectedValue; });
                    if (opt) sVal = parseFloat(opt.score);
                }
                flatParams.push({ k: p.k, val: sVal });
            });
        });

        var cr = c.getCredit();

        c.server.get({
            action: 'submit_spoc_request',
            gpCode: c.data.selectedGPCode,
            groupCode: c.data.selectedGroupCode,
            customerName: c.data.activeDraft.customer_name,
            companyType: c.data.activeDraft.company_type,
            int_rating: cr.internal,
            ext_rating: cr.external,
            enteredExtRating: c.enteredExternalRating(),
            crm_document_link: c.data.activeDraft.crm_document_link,
            stagingSysIds: c.data.activeDraft.staging_sys_ids,
            sites: c.getSelectedSites(),
            zonals: c.getZonalPayload(),
            gpLive: c.data.gpLive,
            grpLive: c.getGroupLive(),
            updGpLimit: c.rvGpUpdated(),
            updGrpLimit: c.rvGroupUpdated(),
            p1Breakdown: c.data.p1Breakdown || [],
            p2Breakdown: c.data.p2Breakdown || [],
            calc: c.data.calc,
            riskParams: flatParams,
            documentType: c.data.tw.documentType,
            fileData: c.data.tw.fileData,
            fileName: c.data.tw.fileName,
            fileType: c.data.tw.fileType,
            businessJustification: c.data.businessJustification,
            deviationJustification: c.data.deviationJustification,
            attachmentGUID: c.data.attachmentGUID
        }).then(function(r) {
            c.data.submitting = false;
            if (r.data.success) {
                c.data.submitted = true;
                c.data.requestNumber = r.data.requestNumber;
                scrollToTop();
            } else {
                alert('Submission Error: ' + (r.data.error || 'Failed to generate request.'));
            }
        }, function() {
            c.data.submitting = false;
            alert('Submission Error: server request failed.');
        });
    };

    c.resetForm = function() {
        c.stopTwPolling();
        liveCache = {};
        c.data.submitted = false;
        c.data.currentStep = 1;
        c.data.selectedGPCode = '';
        c.data.selectedGroupCode = '';
        c.data.distinctGroupCodes = [];
        c.data.activeDraft = null;
        c.data.gpOverview = null;
        c.data.hierRows = [];
        c.data.epRows = [];
        c.data.revRows = [];
        c.tree.hier.q = '';
        c.tree.ep.q = '';
        c.tree.rev.q = '';
        c.data.overviewError = '';
        c.data.loadError = '';
        c.data.lockWarning = '';
        c.data.businessJustification = '';
        c.data.deviationJustification = '';
        c.data.reviewConfirmed = false;
        c.data.calc = { p1: 0, p2: 0, p3: 0, safeLimit: 0 };
        c.data.aiSummaryPoints = [];
        c.data.p1Breakdown = [];
        c.data.p2Breakdown = [];
        c.data.revComposite = { common: { groups: [], pts: 0, wPct: 0 }, segRows: [], segments: [], totalContrib: 0 };
        c.data.gpMacl = { groups: [], totalExpected: 0, macl: 0, siteCount: 0, unit: 'MT', segments: [] };
        c.resetMaclPaging();
        c.data.tw.documentType = 'No Document';
        c.data.tw.fileName = '';
        c.data.tw.fileData = null;
        c.data.tw.ocrDone = false;
        c.data.tw.ocrProcessing = false;
        c.data.tw.ocrError = '';
        c.data.tw.lastOcrResult = null;
        $scope.attachments = [];
        c.allSelected = false;
        c.server.get({ action: 'fetch_draft_gps' }).then(function(r) {
            c.data.distinctGPCodes = r.data.distinctGPCodes || [];
        });
    };

    $scope.$on('$destroy', function() { c.stopTwPolling(); });
};

sp_widget.css:
/* ==========================================================================
   Key Customer Limit Request (Central SPOC) - CSS  v2.0 (look and feel only)
   Changes:
   - Group Code tables (Step 1 position, Step 3 potential, Step 4 limit position) now use the
     group-code dropdown tree: Collapse/Expand all + Search group code, zones and sites open
     under the group, zone total rows, yellow GP total row.            [.clm-gh*]
   - Common sections aligned with the Non-Trade master: site table (sticky columns, Customer ·
     Segment · Status cell, Territory cell, grouped ageing table), projection grid (sticky customer,
     Territory), Entity Profile form grid, credit index two-column layout with coloured grades.
   - New: .clm-block-dev (deviation card), inline styles replaced by classes.
   v2.2: segment shown under the Group Code (.gh-seg); Territory column restored on Step 1; equation tiles replaced by
         plain tiles (formula text removed everywhere).
   v2.1: Zonal Parent / Territory columns replaced by .clm-nt-cust-loc / .clm-nt-cust-zrd lines inside the
         customer cell (Grp · Zone Code, Z · R · D); wider customer columns.
   - Removed unused: .clm-nt-clickable-count, .clm-nt-hier row levels, .clm-nt-hint-line.
   ========================================================================== */
@import url('https://fonts.googleapis.com/css2?family=Oxygen:wght@300;400;700&display=swap');

.clm-widget, .clm-widget *, .clm-widget *::before, .clm-widget *::after { box-sizing:border-box; }
.clm-nt-page { background:#f6f2ee; padding:24px 32px; border-radius:8px; color:#1a1a1a; }

/* ---------- Hero ---------- */
.clm-hero {
  position:relative; isolation:isolate; overflow:hidden;
  display:flex; align-items:center; justify-content:space-between; gap:16px 24px;
  min-height:200px; padding:26px 32px; border-radius:12px;
  background:#7A1012; color:#fff; box-shadow:0 10px 28px rgba(122,16,18,.25);
}
.clm-hero::before {
  content:""; position:absolute; inset:0; z-index:-3;
  background:
    repeating-conic-gradient(from -90deg at 72% 100%,
      #F3CE52 0deg 5deg, #F9A04A 5deg 9deg, #F3712A 9deg 14deg,
      #9E1715 14deg 18deg, #DA1D26 18deg 23deg, #7A1012 23deg 26deg);
}
.clm-hero::after {
  content:""; position:absolute; inset:0; z-index:-2;
  background:linear-gradient(90deg, #7A1012 0%, #9E1715 46%, rgba(158,23,21,.82) 56%, rgba(158,23,21,.25) 70%, rgba(122,16,18,0) 82%);
}
.clm-hero-sun {
  position:absolute; left:72%; bottom:-64px; z-index:-1; width:128px; height:128px; border-radius:50%;
  transform:translateX(-50%);
  background:
    repeating-linear-gradient(0deg, transparent 0 11px, rgba(122,16,18,.85) 11px 14px),
    radial-gradient(circle, #F3CE52 0 55%, #F9A04A 100%);
  box-shadow:0 0 0 6px rgba(243,206,82,.25);
}
.clm-hero-text { position:relative; max-width:640px; }
.clm-hero-bar { width:44px; height:6px; border-radius:3px; margin-bottom:12px; background:linear-gradient(90deg,#F3CE52,#F3712A); }
.clm-hero-title { margin:0 0 6px; font-size:26px; font-weight:700; line-height:1.25; color:#fff; }
.clm-hero-accent { color:#F3CE52; }
.clm-hero-sub { margin:0; font-size:15px; line-height:1.45; color:#fbe3cf; }
.clm-hero-side { position:relative; display:flex; align-items:center; gap:12px; flex-shrink:0; }
.clm-hero-stat { min-width:150px; padding:10px 18px; border-radius:8px; text-align:left; background:rgba(122,16,18,.92); border-left:4px solid #F3CE52; }
.clm-hero-stat-v { font-size:34px; font-weight:700; line-height:1.1; letter-spacing:1px; color:#F3CE52; white-space:nowrap; }
.clm-hero-stat-k { margin-top:2px; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; color:#fbd9bd; }
.clm-hero-btn { display:inline-flex; align-items:center; gap:8px; padding:10px 18px; border:0; border-radius:6px; background:#F3CE52; color:#7A1012; font-size:14px; font-weight:700; cursor:pointer; box-shadow:0 0 0 2px #7A1012, 0 4px 12px rgba(0,0,0,.18); }
.clm-hero-btn:hover { background:#ffe07a; }

/* ---------- Panel, steps, sections ---------- */
.clm-nt-panel { margin-top:18px; background:#fff; border:1px solid #e0e6ed; border-radius:10px; overflow:hidden; }

.clm-nt-steps { display:flex; align-items:center; gap:10px; padding:16px 32px; background:#fafbfc; border-bottom:1px solid #dde3ea; }
.clm-nt-step { display:flex; align-items:center; gap:8px; flex-shrink:0; }
.clm-nt-step-n { width:26px; height:26px; border-radius:50%; display:inline-flex; align-items:center; justify-content:center; background:#eef1f5; border:1px solid #dde3ea; color:#7f8c9a; font-size:13px; font-weight:700; }
.clm-nt-step-k { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; color:#7f8c9a; }
.clm-nt-step-line { flex:1; height:2px; min-width:20px; background:#e6eaef; }
.clm-nt-step.is-active .clm-nt-step-n { background:#F3D54E; border-color:#F3D54E; color:#1a1a1a; }
.clm-nt-step.is-active .clm-nt-step-k { color:#1a1a1a; }
.clm-nt-step.is-done .clm-nt-step-n { background:#1a1a1a; border-color:#1a1a1a; color:#F3D54E; }
.clm-nt-step.is-done .clm-nt-step-k { color:#3a4451; }

.clm-section { background:#fff; padding:28px 32px; border-top:1px solid #eef1f5; }
.clm-nt-steps + div > .clm-section:first-child, .clm-nt-steps + .clm-section { border-top:0; }
.clm-nt-section-tight { padding-bottom:0; }
.clm-section-title { display:flex; align-items:center; gap:12px; margin-bottom:4px; font-size:14px; font-weight:700; color:#1a1a1a; text-transform:uppercase; letter-spacing:1px; }
.clm-section-num { width:26px; height:26px; border-radius:50%; background:#F3D54E; color:#1a1a1a; flex-shrink:0; font-size:13px; font-weight:700; display:inline-flex; align-items:center; justify-content:center; }

/* ---------- Blocks + chips ---------- */
.clm-block { margin-top:16px; background:#fff; border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
.clm-block-head { display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap; padding:14px 20px; background:#fafbfc; border-bottom:1px solid #dde3ea; }
.clm-block-title { display:flex; align-items:center; gap:10px; font-size:14px; font-weight:700; color:#1a1a1a; text-transform:uppercase; letter-spacing:.9px; }
.clm-block-title::before { content:""; width:4px; height:16px; border-radius:2px; background:#F3D54E; flex-shrink:0; }
.clm-block-sub { margin:4px 0 0 14px; font-size:12px; color:#5a6a7a; }
.clm-block-meta { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.clm-chip { display:inline-flex; align-items:center; gap:6px; padding:4px 10px; background:#fff; border:1px solid #dde3ea; border-radius:12px; font-size:12px; font-weight:700; color:#1a1a1a; white-space:nowrap; }
.clm-chip-k { font-weight:400; color:#5a6a7a; }
.clm-chip-live { background:#eaf7ee; border-color:#b9e3c6; color:#1e8449; }
.clm-chip-req  { background:#fff8e1; border-color:#f3d54e; color:#7a5a00; }
.clm-chip-dev  { background:#fdecea; border-color:#f5c2bc; color:#b3261e; }
.clm-chip.clm-nt-chip-xs { padding:1px 8px; font-size:10.5px; border-radius:10px; }
.clm-chip.clm-nt-chip-wrap { white-space:normal; }
.clm-nt-dot { font-size:8px; }
.clm-tw-body { padding:18px 20px; }
.clm-nt-pb0 { padding-bottom:0; }
.clm-nt-mt0 { margin-top:0; }

/* deviation card: red marker, light red head, red title */
.clm-block-dev { border-color:#f5c2bc; }
.clm-block-dev > .clm-block-head { background:#fef5f4; border-bottom-color:#f5c2bc; }
.clm-block-dev .clm-block-title { color:#b3261e; }
.clm-block-dev .clm-block-title::before { background:#E23D28; }

.clm-nt-sub-title { display:flex; align-items:center; gap:8px; margin-bottom:10px; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; color:#3a4451; }
.clm-nt-sub-title::before { content:""; width:3px; height:12px; border-radius:2px; background:#F3D54E; }
.clm-nt-sub-gap { margin-top:22px; }

/* ---------- Forms ---------- */
.clm-field { display:flex; flex-direction:column; gap:6px; }
.clm-field-k { margin:0; font-size:13px; font-weight:700; color:#1a1a1a; }
.clm-field-hint { font-size:12px; color:#7f8c9a; }
.clm-req { color:#E23D28; font-weight:700; }
.clm-input.form-control { width:100%; display:block; height:auto; padding:9px 12px; font-size:14px; color:#1a1a1a; background:#fff; border:1px solid #cdd4dc; border-radius:6px; box-shadow:none; transition:border-color .2s, box-shadow .2s; }
.clm-input.form-control:focus { border-color:#E8B800; box-shadow:0 0 0 3px rgba(243,213,78,.3); outline:0; }
textarea.clm-input.form-control { resize:vertical; }
.clm-nt-form-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px 20px; }
.clm-nt-span-2 { grid-column:1 / -1; }

.clm-nt-upload { display:flex; align-items:center; gap:12px; padding:12px 14px; background:#fafbfc; border:1px dashed #c9d1db; border-radius:6px; }
.clm-nt-upload-ic { font-size:20px; color:#7f8c9a; }
.clm-nt-file-ok { margin-top:6px; font-size:13px; color:#1e8449; }
.clm-nt-attach-item { display:flex; align-items:center; justify-content:space-between; padding:8px 12px; margin-bottom:8px; background:#fff; border:1px solid #e0e6ed; border-radius:6px; font-size:13px; color:#1782c5; font-weight:700; }
.clm-nt-doclink { color:#1782c5; font-weight:700; text-decoration:none; }
.clm-nt-doclink:hover { text-decoration:underline; }
.clm-nt-doc-row { display:flex; align-items:center; gap:14px; padding:10px 14px; margin-bottom:10px; background:#fafbfc; border:1px solid #e0e6ed; border-radius:6px; }
.clm-nt-doc-row > .fa { font-size:20px; color:#7f8c9a; }
.clm-nt-doc-gap { margin-top:16px; }
.clm-nt-form-grid .clm-nt-doc-row { margin-bottom:0; }

/* ---------- Data tables ---------- */
.clm-nt-table-scroll { overflow-x:auto; -webkit-overflow-scrolling:touch; }
.clm-table { width:100%; border-collapse:collapse; font-size:13px; font-variant-numeric:tabular-nums; margin:0; }
.clm-table th { background:#eef1f5; color:#2b3440; padding:12px 14px; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; text-align:center; white-space:nowrap; border:1px solid #e3e8ee; vertical-align:middle; }
.clm-table td { padding:14px; color:#1a1a1a; text-align:center; white-space:nowrap; border:1px solid #edf0f4; vertical-align:middle; }
.clm-table tr > :first-child { border-left:0; }
.clm-table tr > :last-child  { border-right:0; }
.clm-table thead tr:first-child th { border-top:0; }
.clm-table tbody tr:last-child td  { border-bottom:0; }
.clm-table .grp { border-left:2px solid #dde3ea !important; }
.clm-table tr.super th { letter-spacing:1px; padding:11px 14px; }
.clm-table th.bg-blank { background:#f7f8fa; }
.clm-table th.bg-code  { background:#e3eefa; color:#0b5394; }
.clm-table th.bg-pan   { background:#fdf3e1; color:#a35400; }
.clm-table th.bg-seg   { background:#f1f3f7; color:#3a4451; }
.clm-table th.bg-req   { background:#e6f4ea; color:#2e7d32; }
.clm-table .clm-nt-left { text-align:left; }

.clm-cust-name { font-weight:700; color:#1a1a1a; }
.clm-cust-code { margin-top:2px; font-size:12px; font-weight:600; color:#5a6a7a; }
.v-ok, .clm-table td.v-ok   { color:#1e8449; font-weight:700; }
.v-bad, .clm-table td.v-bad { color:#c0392b; font-weight:700; }
.clm-nt-strong { font-weight:700; }
.clm-nt-faint { color:#b0b9c4; }
.clm-nt-red { color:#c0392b; }
.clm-nt-wrap { white-space:normal; }
.clm-nt-head-v { font-size:20px; }

/* segment-wise summary table wrapper */
.clm-nt-seg-wrap { border:1px solid #dde3ea; border-radius:8px; }
.clm-nt-segtbl th, .clm-nt-segtbl td { padding:12px 16px; }
.clm-nt-segtbl .num, .clm-table.clm-nt-segtbl td.num { text-align:right; }
.clm-nt-segtbl td.clm-nt-ne { font-weight:700; background:#fffcf0; }
.clm-nt-segtbl tfoot td { background:#f6f7f9; font-weight:700; border-top:2px solid #dde3ea; border-bottom:0; }
.clm-nt-segtbl tfoot td.clm-nt-left { text-transform:uppercase; letter-spacing:.6px; font-size:12px; color:#3a4451; }

/* ---------- Group code dropdown tree (Step 1 / 3 / 4) ---------- */
.clm-gh-bar { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px 16px; margin:0 0 12px; }
.clm-nt-toolbar.clm-gh-bar { margin:0; }
.clm-gh-bar-l { display:flex; align-items:baseline; flex-wrap:wrap; gap:4px 12px; }
.clm-gh-title { display:inline-flex; align-items:center; gap:8px; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; color:#3a4451; }
.clm-gh-title::before { content:""; width:3px; height:12px; border-radius:2px; background:#F3D54E; }
.clm-gh-hint { font-size:11.5px; color:#7f8c9a; }
.clm-gh-bar-r { display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
.clm-btn.clm-gh-btn { text-transform:none; letter-spacing:0; font-size:12.5px; padding:8px 14px; }
.clm-gh-search { width:240px; max-width:100%; }

.clm-gh th, .clm-gh td { padding:12px 16px; }
.clm-gh th.clm-nt-left, .clm-gh td.clm-nt-left { text-align:left; }
.clm-gh .num, .clm-table.clm-gh td.num { text-align:right; }
.clm-gh tr.gh-group { cursor:pointer; }
.clm-gh tr.gh-group td { background:#f6f7f9; font-weight:700; }
.clm-gh tr.gh-group:hover td { background:#fffcf0; }
.clm-gh tr.gh-group.is-open td { border-bottom:2px solid #dde3ea; }
.clm-gh tr.gh-group td.clm-nt-ne { background:#fbf5dc; }
.clm-gh tr.gh-group td.gh-gcell { white-space:nowrap; }
.clm-gh tr.gh-group.is-open td:first-child { box-shadow:inset 4px 0 0 #F3D54E; }
.gh-seg { margin:6px 0 0 22px; }
.gh-caret { width:12px; margin-right:10px; color:#5a6a7a; font-size:12px; }
.gh-muted { color:#5a6a7a; font-weight:400; }
.gh-sub { margin-top:2px; font-size:12px; font-weight:400; color:#5a6a7a; }
.gh-code { font-weight:700; color:#1a1a1a; }
.clm-gh td.gh-gblank { background:#fff; }
.clm-gh td.gh-zcell { background:#fafbfc; vertical-align:top; }
.clm-gh tr.gh-site td { background:#fff; }
.clm-gh tr.gh-site td.num { font-weight:400; }
.clm-gh tr.gh-site td.clm-nt-ne { background:#fffcf0; }
.clm-gh tr.gh-site.is-active td { background:#fffcf0; }
.clm-gh tr.gh-site.is-active td.gh-sitecell { box-shadow:inset 4px 0 0 #F3D54E; }
.clm-gh tr.gh-site.is-active td.gh-gblank, .clm-gh tr.gh-site.is-active td.gh-zcell { background:#fff; }
.clm-gh tr.gh-site td.clm-nt-chg { color:#7a4100; }
.clm-gh tr.gh-ztot td { background:#f7f8fa; font-weight:700; }
.clm-gh tr.gh-ztot td.clm-nt-ne { background:#fbf5dc; }
.clm-gh tr.gh-ztot td.gh-ztl { text-transform:uppercase; letter-spacing:.6px; font-size:12px; color:#3a4451; }
.clm-gh tfoot td { background:#fff8d6; font-weight:700; border-top:2px solid #F3D54E; border-bottom:0; }
.clm-gh tfoot td.clm-nt-left { text-transform:uppercase; letter-spacing:.6px; font-size:12px; color:#3a4451; }
.clm-gh tfoot .gh-foot-k { text-transform:none; letter-spacing:0; font-weight:400; color:#5a6a7a; }
.clm-nt-reqtag { display:inline-block; margin-left:8px; padding:1px 8px; border-radius:10px; font-size:10.5px; font-weight:700; text-transform:uppercase; letter-spacing:.4px; vertical-align:middle; background:#fff1e3; color:#b45f06; border:1px solid #f6c590; white-space:nowrap; }
.clm-nt-inreq { display:inline-block; margin-left:6px; padding:1px 7px; border-radius:10px; font-size:10.5px; font-weight:700; text-transform:uppercase; letter-spacing:.4px; vertical-align:middle; background:#1a1a1a; color:#F3D54E; }

/* ---------- Site selection table (Step 1) ---------- */
.clm-nt-toolbar { padding:14px 20px; border-bottom:1px solid #e6eaef; }
.clm-nt-search { position:relative; max-width:420px; }
.clm-nt-search .fa { position:absolute; left:12px; top:50%; transform:translateY(-50%); color:#7f8c9a; }
.clm-nt-search .clm-input.form-control { padding-left:34px; }
.clm-nt-col-chk, .clm-nt-col-exp { width:44px; min-width:44px; max-width:44px; padding-left:8px !important; padding-right:8px !important; }

/* checkbox, arrow and customer columns frozen while the table scrolls sideways */
.clm-nt-sites .clm-nt-stk { position:sticky; z-index:2; }
.clm-nt-sites thead .clm-nt-stk { z-index:3; }
.clm-nt-sites td.clm-nt-stk { background:#fff; }
.clm-nt-sites tr.clm-nt-row:hover td.clm-nt-stk { background:#fafbfc; }
.clm-nt-sites .clm-nt-stk-1 { left:0; }
.clm-nt-sites .clm-nt-stk-2 { left:44px; }
.clm-nt-sites .clm-nt-stk-3 { left:88px; box-shadow:6px 0 8px -6px rgba(26,26,26,.18); }
.clm-nt-sites .clm-nt-col-cust { min-width:300px; max-width:380px; white-space:normal; }
.clm-nt-sites .clm-nt-col-terr { min-width:230px; white-space:normal; }
.clm-nt-terr-main { font-size:13px; font-weight:700; color:#1a1a1a; text-transform:uppercase; }
.clm-nt-terr-sub { margin-top:2px; font-size:12px; color:#5a6a7a; text-transform:uppercase; }
.clm-nt-cust-meta { display:flex; align-items:center; flex-wrap:wrap; gap:4px 6px; margin-top:4px; }
.clm-nt-cust-meta .clm-cust-code { margin-top:0; }
.clm-nt-cust-loc { margin-top:4px; font-size:12px; font-weight:400; color:#1a1a1a; }
.clm-nt-cust-zrd { margin-top:2px; font-size:12px; font-weight:400; color:#5a6a7a; }
.clm-nt-cust-loc strong, .clm-nt-cust-zrd strong { font-weight:700; color:#1a1a1a; }
.clm-nt-dotsep { color:#9aa5b1; margin:0 2px; }
.clm-nt-th-sub { margin-top:2px; font-size:10px; font-weight:400; text-transform:none; letter-spacing:0; color:#7f8c9a; }
.clm-nt-checkbox { width:16px; height:16px; margin:0; cursor:pointer; accent-color:#1a1a1a; }
.clm-nt-exp-btn { width:28px; height:28px; padding:0; border:1px solid #dde3ea; border-radius:6px; background:#fff; color:#3a4451; cursor:pointer; }
.clm-nt-exp-btn:hover { background:#1a1a1a; color:#F3D54E; border-color:#1a1a1a; }
.clm-nt-seg { display:inline-block; padding:3px 10px; border-radius:12px; background:#f1f3f7; border:1px solid #dde3ea; font-size:11.5px; font-weight:700; color:#3a4451; }
.clm-nt-loc { font-size:12.5px; color:#3a4451; }
.clm-nt-row { cursor:pointer; transition:background .15s; }
.clm-nt-row:hover td { background:#fafbfc; }
.clm-table tr.selected-row td { background:#fffcf0 !important; }
.clm-table tr.selected-row td:first-child { box-shadow:inset 4px 0 0 #F3D54E; }
.clm-table tr.bg-light td { background:#f7f8fa !important; color:#9aa5b1; }
.clm-table tr.bg-light .clm-cust-name, .clm-table tr.bg-light .v-ok, .clm-table tr.bg-light .v-bad,
.clm-table tr.bg-light .clm-nt-terr-main, .clm-table tr.bg-light .clm-nt-terr-sub, .clm-table tr.bg-light .clm-nt-cust-loc, .clm-table tr.bg-light .clm-nt-cust-zrd, .clm-table tr.bg-light .clm-nt-cust-loc strong, .clm-table tr.bg-light .clm-nt-cust-zrd strong, .clm-table tr.bg-light .clm-cust-code { color:#9aa5b1; }
.clm-table tr.bg-light { cursor:not-allowed; }
.clm-nt-sites tr.clm-swap-locked { cursor:not-allowed; }
.clm-nt-sites tr.clm-swap-locked td { opacity:.85; }

/* expanded 6 month ageing */
.clm-table tr.clm-nt-exp-row > td { padding:14px 16px; background:#f7f8fa; text-align:left; }
.clm-nt-exp-inner { position:sticky; left:16px; width:100%; max-width:min(940px, calc(100vw - 120px)); }
.clm-nt-exp-title { display:flex; align-items:center; gap:10px; margin-bottom:10px; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; color:#3a4451; }
.clm-nt-exp-title::before { content:""; width:4px; height:14px; border-radius:2px; background:#F3D54E; }
.clm-nt-ag-wrap { border:1px solid #dde3ea; border-radius:6px; background:#fff; }
.clm-nt-ag { table-layout:fixed; }
.clm-nt-ag col.clm-nt-ag-c-month { width:104px; }
.clm-nt-ag col.clm-nt-ag-c-total { width:124px; }
.clm-nt-ag th { font-size:11px; padding:7px 8px; letter-spacing:.3px; }
.clm-nt-ag td { font-size:12px; padding:7px 8px; text-align:right; overflow:hidden; text-overflow:ellipsis; }
.clm-nt-ag td.clm-nt-left { text-align:left; }
.clm-nt-ag tr.ag-group th.safe { background:#d9eedd; color:#14532d; }  .clm-nt-ag tr.ag-sub th.safe { background:#edf7ef; color:#14532d; }
.clm-nt-ag tr.ag-group th.warn { background:#fde4c4; color:#7a4100; }  .clm-nt-ag tr.ag-sub th.warn { background:#fff4e5; color:#7a4100; }
.clm-nt-ag tr.ag-group th.risk { background:#f8d7d3; color:#8f1d16; }  .clm-nt-ag tr.ag-sub th.risk { background:#fdeeec; color:#8f1d16; }
.clm-nt-ag tr.ag-sub th:last-child { border-right:0; }
.clm-nt-ag td.zero { color:#b0b9c4; }
.clm-nt-ag td.warn-val { color:#a15a00; font-weight:700; background:#fffaf2; }
.clm-nt-ag td.risk-val { color:#b3261e; font-weight:700; background:#fff6f5; }
.clm-nt-empty { text-align:center !important; color:#7f8c9a; padding:14px !important; }

.clm-nt-pager { display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; padding:12px 20px; background:#fafbfc; border-top:1px solid #dde3ea; }
.clm-nt-pagesize { display:flex; align-items:center; gap:8px; font-size:12.5px; color:#5a6a7a; }
.clm-nt-pagesize .clm-input.form-control { width:76px; padding:6px 8px; font-size:13px; }
.clm-nt-pagenav { display:flex; align-items:center; gap:10px; }
.clm-nt-pagenum { font-size:13px; font-weight:700; }

/* ---------- Projection grid (Step 2) ---------- */
.clm-nt-grid th { font-size:11px; padding:10px 7px; letter-spacing:.4px; white-space:normal; }
.clm-nt-grid td.clm-nt-left { white-space:normal; min-width:150px; padding-left:14px; }
.clm-nt-grid tr.super th { padding:9px 8px; }
.clm-nt-grid td { padding:10px 7px; }
.clm-nt-cell.form-control { height:auto; width:96px; min-width:0; padding:7px 10px; font-size:13.5px; border:1px solid #cdd4dc; border-radius:5px; box-shadow:none; text-align:right; }
.clm-nt-cell.form-control:focus { border-color:#E8B800; box-shadow:0 0 0 3px rgba(243,213,78,.3); }
.clm-nt-cell-sm.form-control { width:70px; }
.clm-nt-cell-key.form-control { width:124px; font-weight:700; background:#fffcf0; border-color:#e8d27a; }
.clm-nt-cell-txt.form-control { width:100%; min-width:150px; min-height:34px; text-align:left; resize:vertical; }
.clm-nt-calc { background:#faf8fe; text-align:right !important; }
.clm-nt-ro { background:#fdfaf3; color:#3a4451; }
.clm-table td.clm-nt-num { text-align:right; }
.clm-nt-unit { font-size:11px; font-weight:400; color:#7f8c9a; }
.clm-nt-grid td .clm-nt-err { max-width:130px; }
.clm-nt-grid tfoot td, .clm-nt-rv tfoot td { background:#f6f7f9; font-weight:700; border-top:2px solid #dde3ea; border-bottom:0; padding:12px 8px; }
.clm-nt-grid tfoot td.clm-nt-left, .clm-nt-rv tfoot td.clm-nt-left { padding-left:14px; text-transform:uppercase; letter-spacing:.6px; font-size:12px; color:#3a4451; }
/* customer column frozen while the grid scrolls sideways */
.clm-nt-grid .clm-nt-stk-g { position:sticky; left:0; z-index:2; min-width:210px; max-width:260px; white-space:normal; box-shadow:6px 0 8px -6px rgba(26,26,26,.18); }
.clm-nt-grid thead .clm-nt-stk-g { z-index:3; }
.clm-nt-grid tbody td.clm-nt-stk-g { background:#fff; }
.clm-nt-grid tfoot td.clm-nt-stk-g { background:#f6f7f9; }
.clm-nt-err { margin-top:4px; font-size:11px; font-weight:700; color:#c0392b; white-space:normal; text-align:left; }
.clm-nt-err-list { margin:6px 0 0; padding-left:18px; line-height:1.7; }
.border-danger { border-color:#E23D28 !important; box-shadow:0 0 0 3px rgba(226,61,40,.12) !important; }

/* ---------- Review (Step 4) ---------- */
.clm-nt-rv th, .clm-nt-rv td { padding:12px 12px; }
.clm-nt-rv .num, .clm-table.clm-nt-rv td.num { text-align:right; }
.clm-table td.clm-nt-chg { background:#fffcf0; color:#7a4100; }
.clm-nt-note-row { padding:12px 20px; font-size:12.5px; color:#3a4451; background:#fafbfc; border-top:1px solid #e6eaef; }
.clm-nt-res-tile { margin:0 20px 20px; padding:16px; text-align:center; border:1px solid #f1d77a; border-radius:8px; background:#fffcf0; }
.clm-block > .clm-nt-table-scroll + .clm-nt-res-tile, .clm-block > div + .clm-nt-res-tile { margin-top:16px; }
.clm-nt-res-tile-k { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.8px; color:#7a5a00; }
.clm-nt-res-tile-v { margin-top:4px; font-size:28px; font-weight:700; color:#1a1a1a; }
.clm-nt-macl tr.clm-nt-segrow td { background:#f6f7f9; font-weight:700; color:#1a1a1a; border-top:1px solid #e3e8ee; }
.clm-nt-segrow-k { margin-left:8px; font-size:12px; font-weight:400; color:#5a6a7a; }
.clm-table td.clm-nt-indent { padding-left:34px; }

/* Requested sites / All sites toggle */
.clm-nt-toggle { display:inline-flex; border:1px solid #cdd4dc; border-radius:16px; overflow:hidden; background:#fff; }
.clm-nt-toggle-btn { padding:5px 14px; border:0; background:transparent; color:#3a4451; font-size:12px; font-weight:700; cursor:pointer; white-space:nowrap; }
.clm-nt-toggle-btn + .clm-nt-toggle-btn { border-left:1px solid #cdd4dc; }
.clm-nt-toggle-btn:hover { background:#f6f7f9; }
.clm-nt-toggle-btn.is-on { background:#1a1a1a; color:#F3D54E; }

/* composite index (P2) review */
.clm-nt-step-dot { display:inline-flex; align-items:center; justify-content:center; width:20px; height:20px; margin-right:4px; border-radius:50%; background:#1a1a1a; color:#F3D54E; font-size:11px; font-weight:700; vertical-align:middle; }
.clm-nt-seg-head { padding:12px 20px 8px; font-size:12.5px; color:#5a6a7a; }
.clm-nt-seg-head + .clm-nt-table-scroll { border-top:1px solid #e6eaef; }
.clm-nt-table-scroll + .clm-nt-seg-head { padding-top:16px; border-top:1px solid #e6eaef; }
.clm-nt-sub-v { margin-top:2px; font-size:11px; font-weight:400; color:#7f8c9a; }
.clm-nt-segp td.clm-nt-segcell { background:#fafbfc; border-right:1px solid #e6eaef; vertical-align:middle; }
.clm-nt-segp tr.seg-first td { border-top:2px solid #e6eaef; }
.clm-nt-segp tbody tr:first-child td { border-top:0; }
.clm-nt-p2w th, .clm-nt-p2w td { padding:10px 12px; }

.clm-nt-cmx th, .clm-nt-cmx td { padding:10px 16px; }
.clm-nt-cmx tfoot td, .clm-nt-cmx tr.clm-nt-cmx-tot td { background:#fff8e1; font-weight:700; color:#1a1a1a; border-top:1px solid #f1e2a0; }
.clm-nt-cmx tr.grp.clm-nt-ag-safe td { background:#edf7ef; color:#14532d; }
.clm-nt-cmx tr.grp.clm-nt-ag-warn td { background:#fff4e5; color:#7a4100; }
.clm-nt-cmx tr.grp.clm-nt-ag-risk td { background:#fdeeec; color:#8f1d16; }
.clm-nt-cmx .tag { margin-left:6px; }
.clm-nt-bar-col { width:200px; }
.clm-nt-bar { display:inline-block; width:90px; height:6px; margin-right:8px; vertical-align:middle; border-radius:3px; background:#e6eaef; overflow:hidden; }
.clm-nt-bar-fill { display:block; height:100%; border-radius:3px; }
.clm-nt-bar-safe { background:#1e8449; } .clm-nt-bar-warn { background:#e08a00; } .clm-nt-bar-risk { background:#c0392b; }

/* credit index: ageing on the left, ratings on the right */
.clm-nt-credit-grid { display:grid; grid-template-columns:minmax(0,1.7fr) minmax(260px,1fr); gap:16px; padding:16px 20px 20px; align-items:start; }
.clm-nt-credit-main { border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
.clm-nt-credit-side { display:flex; flex-direction:column; gap:12px; }
.clm-nt-credit-side .clm-tw-factor { padding:14px 16px; }
.clm-nt-credit-grid + .clm-nt-res-tile { margin-top:0; }
.clm-nt-rating { text-align:center; }
.clm-nt-rating-v { font-size:30px; font-weight:700; line-height:1.2; color:#1a1a1a; }
.clm-nt-rating-v.grade-A { color:#1e8449; }
.clm-nt-rating-v.grade-B { color:#e07b00; }
.clm-nt-rating-v.grade-C { color:#c0392b; }

.clm-nt-readonly { background:#fafbfc; border:1px solid #e0e6ed; border-left:4px solid #F3D54E; border-radius:6px; padding:12px 14px; font-size:14px; line-height:1.5; white-space:pre-wrap; }

.clm-nt-safe { border-color:#f1d77a; }

/* ---------- Matrix (Step 3 and 4) ---------- */
.clm-matrix { width:100%; border-collapse:collapse; font-size:13px; margin:0; }
.clm-matrix th { text-align:left; padding:12px 14px; background:#e4e9f0; color:#1a1a1a; font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.7px; border:1px solid #d9e0e8; }
.clm-matrix td { padding:11px 14px; border:1px solid #edf0f4; color:#1a1a1a; vertical-align:middle; }
.clm-matrix tr > :first-child { border-left:0; }
.clm-matrix tr > :last-child  { border-right:0; }
.clm-matrix thead tr:first-child th { border-top:0; }
.clm-matrix tbody:last-of-type tr:last-child td, .clm-matrix tfoot tr:last-child td { border-bottom:0; }
.clm-matrix .num { text-align:right; white-space:nowrap; }
.clm-matrix tr.grp td { background:#fbf6e4; color:#1a1a1a; padding:10px 14px; font-size:12.5px; font-weight:700; text-transform:uppercase; letter-spacing:.9px; border-top:1px solid #efe3b8; border-bottom:1px solid #efe3b8; }
.clm-matrix tr.grp td:first-child { box-shadow:inset 4px 0 0 #F3D54E; }
.clm-matrix tr.grp td.clm-nt-m-gmeta { font-weight:600; text-transform:none; letter-spacing:0; color:#7a5a00; font-size:12px; }
.clm-nt-m-name { width:42%; } .clm-nt-m-sel { width:40%; } .clm-nt-m-src { width:18%; }
.clm-nt-m-title { font-size:13px; font-weight:600; color:#2b3440; }
.clm-nt-m-select.form-control { padding:7px 10px; font-size:13px; }
.clm-nt-m-src-val { margin-top:3px; font-size:11.5px; color:#5a6a7a; }
.clm-nt-m-orig { margin-top:4px; font-size:11px; color:#7f8c9a; }
.clm-matrix tbody tr:not(.grp):hover td { background:#fcfcfd; }
.clm-matrix tr.ai-highlight-row td    { background:#f7fbfe; }
.clm-matrix tr.ai-highlight-row td:first-child    { box-shadow:inset 4px 0 0 #1782c5; }
.clm-matrix tr.input-highlight-row td { background:#fcf9ff; }
.clm-matrix tr.input-highlight-row td:first-child { box-shadow:inset 4px 0 0 #800080; }
.clm-matrix tr.edit-highlight-row td  { background:#fffdf6; }
.clm-matrix tr.edit-highlight-row td:first-child  { box-shadow:inset 4px 0 0 #ffc107; }
.clm-matrix tr.default-param-row td   { background:#fafbfc; }
.clm-matrix tr.default-param-row td:first-child   { box-shadow:inset 4px 0 0 #b0b9c4; }

.tag { display:inline-flex; align-items:center; gap:4px; padding:2px 8px; border-radius:4px; border:1px solid; font-size:10.5px; font-weight:700; white-space:nowrap; }
.tag-ai     { background:#eef6fb; color:#1782c5; border-color:#1782c5; }
.tag-input  { background:#f6eefe; color:#800080; border-color:#800080; }
.tag-ovr    { background:#fffbeb; color:#a07000; border-color:#ffc107; }
.tag-manual { background:#f5f5f5; color:#5a6a7a; border-color:#d6dbe1; }
.tag-miss   { background:#fdecea; color:#b3261e; border-color:#f5c2bc; }
.tag-default { background:#f1f3f7; color:#3a4451; border-color:#b0b9c4; }

/* ---------- Factor tiles + result row ---------- */
.clm-tw-factors { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; }
.clm-nt-factors-4 { grid-template-columns:repeat(4,minmax(0,1fr)); }
.clm-tw-factor { padding:12px 14px; border:1px solid #e0e6ed; border-radius:6px; background:#fafbfc; }
.clm-tw-factor-k { font-size:12px; color:#5a6a7a; margin-bottom:4px; }
.clm-tw-factor-v { font-size:16px; font-weight:700; color:#1a1a1a; white-space:nowrap; }
.clm-tw-factor-s { font-size:11px; color:#7f8c9a; margin-top:4px; }
.clm-tw-factor.is-ok  { background:#f4fbf6; border-color:#cfead8; }  .clm-tw-factor.is-ok  .clm-tw-factor-v { color:#1e8449; }
.clm-tw-factor.is-bad { background:#fef5f4; border-color:#f5c2bc; }  .clm-tw-factor.is-bad .clm-tw-factor-v { color:#c0392b; }
.clm-tw-factor.is-key { background:#fffcf0; border-color:#f1e2a0; box-shadow:inset 4px 0 0 #F3D54E; }

.clm-tw-res { display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap; padding:16px 20px; background:#fffcf0; border-top:1px solid #f1e2a0; }
.clm-tw-res-k { font-size:13px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-tw-res-f { margin-top:6px; font-size:12px; color:#7f8c9a; }
.clm-tw-res-v { margin-left:auto; font-size:30px; font-weight:700; line-height:1.1; color:#1a1a1a; }
.clm-tw-res.is-ok  { background:#f4fbf6; border-top-color:#b9e3c6; } .clm-tw-res.is-ok  .clm-tw-res-v { color:#1e8449; }
.clm-tw-res.is-bad { background:#fef5f4; border-top-color:#f5c2bc; } .clm-tw-res.is-bad .clm-tw-res-v { color:#c0392b; }

/* ---------- Notices, loaders, actions, buttons, success ---------- */
.clm-note { display:flex; align-items:flex-start; gap:10px; margin-top:16px; padding:12px 16px; border:1px solid; border-radius:8px; font-size:13px; }
.clm-note .fa { margin-top:2px; }
.clm-note-ok   { background:#f4fbf6; border-color:#b9e3c6; color:#1e8449; }
.clm-note-warn { background:#fff8e1; border-color:#f3d54e; color:#7a5a00; }
.clm-note-err  { background:#fef5f4; border-color:#f5c2bc; color:#c0392b; }
.clm-note.clm-nt-mt0 { margin-top:0; }

.clm-nt-loader { padding:36px 20px; text-align:center; }
.clm-nt-loader .fa { color:#AF272F; margin-bottom:14px; }
.clm-nt-loader-t { font-size:16px; font-weight:700; color:#1a1a1a; }
.clm-nt-loader-s { margin-top:6px; font-size:12.5px; color:#5a6a7a; }

.clm-nt-actions { display:flex; align-items:center; justify-content:flex-end; gap:10px; flex-wrap:wrap; padding:18px 32px; background:#fafbfc; border-top:1px solid #dde3ea; }
.clm-nt-busy { margin-right:auto; font-size:12.5px; color:#5a6a7a; }
.clm-nt-ready { display:flex; gap:8px; flex-wrap:wrap; margin-right:auto; }

.clm-btn { display:inline-flex; align-items:center; justify-content:center; gap:8px; padding:10px 20px; background:#fff; color:#1a1a1a; border:1px solid #cdd4dc; border-radius:6px; font-size:13px; font-weight:700; text-transform:uppercase; letter-spacing:.5px; cursor:pointer; white-space:nowrap; transition:background .2s, color .2s, border-color .2s; }
.clm-btn:hover { border-color:#1a1a1a; }
.clm-btn-sm { padding:6px 12px; font-size:12px; }
.clm-btn-primary { background:#1a1a1a; color:#F3D54E; border-color:#1a1a1a; }
.clm-btn-primary:hover { background:#333; color:#F3D54E; }
.clm-btn[disabled], .clm-btn[disabled]:hover { background:#eef1f5; color:#9aa5b1; border-color:#dde3ea; cursor:not-allowed; }

.clm-nt-success { padding:48px 32px; text-align:center; border-top:0; }
.clm-nt-success-ic { width:72px; height:72px; margin:0 auto 16px; border-radius:50%; display:flex; align-items:center; justify-content:center; background:#eaf7ee; border:2px solid #27ae60; color:#27ae60; font-size:32px; }
.clm-nt-success-t { font-size:20px; font-weight:700; color:#1a1a1a; }
.clm-nt-success-s { margin:8px auto 24px; max-width:520px; font-size:13.5px; color:#5a6a7a; }
.clm-nt-success-actions { display:flex; justify-content:center; gap:10px; flex-wrap:wrap; }

.slide-down { animation:clmNtSlide .35s ease-out; }
@keyframes clmNtSlide { from { opacity:0; transform:translateY(-8px); } to { opacity:1; transform:translateY(0); } }

/* ---------- Responsive ---------- */
@media (max-width:1100px) {
  .clm-nt-factors-4, .clm-tw-factors { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .clm-hero-title { font-size:22px; }
}
@media (max-width:900px) {
  .clm-nt-eq { grid-template-columns:1fr; gap:6px; }
  .clm-nt-credit-grid { grid-template-columns:1fr; }
  .clm-nt-eq-op { line-height:1; }
}
@media (max-width:768px) {
  .clm-nt-page { padding:14px; }
  .clm-hero { flex-direction:column; align-items:flex-start; padding:22px 20px 70px; }
  .clm-hero::after { background:linear-gradient(180deg, #7A1012 0%, #9E1715 55%, rgba(158,23,21,.55) 75%, rgba(122,16,18,0) 100%); }
  .clm-hero-sun { left:50%; }
  .clm-hero-side { width:100%; }
  .clm-section { padding:20px 16px; }
  .clm-nt-steps { padding:12px 16px; overflow-x:auto; }
  .clm-nt-step-k { display:none; }
  .clm-nt-step.is-active .clm-nt-step-k { display:inline; }
  .clm-nt-actions { padding:14px 16px; }
  .clm-nt-form-grid { grid-template-columns:1fr; }
  .clm-gh-bar-r { width:100%; }
  .clm-gh-search { flex:1; width:auto; }
}
@media (max-width:640px) {
  .clm-hero-title { font-size:20px; }
  .clm-hero-sub { font-size:13px; }
  .clm-hero-stat-v { font-size:28px; }
  .clm-nt-factors-4, .clm-tw-factors { grid-template-columns:1fr; gap:8px; }
  .clm-tw-factor { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:4px 10px; }
  .clm-tw-factor-k { margin-bottom:0; }
  .clm-tw-factor-s { flex-basis:100%; margin-top:0; }
  .clm-tw-factor.clm-nt-rating { display:block; }
  .clm-nt-head-v { font-size:16px; }
  .clm-tw-res-v { font-size:24px; margin-left:0; }
  .clm-block-sub { margin-left:0; }
  .clm-nt-actions .clm-btn, .clm-nt-success-actions .clm-btn { width:100%; }
  .clm-nt-busy { width:100%; }
  .clm-nt-pager { flex-direction:column; align-items:stretch; }
  .clm-nt-pagenav { justify-content:space-between; }
  .clm-nt-credit-grid { padding:12px; }
  .clm-nt-cmx th, .clm-nt-cmx td { padding:9px 12px; }
  .clm-nt-bar { width:50px; }
  .clm-gh th, .clm-gh td { padding:10px 12px; }
}

/* One font family (keep last) */
.clm-widget, .clm-widget *, .clm-widget input, .clm-widget select,
.clm-widget textarea, .clm-widget button, .clm-widget table {
  font-family: "Oxygen", "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
}
.clm-widget .fa { font-family: FontAwesome !important; }

sp_widget.script:
(function() {
    var action = input && input.action;
    var currentUserId = gs.getUserID();

    var TABLES = {
        APPROVAL_MATRIX: 'x_birl3_clm_approval_matrix',
        GROUP_REQ:       'x_birl3_clm_key_group_code_request',
        KEY_ZONAL:       'x_birl3_clm_uclm_key_zonal_parent',
        KEY_SITE:        'x_birl3_clm_clm_key_site',
        MATRIX:          'x_birl3_clm_risk_assessment_matrix',
        OUTSTANDING:     'x_birl3_clm_clm_aging_snapshot',
        DRAFT_DEMAND:    'x_birl3_clm_p1_crm_site_draft',
        CRM_GP_REQ:      'x_birl3_clm_clm_key_crm_gp_request',
        SITE_MASTER:     'x_birl3_clm_clm_customer_master1',
        CUSTOMER_MASTER: 'x_birl3_clm_clm_customer_master1',
        SALES_VALUE:     'x_birl3_clm_clm_cement_rmc_bpd_values',
        OCR_CRIF:        'x_birl3_clm_ocr_test',
        OCR_BS:          'x_birl3_clm_bs_ocr',
        OCR_CORP:        'x_birl3_clm_corpository_ocr',
        SWAP:            'x_birl3_clm_key_limit_swap'
    };

    var STANDARD_MONTHS = ['apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec', 'jan', 'feb', 'mar'];

    // A group request is "closed" (site is free again) when Approved / Rejected / Returned. Anything else = open = site locked.
    var CLOSED_REQ_STATES = ['approved', 'rejected', 'returned'];

    // LIMIT SWAP: the swap table field "approval" holds: requested / approved / rejected / returned.
    // Only "requested" (swap still pending) locks the site. Approved / Rejected / Returned free the site.
    var SWAP_APPROVAL_FIELD = 'approval';
    var SWAP_ACTIVE_APPROVALS = ['requested'];

    // SAP keeps a placeholder limit of Rs 1 on sites without a real limit. It is treated as nil when working out
    // how much a request changes the limit. Set to 0 to switch this off.
    var SAP_PLACEHOLDER_LIMIT = 1;
    function effLimit(l) {
        l = parseFloat(l) || 0;
        return (l > 0 && l <= SAP_PLACEHOLDER_LIMIT) ? 0 : l;
    }

    var reqCache = {};

    // ======================= GENERIC HELPERS =======================
    function firstValidField(gr, list) {
        for (var i = 0; i < list.length; i++) {
            if (gr.isValidField(list[i])) return list[i];
        }
        return '';
    }

    var masterProbe = new GlideRecord(TABLES.CUSTOMER_MASTER);
    var HAS_CG3 = masterProbe.isValidField('cg3');
    // field names on the customer master used for the zone / region / depot scope
    var M_ZONE   = firstValidField(masterProbe, ['zone', 'zone_code']);
    var M_REGION = firstValidField(masterProbe, ['region', 'region_code']);
    var M_DEPOT  = firstValidField(masterProbe, ['depot', 'depot_code']);

    function getSafeValue(gr, fieldsArray) {
        for (var i = 0; i < fieldsArray.length; i++) {
            if (gr.isValidField(fieldsArray[i])) {
                var val = gr.getValue(fieldsArray[i]);
                if (val !== null && val !== undefined && val.toString().trim() !== '') return val.toString().trim();
            }
        }
        return '';
    }

    // readable code; if the field is a reference (sys_id) returns its display value
    function getCode(gr, fieldsArray) {
        for (var i = 0; i < fieldsArray.length; i++) {
            if (gr.isValidField(fieldsArray[i])) {
                var val = gr.getValue(fieldsArray[i]);
                if (val !== null && val !== undefined && val.toString().trim() !== '') {
                    val = val.toString().trim();
                    if (/^[a-fA-F0-9]{32}$/.test(val)) {
                        var disp = gr.getDisplayValue(fieldsArray[i]);
                        if (disp) return disp.toString().trim();
                    }
                    return val;
                }
            }
        }
        return '';
    }

    function getName(gr, nameFields, codeFields) {
        var n = getSafeValue(gr, nameFields);
        if (n) return n;
        for (var i = 0; i < codeFields.length; i++) {
            if (gr.isValidField(codeFields[i])) {
                var raw = gr.getValue(codeFields[i]);
                if (raw && /^[a-fA-F0-9]{32}$/.test(raw.toString().trim())) {
                    var d = gr.getDisplayValue(codeFields[i]);
                    if (d) return d.toString().trim();
                }
            }
        }
        return '';
    }

    function firstNum(gr, fields) {
        for (var i = 0; i < fields.length; i++) {
            if (gr.isValidField(fields[i])) {
                var raw = gr.getValue(fields[i]);
                if (raw !== null && raw !== undefined && raw.toString().trim() !== '') {
                    var n = parseFloat(raw);
                    if (!isNaN(n)) return n;
                }
            }
        }
        return 0;
    }

    // first field that holds a number > 0, else 0
    function positiveNum(gr, fields) {
        for (var i = 0; i < fields.length; i++) {
            if (gr.isValidField(fields[i])) {
                var raw = gr.getValue(fields[i]);
                if (raw !== null && raw !== undefined && raw.toString().trim() !== '') {
                    var n = parseFloat(raw);
                    if (!isNaN(n) && n > 0) return n;
                }
            }
        }
        return 0;
    }

    // previous approved SPOC value first, else master value, else 0 (records which source was used)
    function pickVal(spocV, masterV, flags) {
        if (spocV > 0) { flags.spoc = true; return spocV; }
        if (masterV > 0) { flags.master = true; return masterV; }
        return 0;
    }

    // CRM value first (only if > 0), else master value, else 0
    function crmOrMaster(crmV, masterV) {
        var c1 = parseFloat(crmV);
        if (!isNaN(c1) && c1 > 0) return c1;
        var m1 = parseFloat(masterV);
        if (!isNaN(m1) && m1 > 0) return m1;
        return 0;
    }

    function setIfValid(gr, field, val) {
        if (gr.isValidField(field)) gr.setValue(field, val);
    }

    function setFirstValid(gr, fields, val) {
        for (var i = 0; i < fields.length; i++) {
            if (gr.isValidField(fields[i])) { gr.setValue(fields[i], val); return; }
        }
    }

    // sets a field to refId when it is a reference field, otherwise to the plain text value
    function setRefOrText(gr, field, refId, text) {
        if (!gr.isValidField(field)) return;
        var isRef = false;
        try { isRef = (gr.getElement(field).getED().getInternalType() === 'reference'); } catch (e) { isRef = false; }
        gr.setValue(field, isRef ? (refId || '') : (text || ''));
    }

    // Key customer filter: CG1 = N00 and not contractor (CG3 <> N09). prefix = 'customer.' for dot-walks
    function addKeyFilters(gr, prefix) {
        prefix = prefix || '';
        gr.addQuery(prefix + 'cg1', 'N00');
        if (HAS_CG3) gr.addQuery(prefix + 'cg3', '!=', 'N09');
    }

    // ======================= ZONE / REGION / DEPOT SCOPE =======================
    // scopeRows is filled from the logged-in user's rows in the approval matrix (see AUTHORISATION below).
    var scopeRows = [];

    function keyConds() {
        var c = ['cg1=N00'];
        if (HAS_CG3) c.push('cg3!=N09');
        return c;
    }

    // Builds one encoded query: (base conditions + one scope row) OR (base conditions + next scope row) ...
    // A blank segment / zone / region / depot on the matrix row means "no restriction" at that level.
    function scopeQueryString(baseConds) {
        if (!scopeRows.length) return null;
        var parts = [];
        scopeRows.forEach(function(sr) {
            var c = (baseConds || []).slice();
            if (sr.segment) c.push('segment=' + sr.segment);
            if (sr.zone   && M_ZONE)   c.push(M_ZONE   + '=' + sr.zone);
            if (sr.region && M_REGION) c.push(M_REGION + '=' + sr.region);
            if (sr.depot  && M_DEPOT)  c.push(M_DEPOT  + '=' + sr.depot);
            parts.push(c.join('^'));
        });
        return parts.join('^NQ');
    }

    // restricts a customer master query to Key sites inside the user's segment / zone / region / depot
    function applyScope(gr, extraConds) {
        var q = scopeQueryString(keyConds().concat(extraConds || []));
        if (q === null) { gr.addQuery('sys_id', 'NONE'); return; }
        gr.addEncodedQuery(q);
    }

    // value / display value of a field (default 'state') matches one of the list items
    function fieldIn(gr, fieldName, list) {
        if (!gr.isValidField(fieldName)) return false;
        var sv = (gr.getValue(fieldName) || '').toString().trim().toLowerCase();
        var sd = (gr.getDisplayValue(fieldName) || '').toString().trim().toLowerCase();
        return list.indexOf(sv) !== -1 || list.indexOf(sd) !== -1;
    }
    function stateIn(gr, list) { return fieldIn(gr, 'state', list); }

    // group request by sys_id or by number (group_request on child tables may be a reference or plain text)
    function getReq(ref) {
        ref = (ref || '').toString().trim();
        if (!ref) return null;
        if (reqCache.hasOwnProperty(ref)) return reqCache[ref];
        var rq = new GlideRecord(TABLES.GROUP_REQ);
        var found = false;
        if (/^[a-fA-F0-9]{32}$/.test(ref)) {
            found = rq.get(ref);
        } else {
            rq.addQuery('number', ref);
            rq.setLimit(1);
            rq.query();
            found = rq.next();
        }
        reqCache[ref] = found ? rq : null;
        return reqCache[ref];
    }
    function isReqClosed(rq)   { return stateIn(rq, CLOSED_REQ_STATES); }
    function isReqApproved(rq) { return stateIn(rq, ['approved']); }

    // SITE-LEVEL lock: site already inside an open (not Approved / Rejected / Returned) request
    function getOpenRequestLocks(codes) {
        var map = {};
        if (!codes || codes.length === 0) return map;
        var ks = new GlideRecord(TABLES.KEY_SITE);
        ks.addQuery('site_code', 'IN', codes.join(','));
        ks.query();
        while (ks.next()) {
            var sc = (ks.getValue('site_code') || '').trim();
            if (!sc || map[sc]) continue;
            var rq = getReq(ks.getValue('group_request'));
            if (rq && !isReqClosed(rq)) map[sc] = rq.getValue('number') || rq.getUniqueValue();
        }
        return map;
    }

    // a swap record is ACTIVE only while its "approval" field is "requested".
    // approved / rejected / returned => swap finished => no lock.
    function swapIsActive(sw) {
        if (!sw.isValidField(SWAP_APPROVAL_FIELD)) {
            gs.warn('CLM Central SPOC: field "' + SWAP_APPROVAL_FIELD + '" not found on ' + TABLES.SWAP + ' - treating every swap as active');
            return true;
        }
        return fieldIn(sw, SWAP_APPROVAL_FIELD, SWAP_ACTIVE_APPROVALS);
    }

    // LIMIT SWAP lock: site is donor or donee (customer_code_sap) of a swap whose approval = requested.
    function getSwapLocks(codes, custIdByCode) {
        var map = {};
        var sw = new GlideRecord(TABLES.SWAP);
        if (!sw.isValid() || !codes || codes.length === 0) return map;

        var keys = codes.slice(), idToCode = {}, codeSet = {};
        codes.forEach(function(cd) {
            codeSet[cd] = true;
            if (custIdByCode && custIdByCode[cd]) { keys.push(custIdByCode[cd]); idToCode[custIdByCode[cd]] = cd; }
        });

        var qc = sw.addQuery('donee', 'IN', keys.join(','));
        qc.addOrCondition('donor', 'IN', keys.join(','));
        sw.query();
        while (sw.next()) {
            if (!swapIsActive(sw)) continue;   // approved / rejected / returned -> no lock
            var ref = sw.isValidField('number') ? sw.getValue('number') : sw.getUniqueValue();
            ['donee', 'donor'].forEach(function(f) {
                var raw = (sw.getValue(f) || '').toString().trim();
                var cd = idToCode[raw] || raw;
                if (codeSet[cd] && !map[cd]) map[cd] = { ref: ref, role: f };
            });
        }
        return map;
    }

    // GRANDPARENT-LEVEL locks (not limited to the user's zone / region / depot):
    //  - req  : any group request under the Grandparent that is still open (not Approved / Rejected / Returned)
    //  - swap : any Key site of the Grandparent that is donor / donee of a swap with approval = requested
    // While either exists, NO site under the Grandparent can be raised for a new request.
    function getGpLocks(gp) {
        var out = { req: null, swap: null };
        gp = (gp || '').toString().trim();
        if (!gp) return out;

        var rq = new GlideRecord(TABLES.GROUP_REQ);
        rq.addQuery('grandparent_code', gp);
        rq.query();
        while (rq.next()) {
            if (isReqClosed(rq)) continue;
            out.req = { ref: rq.getValue('number') || rq.getUniqueValue(), group: rq.getValue('group_code') || '' };
            break;
        }

        var codes = [], cust = {};
        var m = new GlideRecord(TABLES.CUSTOMER_MASTER);
        m.addQuery('grand_parent', gp);
        addKeyFilters(m);
        m.query();
        while (m.next()) {
            var cd = getSafeValue(m, ['customer_code_sap']);
            if (cd) { codes.push(cd); cust[cd] = m.getUniqueValue(); }
        }
        var sl = getSwapLocks(codes, cust);
        var sk = Object.keys(sl);
        if (sk.length) out.swap = { ref: sl[sk[0]].ref, role: sl[sk[0]].role, site: sk[0] };
        return out;
    }

    // worst external rating (A best, C worst) entered on earlier requests of this GP (needs field entered_external_rating)
    function gpWorstEnteredRating(gp) {
        var rank = { A: 1, B: 2, C: 3 }, worst = '';
        var g = new GlideRecord(TABLES.GROUP_REQ);
        if (!g.isValidField('entered_external_rating')) return '';
        g.addQuery('grandparent_code', gp);
        g.addQuery('entered_external_rating', '!=', '');
        g.query();
        while (g.next()) {
            if (stateIn(g, ['rejected', 'returned'])) continue;
            var r = (g.getValue('entered_external_rating') || '').toUpperCase();
            if (rank[r] && (!worst || rank[r] > rank[worst])) worst = r;
        }
        return worst;
    }

    // total outstanding of one snapshot row
    function osTotal(gr) {
        var f = ['total_outstanding', 'u_net_balance'];
        for (var i = 0; i < f.length; i++) {
            if (gr.isValidField(f[i])) {
                var v = gr.getValue(f[i]);
                if (v !== null && v !== undefined && v !== '') return Math.abs(parseFloat(v)) || 0;
            }
        }
        var b = ['bucket_0_30_days', 'bucket_31_45_days', 'bucket_46_60_days', 'bucket_61_75_days', 'bucket_76_90_days',
                 'bucket_91_120_days', 'bucket_121_180_days', 'bucket_181_365_days', 'bucket_366_730_days', 'bucket_730_above'];
        var sum = 0;
        for (var j = 0; j < b.length; j++) sum += firstNum(gr, [b[j]]);
        return Math.abs(sum);
    }

    function bucketsOf(r) {
        return {
            b0_30:  firstNum(r, ['bucket_0_30_days']),
            b31_45: firstNum(r, ['bucket_31_45_days']),
            b46_60: firstNum(r, ['bucket_46_60_days']),
            b61_75: firstNum(r, ['bucket_61_75_days']),
            b76_90: firstNum(r, ['bucket_76_90_days']),
            b91_120: firstNum(r, ['bucket_91_120_days']),
            bGt120: firstNum(r, ['bucket_121_180_days']) + firstNum(r, ['bucket_181_365_days']) +
                    firstNum(r, ['bucket_366_730_days']) + firstNum(r, ['bucket_730_above']) +
                    firstNum(r, ['bucket_gt120_days'])
        };
    }
    function zeroB() { return { b0_30: 0, b31_45: 0, b46_60: 0, b61_75: 0, b76_90: 0, b91_120: 0, bGt120: 0 }; }

    // Grandparent level snapshot stats (N09 excluded):
    //  - latest snapshot of every customer -> outstanding per site, sales
    //  - last 6 distinct months across the GP -> average ageing distribution for the internal rating
    function gpSnapshotStats(gp) {
        var res = { osMap: {}, avgMonthlySales: 0, customers: 0, months: 0, b: zeroB() };
        var seen = {}, perMonth = {}, monthKeys = [];

        var o = new GlideRecord(TABLES.OUTSTANDING);
        o.addQuery('customer.grand_parent', gp);
        addKeyFilters(o, 'customer.');
        o.orderByDesc('snapshot_month');
        o.query();
        while (o.next()) {
            var cid = o.getValue('customer');
            if (!cid) continue;

            if (!seen[cid]) {
                seen[cid] = true;
                res.customers++;
                res.osMap[cid] = osTotal(o);
                res.avgMonthlySales += firstNum(o, ['sales_prev_month']);
            }

            var mKey = (o.getValue('snapshot_month') || '').toString().split(' ')[0];
            if (!perMonth[mKey]) {
                if (monthKeys.length >= 6) continue;
                perMonth[mKey] = zeroB();
                monthKeys.push(mKey);
            }
            var bk = bucketsOf(o), pm = perMonth[mKey];
            for (var k in bk) pm[k] += bk[k];
        }
        res.months = monthKeys.length;
        monthKeys.forEach(function(m) {
            for (var k in perMonth[m]) res.b[k] += perMonth[m][k] / monthKeys.length;   // monthly average
        });
        return res;
    }

    // Internal rating from the grandparent level buckets (FRS).
    // L = 0-60, M = 61-75, N = 76-90, O = 91+.  Zero outstanding -> A.  A: L>=80 & N+O<=10 ; B: L>=60 & N+O<=20 ; else C.
    function buildCredit(b, customers, months) {
        var safe = b.b0_30 + b.b31_45 + b.b46_60, mid = b.b61_75, crit = b.b76_90, tox = b.b91_120 + b.bGt120;
        var grand = safe + mid + crit + tox;
        var internal = 'A', pctL = 0, pctCT = 0;
        if (grand > 0) {
            pctL = (safe / grand) * 100;
            pctCT = ((crit + tox) / grand) * 100;
            if (pctL >= 80 && pctCT <= 10) internal = 'A';
            else if (pctL >= 60 && pctCT <= 20) internal = 'B';
            else internal = 'C';
        }

        var rows = [
            { label: '0-30',   group: 'safe', amt: b.b0_30 },
            { label: '31-45',  group: 'safe', amt: b.b31_45 },
            { label: '46-60',  group: 'safe', amt: b.b46_60 },
            { label: '61-75',  group: 'warn', amt: b.b61_75 },
            { label: '76-90',  group: 'warn', amt: b.b76_90 },
            { label: '91-120', group: 'risk', amt: b.b91_120 },
            { label: '>120',   group: 'risk', amt: b.bGt120 }
        ];
        rows.forEach(function(r) { r.pct = grand > 0 ? (r.amt / grand) * 100 : 0; });

        return { buckets: rows, total: grand, internal: internal, external: '', p3Factor: 0,
                 pctSafe: pctL, pctCritical: pctCT, customers: customers, months: months || 0, prevExtRating: '' };
    }

    // Latest values previously submitted by the Central SPOC (key site table) per site code.
    // ONLY from Approved requests (settled figures). CRM draft values are intentionally NOT used here.
    function gpSpocMap(codes) {
        var map = {};
        if (!codes || codes.length === 0) return map;
        var k = new GlideRecord(TABLES.KEY_SITE);
        k.addQuery('site_code', 'IN', codes.join(','));
        k.orderByDesc('sys_created_on');
        k.query();
        while (k.next()) {
            var sc = (k.getValue('site_code') || '').trim();
            if (!sc || map[sc]) continue;
            var rqK = getReq(k.getValue('group_request'));
            if (!rqK || !isReqApproved(rqK)) continue;   // change to: if (!rqK || !isReqClosed(rqK)) continue;  to also accept Rejected/Returned
            map[sc] = {
                monthly:  positiveNum(k, ['site_monthly_potential']),
                current:  positiveNum(k, ['site_current_potential']),
                expected: positiveNum(k, ['site_expected_potential']),
                rate:     positiveNum(k, ['site_rate']),
                tenor:    positiveNum(k, ['credit_tenor', 'site_credit_tenor'])
            };
        }
        return map;
    }

    // map of customer_code_sap -> salesorg
    function salesOrgByCodes(codes) {
        var map = {};
        if (!codes || codes.length === 0) return map;
        var g = new GlideRecord(TABLES.CUSTOMER_MASTER);
        g.addQuery('customer_code_sap', 'IN', codes.join(','));
        g.query();
        while (g.next()) {
            var code = getSafeValue(g, ['customer_code_sap']);
            var so = getSafeValue(g, ['salesorg']);
            if (code && so && !map[code]) map[code] = so;
        }
        return map;
    }

    function segDefaultSalesOrg(segName) {
        var s = (segName || '').toLowerCase();
        if (s.indexOf('cement') !== -1) return '6000';
        if (s.indexOf('bpd') !== -1) return '8000';
        return '';   // RMC: always read from the master record
    }

    // LIVE credit limit / BG from the SAP WSDL, plus the "active" (unexpired) BG.
    function getLiveCredit(code, salesOrg, expiryRaw) {
        var r = { ok: false, limit: 0, bg: 0, activeBg: 0, expiry: expiryRaw || '' };
        code = (code || '').toString().trim();
        if (!code) return r;

        try {
            var wsdl = new x_birl3_clm.CLM_NEW_WSDL1();
            var resp = wsdl.getCreditDetails(code, (salesOrg || '').toString().trim());
            if (resp) {
                var js = JSON.parse(resp);
                r.limit = parseFloat(js.creditLimit) || 0;
                r.bg = Math.abs(parseFloat(js.actBg)) || 0;
                if (js.expryDate && js.expryDate != "0000-00-00") r.expiry = js.expryDate;
                r.ok = true;
            }
        } catch (apiErr) {
            gs.error("CLM API Error for " + code + ": " + apiErr.message);
        }

        if (!r.expiry) {
            var expGr = new GlideRecord(TABLES.CUSTOMER_MASTER);
            expGr.addQuery('customer_code_sap', code);
            expGr.setLimit(1);
            expGr.query();
            if (expGr.next()) r.expiry = getSafeValue(expGr, ['bg_expiry_date']);
        }

        if (r.bg > 0 && r.expiry && r.expiry !== "0000-00-00") {
            try {
                var expPart = r.expiry.toString().split(' ')[0];
                var expDt = new GlideDateTime(expPart + ' 23:59:59');
                if (expDt.compareTo(new GlideDateTime()) >= 0) r.activeBg = r.bg;
            } catch (dErr) { /* ignore bad date */ }
        }
        return r;
    }

    // NOD (cement only): outstanding / (annual sales / 12) * 30
    function calcSiteNOD(custSysId, segment, tableOs) {
        if (!custSysId || !segment || segment.toLowerCase().indexOf('cement') === -1) return 0;
        var p1 = Math.abs(parseFloat(tableOs)) || 0;

        var totalSales = 0;
        var valGr = new GlideRecord(TABLES.SALES_VALUE);
        valGr.addQuery('u_customer', custSysId);
        valGr.orderByDesc('sys_created_on');
        valGr.setLimit(1);
        valGr.query();
        if (valGr.next()) {
            STANDARD_MONTHS.forEach(function(m) {
                var val = valGr.isValidField(m) ? valGr.getValue(m) : valGr.getValue('u_' + m);
                totalSales += parseFloat(val) || 0;
            });
        }
        var p2 = totalSales / 12;

        if (!(p2 > 0)) {
            var sn = new GlideRecord(TABLES.OUTSTANDING);
            sn.addQuery('customer', custSysId);
            sn.orderByDesc('snapshot_month');
            sn.setLimit(1);
            sn.query();
            if (sn.next()) p2 = parseFloat(sn.getValue('sales_prev_month')) || 0;
        }
        return p2 > 0 ? Math.round((p1 / p2) * 30) : 0;
    }

    // server-side validation of one site row (mirrors the client rules)
    function validateSiteRow(st) {
        var errs = [];
        var label = st.site_code || 'Site';
        var mp   = parseFloat(st.monthly_potential);
        var cp   = parseFloat(st.current_potential);
        var ep   = parseFloat(st.expected_potential);
        var rate = parseFloat(st.order_rate);
        var ten  = parseFloat(st.credit_tenor);
        var lim  = parseFloat(st.requested_limit);

        if (!(mp > 0))   errs.push(label + ': Monthly Potential must be greater than 0');
        if (!(cp > 0))   errs.push(label + ': Current Potential must be greater than 0');
        if (!(ep > 0))   errs.push(label + ': Expected Potential must be greater than 0');
        if (!(rate > 0)) errs.push(label + ': Order Rate must be greater than 0');
        if (!(ten > 0))  errs.push(label + ': Credit Tenor must be greater than 0');
        if (!(lim > 0))  errs.push(label + ': Desired Limit must be greater than 0');
        if (mp > 0 && cp > mp) errs.push(label + ': Current Potential cannot exceed Monthly Potential');
        if (mp > 0 && ep > mp) errs.push(label + ': Expected Potential cannot exceed Monthly Potential');
        return errs;
    }

    var riskParamDefs = [
        { k: 'age_of_company',      label: "Age of Company",      weight: 0.05, options: [ {key:'b', label:"Best (> 15 Yrs)", score:10}, {key:'g', label:"Good (> 10 Yrs)", score:7}, {key:'a', label:"Average (> 5 Yrs)", score:5}, {key:'p', label:"Poor (< 5 Yrs)", score:2} ]},
        { k: 'segment_potential',   label: "Segment Potential",   weight: 0.10, options: [ {key:'b', label:"Best (> 25,000 MT)", score:10}, {key:'g', label:"Good (10k-25k MT)", score:7}, {key:'a', label:"Average (3k-10k MT)", score:5}, {key:'p', label:"Poor (< 3,000 MT)", score:2} ]},
        { k: 'current_share',       label: "Current Share %",     weight: 0.08, options: [ {key:'b', label:"Best (> 70)", score:10}, {key:'g', label:"Good (50-70)", score:7}, {key:'a', label:"Average (30-50)", score:5}, {key:'p', label:"Poor (< 30)", score:2} ]},
        { k: 'sector_of_operation', label: "Sector of Operation", weight: 0.05, options: [ {key:'b', label:"Best (Port/Dam/PSU)", score:10}, {key:'g', label:"Good (Road/Rail/Power)", score:7}, {key:'a', label:"Average (Urban/Comm.)", score:5}, {key:'p', label:"Poor (Others)", score:2} ]},
        { k: 'corporate_body',      label: "Corporate Body",      weight: 0.05, options: [ {key:'b', label:"Best (Top 15/MNC)", score:10}, {key:'g', label:"Good (Unlisted Intl.)", score:7}, {key:'a', label:"Average (Unlisted Ltd)", score:5}, {key:'p', label:"Poor (Pvt/Partner/Prop)", score:2} ]},
        { k: 'mgmt_competence',     label: "Mgmt Competence",     weight: 0.05, options: [ {key:'b', label:"Excellent", score:10}, {key:'g', label:"V. Good", score:7}, {key:'a', label:"Good", score:5}, {key:'p', label:"Average", score:2} ]},
        { k: 'revenue',             label: "Revenue Turn",        weight: 0.05, options: [ {key:'b', label:"Best (> 100 CR)", score:10}, {key:'g', label:"Good (50-100 CR)", score:7}, {key:'a', label:"Average (10-50 CR)", score:5}, {key:'p', label:"Poor (< 10 CR)", score:2} ]},
        { k: 'sales_growth',        label: "Sales Growth (CAGR)", weight: 0.03, options: [ {key:'b', label:"Best (> 20%)", score:10}, {key:'g', label:"Good (10-20%)", score:7}, {key:'a', label:"Average (5-10%)", score:5}, {key:'p', label:"Poor (< 5%)", score:2} ]},
        { k: 'gross_profit',        label: "Gross Profit %",      weight: 0.02, options: [ {key:'b', label:"Best (> 20%)", score:10}, {key:'g', label:"Good (10-20%)", score:7}, {key:'a', label:"Average (5-10%)", score:5}, {key:'p', label:"Poor (< 5%)", score:2} ]},
        { k: 'ebitda',              label: "EBITDA Margin",       weight: 0.02, options: [ {key:'b', label:"Best (> 15%)", score:10}, {key:'g', label:"Good (10-15%)", score:7}, {key:'a', label:"Average (5-10%)", score:5}, {key:'p', label:"Poor (< 5%)", score:2} ]},
        { k: 'dept_to_equity',      label: "Debt to Equity",      weight: 0.02, options: [ {key:'b', label:"Best (< 0.5)", score:10}, {key:'g', label:"Good (0.5-1.0)", score:7}, {key:'a', label:"Average (1.0-2.0)", score:5}, {key:'p', label:"Poor (> 2.0)", score:2} ]},
        { k: 'int_coverage',        label: "Interest Coverage",   weight: 0.02, options: [ {key:'b', label:"Best (> 4.0)", score:10}, {key:'g', label:"Good (3.0-4.0)", score:7}, {key:'a', label:"Average (1.5-3.0)", score:5}, {key:'p', label:"Poor (< 1.5)", score:2} ]},
        { k: 'net_wcc_days',        label: "Net WCC Days",        weight: 0.02, options: [ {key:'b', label:"Best (< 30)", score:10}, {key:'g', label:"Good (30-60)", score:7}, {key:'a', label:"Average (60-90)", score:5}, {key:'p', label:"Poor (> 90)", score:2} ]},
        { k: 'ar_days',             label: "A/R Ledger Days",     weight: 0.04, options: [ {key:'b', label:"Best (< 30)", score:10}, {key:'g', label:"Good (30-60)", score:7}, {key:'a', label:"Average (60-90)", score:5}, {key:'p', label:"Poor (> 90)", score:2} ]},
        { k: 'inventory_days',      label: "Inventory Days",      weight: 0.02, options: [ {key:'b', label:"Best (< 30)", score:10}, {key:'g', label:"Good (30-60)", score:7}, {key:'a', label:"Average (60-90)", score:5}, {key:'p', label:"Poor (> 90)", score:2} ]},
        { k: 'ap_days',             label: "A/P Days",            weight: 0.04, options: [ {key:'b', label:"Best (45-75)", score:10}, {key:'g', label:"Good (30-45)", score:7}, {key:'a', label:"Average (15-30)", score:5}, {key:'p', label:"Poor (< 15 or > 120)", score:2} ]},
        { k: 'ext_rating',          label: "External Rating",     weight: 0.10, options: [ {key:'b', label:"Best (AAA to A)", score:10}, {key:'g', label:"Good (BBB+ to BBB-)", score:7}, {key:'a', label:"Average (BB / Unrated Ltd)", score:5}, {key:'p', label:"Poor (B / Prop-Partner)", score:2} ]},
        { k: 'gst_delay',           label: "GST/PF Delay",        weight: 0.05, options: [ {key:'b', label:"Best (0 Days)", score:10}, {key:'g', label:"Good (1-15 Days)", score:7}, {key:'a', label:"Average (16-60 Days)", score:5}, {key:'p', label:"Poor (> 60 Days)", score:2} ]},
        { k: 'court_cases',         label: "Court Cases",         weight: 0.10, options: [ {key:'b', label:"Best (No Cases)", score:10}, {key:'g', label:"Good (Minor Civil)", score:7}, {key:'a', label:"Average (1-2 Active)", score:5}, {key:'p', label:"Poor (Multiple/Fraud)", score:2} ]},
        { k: 'mca_compliance',      label: "MCA Compliance",      weight: 0.04, options: [ {key:'b', label:"Best (Compliant)", score:10}, {key:'g', label:"Good (Minor Delay)", score:7}, {key:'a', label:"Average (1 Default)", score:5}, {key:'p', label:"Poor (Multiple Default)", score:2} ]},
        { k: 'social_media_score',  label: "Social Media Score",  weight: 0.05, options: [ {key:'b', label:"Best (5 Star)", score:10}, {key:'g', label:"Good (4 Star)", score:7}, {key:'a', label:"Average (3 Star)", score:5}, {key:'p', label:"Poor (< 2 Star)", score:2} ]}
    ];

    function buildMatrixGroup() {
        var grouped = { "Risk Parameter Matrix": [] };
        for (var pi = 0; pi < riskParamDefs.length; pi++) {
            var def = riskParamDefs[pi];
            var paramObj = {
                k: def.k, label: def.label, weight: def.weight,
                selectedValue: '', autoMapped: false, isChanged: false,
                originalValue: '', originalLabel: '', mappingType: '',
                extractedValue: '', options: []
            };
            for (var oi = 0; oi < def.options.length; oi++) {
                var opt = def.options[oi];
                paramObj.options.push({
                    sys_id: 'key_p_' + pi + '_' + opt.key,
                    label: opt.label,
                    score: opt.score
                });
            }
            grouped["Risk Parameter Matrix"].push(paramObj);
        }
        return grouped;
    }

    // ======================= AUTHORISATION (role + segment + zone / region / depot) =======================
    var isSpoc = false;
    var authorizedSegments = [];

    var mGr = new GlideRecord(TABLES.APPROVAL_MATRIX);
    // field names of zone / region / depot on the approval matrix (blank = that column does not exist -> no restriction)
    var X_ZONE   = firstValidField(mGr, ['zone', 'zone_code']);
    var X_REGION = firstValidField(mGr, ['region', 'region_code']);
    var X_DEPOT  = firstValidField(mGr, ['depot', 'depot_code']);

    mGr.addQuery('approver_user', currentUserId);
    mGr.addQuery('role_name', 'Central Spoc');
    mGr.addQuery('customer_type', 'Key');
    mGr.query();

    var scopeSeen = {};
    while (mGr.next()) {
        isSpoc = true;
        var assignedSegment = mGr.getValue('segment') || '';
        if (assignedSegment && authorizedSegments.indexOf(assignedSegment) === -1) {
            authorizedSegments.push(assignedSegment);
        }
        var scRow = {
            segment: assignedSegment,
            zone:    X_ZONE   ? (mGr.getValue(X_ZONE)   || '') : '',
            region:  X_REGION ? (mGr.getValue(X_REGION) || '') : '',
            depot:   X_DEPOT  ? (mGr.getValue(X_DEPOT)  || '') : ''
        };
        var scKey = [scRow.segment, scRow.zone, scRow.region, scRow.depot].join('|');
        if (!scopeSeen[scKey]) { scopeSeen[scKey] = true; scopeRows.push(scRow); }
    }

    if (!action || action === 'fetch_draft_gps') {
        data.isAuthorized = isSpoc;
    }

    if (!isSpoc) return;

    if (!action) {
        data.attachmentGUID = gs.generateGUID();
        data.table = TABLES.GROUP_REQ;
        data.sys_id = data.attachmentGUID;
    }

    // ======================= OCR =======================
    if (action === 'createOcrRecord') {
        try {
            var targetOcrTable = '';
            if (input.documentType === 'CRIF') {
                targetOcrTable = TABLES.OCR_CRIF;
            } else if (input.documentType === 'Balance Sheet') {
                targetOcrTable = TABLES.OCR_BS;
            } else if (input.documentType === 'Corpository') {
                targetOcrTable = TABLES.OCR_CORP;
            } else {
                targetOcrTable = TABLES.OCR_BS;
            }

            var ocr = new GlideRecord(targetOcrTable);
            if (!ocr.isValid()) { data.error = "Backend OCR table not found."; return; }

            ocr.initialize();
            var ocrSysId = ocr.insert();
            if (input.fileData && input.fileName && input.fileType) {
                var attachment = new GlideSysAttachment();
                attachment.writeBase64(ocr, input.fileName, input.fileType, input.fileData);
            }
            data.sysId = ocrSysId;
            data.targetTable = targetOcrTable;
        } catch (e) { data.error = 'Session creation error: ' + e.message; }
        return;
    }

    if (action === 'pollOcrRecord') {
        if (!input.sysId) { data.ocrStatus = 'failed'; data.error = 'Missing session ID.'; return; }
        var diTask = new GlideRecord('sys_di_task');
        diTask.addQuery('source_record', input.sysId);
        diTask.orderByDesc('sys_created_on');
        diTask.query();

        if (diTask.next()) {
            var diStatus = (diTask.getValue('status') || '').toLowerCase();
            if (diStatus === 'error' || diStatus === 'skipped' || diStatus === 'failed') {
                data.ocrStatus = 'failed'; return;
            }
        }

        var targetTable = input.targetTable || TABLES.OCR_BS;
        var rec = new GlideRecord(targetTable);
        if (rec.get(input.sysId)) {

            var checkFields = ['name_of_company', 'net_revenue', 'rating', 'risk_index', 'ap_days', 'u_ap_days', 'u_customer_name', 'customer_name', 'u_total_revenue___sales', 'u_total_revenue_sales', 'total_revenue', 'u_total_revenue', 'u_total_equity', 'total_equity', 'u_net_worth', 'u_a_p_days'];

            var hasDataExtracted = false;
            for (var i = 0; i < checkFields.length; i++) {
                if (rec.isValidField(checkFields[i]) && rec.getValue(checkFields[i]) !== null && rec.getValue(checkFields[i]) !== '') {
                    hasDataExtracted = true;
                    break;
                }
            }

            if (hasDataExtracted) {
                data.ocrStatus = 'success';
                data.result = {
                    court_cases:    getSafeValue(rec, ['court_cases']),
                    rating:         getSafeValue(rec, ['rating']),
                    risk_index:     getSafeValue(rec, ['risk_index']),
                    ap_days:        getSafeValue(rec, ['ap_days', 'u_ap_days', 'u_a_p_days']),
                    ar_days:        getSafeValue(rec, ['ar_days', 'u_ar_days', 'u_a_r_days']),
                    ebitda:         getSafeValue(rec, ['ebitda', 'u_ebitda_percent', 'u_ebitda__']),
                    gross_profit:   getSafeValue(rec, ['gross_profit', 'u_gross_profit_percent', 'u_gross_profit__']),
                    int_coverage:   getSafeValue(rec, ['int_coverage', 'u_interest_coverage', 'u_int_coverage', 'u_int__coverage']),
                    inventory_days: getSafeValue(rec, ['inventory_days', 'u_inventory_days']),
                    net_revenue:    getSafeValue(rec, ['net_revenue', 'u_total_revenue___sales', 'u_total_revenue_sales', 'total_revenue', 'u_total_revenue', 'u_sales']),
                    net_wcc_days:   getSafeValue(rec, ['net_wcc_days', 'u_net_wcc_days']),
                    sales_growth:   getSafeValue(rec, ['sales_growth', 'u_sales_growth', 'u_sales_growth_pct']),
                    debt_equity:    getSafeValue(rec, ['debt_equity', 'u_debt_to_equity']),
                    net_worth:      getSafeValue(rec, ['networth', 'total_equity', 'u_total_equity', 'u_net_worth']),
                    loans_advances: getSafeValue(rec, ['loans_advances', 'loan_advances'])
                };
            } else {
                data.ocrStatus = 'processing';
            }
        } else { data.ocrStatus = 'failed'; }
        return;
    }

    // ======================= GP / GROUP LISTS (limited to the user's zone / region / depot) =======================
    if (action === 'fetch_draft_gps') {
        data.distinctGPCodes = [];
        var seenGp = {};

        if (scopeRows.length > 0) {
            var gpAgg = new GlideAggregate(TABLES.CUSTOMER_MASTER);
            applyScope(gpAgg);
            gpAgg.groupBy('grand_parent');
            gpAgg.query();

            while (gpAgg.next()) {
                var gcRaw = (gpAgg.getValue('grand_parent') || '').trim();
                if (gcRaw) {
                    var gcUpper = gcRaw.toUpperCase();
                    if (!seenGp[gcUpper]) {
                        seenGp[gcUpper] = true;
                        data.distinctGPCodes.push(gcUpper);
                    }
                }
            }
            data.distinctGPCodes.sort();
        }
    }

    if (action === 'fetch_draft_groups') {
        data.distinctGroupCodes = [];
        var fetchGpUpper = (input.gpCode || '').trim().toUpperCase();
        var seenGrp = {};

        if (fetchGpUpper && scopeRows.length > 0) {
            var grpAgg = new GlideAggregate(TABLES.CUSTOMER_MASTER);
            applyScope(grpAgg, ['grand_parent=' + input.gpCode]);
            grpAgg.groupBy('groupcode');
            grpAgg.query();

            while (grpAgg.next()) {
                var grpcRaw = (grpAgg.getValue('groupcode') || '').trim();
                if (grpcRaw) {
                    var grpcUpper = grpcRaw.toUpperCase();
                    if (!seenGrp[grpcUpper]) {
                        seenGrp[grpcUpper] = true;
                        data.distinctGroupCodes.push(grpcUpper);
                    }
                }
            }
            data.distinctGroupCodes.sort();
        }
    }

    // ======================= GRANDPARENT OVERVIEW (all sites of the GP, for Grandparent-wide calculation) =======================
    if (action === 'fetch_gp_overview') {
        try {
            var ovGp = (input.gpCode || '').trim();

            // the Grandparent must have at least one site inside the user's zone / region / depot
            var accChk = new GlideRecord(TABLES.CUSTOMER_MASTER);
            applyScope(accChk, ['grand_parent=' + ovGp]);
            accChk.setLimit(1);
            accChk.query();
            if (!accChk.hasNext()) {
                data.error = 'No sites of this Grandparent Code fall under your zone / region / depot.';
                return;
            }

            var ovCodeList = [];
            var preGr = new GlideRecord(TABLES.CUSTOMER_MASTER);
            preGr.addQuery('grand_parent', ovGp);
            addKeyFilters(preGr);
            preGr.query();
            while (preGr.next()) {
                var preCode = getSafeValue(preGr, ['customer_code_sap']);
                if (preCode) ovCodeList.push(preCode);
            }

            var ovGr = new GlideRecord(TABLES.CUSTOMER_MASTER);
            ovGr.addQuery('grand_parent', ovGp);
            addKeyFilters(ovGr);
            ovGr.orderBy('groupcode');
            ovGr.orderBy('customer_code_sap');
            ovGr.query();

            var snap = gpSnapshotStats(ovGp);
            var ovOs = snap.osMap;
            var spocMap = gpSpocMap(ovCodeList);   // approved Central SPOC submissions only

            var ovGroups = {}, ovOrder = [];
            var ovCodes = [ovGp];
            var ovTotalOs = 0, ovSiteCount = 0, ovZonalSeen = {}, ovFirstSo = '', ovFirstSeg = '';
            var ovVintageDays = 0;

            while (ovGr.next()) {
                var sCode = getSafeValue(ovGr, ['customer_code_sap']);
                if (!sCode) continue;

                var gCode = getSafeValue(ovGr, ['groupcode']) || '-';
                var zCode = getCode(ovGr, ['zonalparentcode', 'zonal_parent_code']) || '-';
                var segN = ovGr.getDisplayValue('segment') || getSafeValue(ovGr, ['segment']);
                var sSo = getSafeValue(ovGr, ['salesorg']);
                var sOs = ovOs[ovGr.getUniqueValue()] || 0;

                if (!ovFirstSo && sSo) ovFirstSo = sSo;
                if (!ovFirstSeg && segN) ovFirstSeg = segN;

                // oldest first order date under the grandparent (age of company)
                try {
                    var fod = ovGr.getValue('first_order_date') || ovGr.getValue('creation_date');
                    if (fod) {
                        var vNow = new GlideDateTime();
                        var vFirst = new GlideDateTime(fod);
                        var vDays = Math.floor(((vNow.getNumericValue() - vFirst.getNumericValue()) / 1000) / 86400);
                        if (!isNaN(vDays) && vDays > ovVintageDays) ovVintageDays = vDays;
                    }
                } catch (vErr) { /* ignore bad date values */ }

                // site inputs for the NON-requested sites: last approved SPOC value, else customer master, else 0 (field by field)
                var dr = spocMap[sCode] || { monthly: 0, current: 0, expected: 0, rate: 0, tenor: 0 };
                var ms = {
                    monthly:  positiveNum(ovGr, ['total_potential', 'monthly_potential']),
                    current:  positiveNum(ovGr, ['current_potential']),
                    expected: positiveNum(ovGr, ['expected_potential']),
                    rate:     positiveNum(ovGr, ['rate']),
                    tenor:    positiveNum(ovGr, ['credit_tenor'])
                };
                var srcFlags = { spoc: false, master: false };
                var siteInp = {
                    monthly:  pickVal(dr.monthly,  ms.monthly,  srcFlags),
                    current:  pickVal(dr.current,  ms.current,  srcFlags),
                    expected: pickVal(dr.expected, ms.expected, srcFlags),
                    rate:     pickVal(dr.rate,     ms.rate,     srcFlags),
                    tenor:    pickVal(dr.tenor,    ms.tenor,    srcFlags)
                };
                siteInp.src = (srcFlags.spoc && srcFlags.master) ? 'Mixed' : (srcFlags.spoc ? 'SPOC' : (srcFlags.master ? 'Master' : 'None'));

                if (!ovGroups[gCode]) {
                    ovGroups[gCode] = { code: gCode, segMap: {}, salesOrg: '', firstSo: '', zMap: {}, zOrder: [], siteCount: 0, outstanding: 0 };
                    ovOrder.push(gCode);
                    if (gCode !== '-') ovCodes.push(gCode);
                }
                var g = ovGroups[gCode];
                if (segN) g.segMap[segN] = true;
                if (!g.firstSo && sSo) g.firstSo = sSo;

                if (!g.zMap[zCode]) {
                    g.zMap[zCode] = { code: zCode, segMap: {}, salesOrg: '', firstSo: '', sites: [], siteCount: 0, outstanding: 0 };
                    g.zOrder.push(zCode);
                    if (zCode !== '-') ovCodes.push(zCode);
                }
                var z = g.zMap[zCode];
                if (segN) z.segMap[segN] = true;
                if (!z.firstSo && sSo) z.firstSo = sSo;

                z.sites.push({
                    code: sCode,
                    name: getSafeValue(ovGr, ['customer_name', 'u_customer_name']),
                    segment: segN,
                    salesOrg: sSo,
                    custSysId: ovGr.getUniqueValue(),
                    outstanding: sOs,
                    inp: siteInp
                });
                z.siteCount++; z.outstanding += sOs;
                g.siteCount++; g.outstanding += sOs;
                ovTotalOs += sOs; ovSiteCount++;
                ovZonalSeen[gCode + '|' + zCode] = true;
            }

            var soMap = salesOrgByCodes(ovCodes);
            var groupsOut = [];
            ovOrder.forEach(function(gc) {
                var gg = ovGroups[gc];
                var gSegs = Object.keys(gg.segMap);
                var zonalsOut = gg.zOrder.map(function(zc) {
                    var zz = gg.zMap[zc];
                    var zSegs = Object.keys(zz.segMap);
                    return {
                        code: zc,
                        segment: zSegs.join(', '),
                        salesOrg: (zc !== '-' && soMap[zc]) || segDefaultSalesOrg(zSegs[0]) || zz.firstSo,
                        siteCount: zz.siteCount,
                        outstanding: zz.outstanding,
                        sites: zz.sites
                    };
                });
                groupsOut.push({
                    code: gc,
                    segment: gSegs.join(', '),
                    salesOrg: (gc !== '-' && soMap[gc]) || segDefaultSalesOrg(gSegs[0]) || gg.firstSo,
                    zonalCount: zonalsOut.length,
                    siteCount: gg.siteCount,
                    outstanding: gg.outstanding,
                    zonals: zonalsOut
                });
            });

            var creditOut = buildCredit(snap.b, snap.customers, snap.months);
            creditOut.prevExtRating = gpWorstEnteredRating(ovGp);

            data.gpOverview = {
                gpCode: ovGp,
                salesOrg: soMap[ovGp] || segDefaultSalesOrg(ovFirstSeg) || ovFirstSo,
                outstanding: ovTotalOs,
                siteCount: ovSiteCount,
                zonalCount: Object.keys(ovZonalSeen).length,
                vintageDays: ovVintageDays,
                avgMonthlySales: snap.avgMonthlySales,
                credit: creditOut,
                groups: groupsOut
            };
        } catch (ovErr) {
            gs.error('Central SPOC widget - fetch_gp_overview failed: ' + ovErr.message);
            data.error = ovErr.message;
        }
    }

    // ======================= LIVE CREDIT LIMIT / ACTIVE BG (+NOD) =======================
    if (action === 'fetch_live') {
        try {
            var lv = getLiveCredit(input.code, input.salesOrg, input.bgExpiryRaw || '');

            var lvNod = 0;
            if (input.custSysId) {
                lvNod = calcSiteNOD(input.custSysId, input.segment || '', input.outstanding);
            }

            data.liveData = { limit: lv.limit, bg: lv.bg, activeBg: lv.activeBg, bgExpiry: lv.expiry || '', nod: lvNod };
        } catch (lvErr) {
            gs.error('Central SPOC widget - fetch_live failed: ' + lvErr.message);
            data.liveData = { limit: 0, bg: 0, activeBg: 0, bgExpiry: '', nod: 0 };
        }
    }

    // ======================= 6-MONTH AGEING FOR ONE SITE =======================
    if (action === 'fetch_buckets') {
        data.buckets = [];
        if (input.custSysId) {
            var bkGr = new GlideRecord(TABLES.OUTSTANDING);
            bkGr.addQuery('customer', input.custSysId);
            bkGr.orderByDesc('snapshot_month');
            bkGr.setLimit(6);
            bkGr.query();
            while (bkGr.next()) {
                var x90 = firstNum(bkGr, ['bucket_91_120_days']) + firstNum(bkGr, ['bucket_121_180_days']) +
                          firstNum(bkGr, ['bucket_181_365_days']) + firstNum(bkGr, ['bucket_366_730_days']) +
                          firstNum(bkGr, ['bucket_730_above']);
                if (!x90) x90 = firstNum(bkGr, ['bucket_gt120_days']);
                data.buckets.push({
                    month: (bkGr.getValue('snapshot_month') || '').split(' ')[0],
                    b0:  firstNum(bkGr, ['bucket_0_30_days']),
                    b31: firstNum(bkGr, ['bucket_31_45_days']),
                    b46: firstNum(bkGr, ['bucket_46_60_days']),
                    b61: firstNum(bkGr, ['bucket_61_75_days']),
                    b76: firstNum(bkGr, ['bucket_76_90_days']),
                    b90: x90,
                    total: osTotal(bkGr)
                });
            }
        }
    }

    // ======================= SITES OF ONE GROUP (site selection page) =======================
    if (action === 'load_draft_by_group') {
      try {
        var groupCode = (input.groupCode || '').trim();
        var gpCode = (input.gpCode || '').trim();

        var stagingSysIds = [];
        var custName = '';
        var compType = 'Unlisted';
        var crmJustification = '';

        var crmDocumentLink = '';
        var crmDocumentName = '';
        var crmDocumentViewUrl = '';

        var crmGpReqId = '';
        var crmGpReqNumber = '';
        var crmGpReqState = '';
        var crmGpReqSubmittedBy = '';

        var latestDraft = {};
        var draftOrder = [];

        // CRM drafts that belong to a CLOSED request (Approved / Rejected / Returned) are ignored -> clean slate
        var sGr = new GlideRecord(TABLES.DRAFT_DEMAND);
        sGr.addQuery('grandparent_code', gpCode);
        sGr.addQuery('group_code', groupCode);
        sGr.orderByDesc('sys_created_on');
        sGr.query();

        while (sGr.next()) {
            var dCode = (sGr.getValue('site_code') || '').trim();
            if (!dCode) continue;

            var st = sGr.getValue('status');
            var tr = sGr.getValue('target_request');

            // a draft linked to a CLOSED request (Approved / Rejected / Returned) is ignored whatever its status is
            if (tr) {
                var trReq = getReq(tr);
                if (trReq && isReqClosed(trReq)) continue;
            }

            stagingSysIds.push(sGr.getUniqueValue());

            var rowCrmReq = sGr.isValidField('crm_gp_request') ? (sGr.getValue('crm_gp_request') || '') : '';
            if (!crmGpReqId && rowCrmReq) crmGpReqId = rowCrmReq;

            if (!custName) {
                custName = sGr.getValue('customer_name');
                compType = sGr.getValue('company_type') || 'Unlisted';
            }
            if (!crmJustification && sGr.getValue('justification')) {
                crmJustification = sGr.getValue('justification');
            }

            if (!crmDocumentLink && sGr.getValue('u_document_link')) {
                crmDocumentLink = sGr.getValue('u_document_link');

                var attId = '';
                if (/^[a-fA-F0-9]{32}$/.test(crmDocumentLink)) {
                    attId = crmDocumentLink;
                    crmDocumentViewUrl = '/sys_attachment.do?sys_id=' + attId + '&view=true';
                } else {
                    var m = crmDocumentLink.match(/sys_id=([a-fA-F0-9]{32})/);
                    if (m) {
                        attId = m[1];
                        if (crmDocumentLink.indexOf('view=true') === -1) {
                            crmDocumentViewUrl = crmDocumentLink + '&view=true';
                        } else {
                            crmDocumentViewUrl = crmDocumentLink;
                        }
                    } else {
                        crmDocumentViewUrl = crmDocumentLink;
                    }
                }

                if (attId) {
                    var attGr0 = new GlideRecord('sys_attachment');
                    if (attGr0.get(attId)) {
                        crmDocumentName = attGr0.getValue('file_name');
                    } else {
                        crmDocumentName = 'Attached_Document.pdf';
                    }
                } else {
                    var rawName = crmDocumentLink.split('/').pop().split('?')[0];
                    crmDocumentName = rawName ? rawName : 'Attached_Document.pdf';
                }
            }

            if (!latestDraft[dCode]) {
                draftOrder.push(dCode);
                latestDraft[dCode] = {
                    sys_id: sGr.getUniqueValue(),
                    crm_gp_request: rowCrmReq || crmGpReqId,
                    customer_name: sGr.getValue('customer_name') || '',
                    segment: sGr.getValue('segment') || '',
                    zonal_parent_code: sGr.getValue('zone_code') || '',
                    region_code: sGr.getValue('region') || '',
                    monthly_potential: parseFloat(sGr.getValue('monthly_potential')) || null,
                    current_potential: firstNum(sGr, ['current_potential', 'current_sob']),
                    expected_potential: firstNum(sGr, ['expected_potential', 'expected_sob_qty']),
                    expected_sob_qty: parseFloat(sGr.getValue('expected_sob_qty')) || 0,
                    order_rate: parseFloat(sGr.getValue('order_rate')) || null,
                    credit_tenor: parseInt(sGr.getValue('credit_tenor'), 10) || null,
                    requested_limit: parseFloat(sGr.getValue('desired_limit')) || null,
                    justification: sGr.getValue('justification') || '',
                    deviation_justification: sGr.getValue('deviation_justification') || '',
                    status: sGr.getValue('status') || 'Pending SPOC',
                    grandparent_cl: parseFloat(sGr.getValue('grandparent_cl')) || 0,
                    groupcode_cl: parseFloat(sGr.getValue('groupcode_cl')) || 0,
                    zonalparent_cl: parseFloat(sGr.getValue('zonalparent_cl')) || 0,
                    site_cl: parseFloat(sGr.getValue('site_cl')) || 0,
                    target_request: sGr.getValue('target_request') || ''
                };
            }
        }

        if (crmGpReqId) {
            var crmReqGr = new GlideRecord(TABLES.CRM_GP_REQ);
            if (crmReqGr.get(crmGpReqId)) {
                crmGpReqNumber      = crmReqGr.getValue('number') || '';
                crmGpReqState       = crmReqGr.getDisplayValue('state') || '';
                crmGpReqSubmittedBy = crmReqGr.getDisplayValue('submitted_by') || '';
            }
        }

        var sites = [];
        var siteSeen = {};
        var custSysIds = [];

        var buildSite = function(code, dr, mm) {
            dr = dr || null;
            mm = mm || {};

            var isCRM = (dr !== null);

            // Step 2 grid values: CRM value if entered (> 0), else customer master, else 0
            var monthly_pot  = crmOrMaster(isCRM ? dr.monthly_potential : null,  mm.monthly_potential);
            var expected_pot = crmOrMaster(isCRM ? dr.expected_potential : null, mm.expected_potential);
            var current_pot  = crmOrMaster(isCRM ? dr.current_potential : null,  mm.current_potential);
            var o_rate       = crmOrMaster(isCRM ? dr.order_rate : null,          mm.rate);

            // Credit Tenor: CRM, else master, else default 45 days
            var c_tenor = crmOrMaster(isCRM ? dr.credit_tenor : null, mm.credit_tenor);
            if (!(c_tenor > 0)) c_tenor = 45;

            var req_limit = null;
            if (isCRM && dr.requested_limit !== null && dr.requested_limit !== '') {
                req_limit = parseFloat(dr.requested_limit);
            }

            return {
                sys_id: dr ? dr.sys_id : '',
                crm_gp_request: dr ? (dr.crm_gp_request || crmGpReqId) : crmGpReqId,
                cust_sys_id: mm.cust_sys_id || '',
                salesorg: mm.salesorg || '',
                bg_expiry_raw: mm.bg_expiry_raw || '',
                site_code: code,
                customer_name: mm.customer_name || (dr ? dr.customer_name : '') || custName,
                grandparent_code: gpCode,
                group_code: groupCode,
                zonal_parent_code: mm.zonal_parent_code || (dr ? dr.zonal_parent_code : '') || '-',
                zone_code: mm.zone_code || '',
                zone_name: mm.zone_name || '',
                region_code: mm.region_code || (dr ? dr.region_code : '') || '',
                region_name: mm.region_name || '',
                depot_code: mm.depot_code || '',
                depot_name: mm.depot_name || '',
                segment: mm.segment || (dr ? dr.segment : '') || 'Cement',
                monthly_potential: monthly_pot,
                current_potential: current_pot,
                expected_potential: expected_pot,
                expected_sob_qty: dr ? (parseFloat(dr.expected_sob_qty) || 0) : null,
                order_rate: o_rate,
                credit_tenor: c_tenor,
                requested_limit: req_limit,
                // values exactly as CRM entered them (kept in the payload; no longer shown on the site selection table)
                crm_monthly:  isCRM ? (dr.monthly_potential || null) : null,
                crm_current:  isCRM ? (dr.current_potential || null) : null,
                crm_expected: isCRM ? (dr.expected_potential || null) : null,
                crm_rate:     isCRM ? (dr.order_rate || null) : null,
                crm_tenor:    isCRM ? (dr.credit_tenor || null) : null,
                crm_limit:    isCRM ? (dr.requested_limit || null) : null,
                site_justification: '',
                outstanding: 0,
                justification: dr ? dr.justification : '',
                deviation_justification: dr ? dr.deviation_justification : '',
                status: dr ? dr.status : 'No CRM Draft',
                swap_locked: false, swap_ref: '', swap_role: '', gp_swap_lock: false, swap_site: '',
                req_locked: false, req_ref: '', gp_req_lock: false, req_group: ''
            };
        };

        // only sites inside the user's segment / zone / region / depot
        var grpMasterGr = new GlideRecord(TABLES.CUSTOMER_MASTER);
        applyScope(grpMasterGr, ['grand_parent=' + gpCode, 'groupcode=' + groupCode]);
        grpMasterGr.orderBy('customer_code_sap');
        grpMasterGr.query();

        while (grpMasterGr.next()) {
            var mCode = getSafeValue(grpMasterGr, ['customer_code_sap', 'u_customer_code_sap']);
            if (!mCode || siteSeen[mCode]) continue;
            siteSeen[mCode] = true;
            custSysIds.push(grpMasterGr.getUniqueValue());

            sites.push(buildSite(mCode, latestDraft[mCode], {
                cust_sys_id:       grpMasterGr.getUniqueValue(),
                salesorg:          getSafeValue(grpMasterGr, ['salesorg']),
                bg_expiry_raw:     getSafeValue(grpMasterGr, ['bg_expiry_date']),
                customer_name:     getSafeValue(grpMasterGr, ['customer_name', 'u_customer_name']),
                zonal_parent_code: getCode(grpMasterGr, ['zonalparentcode', 'zonal_parent_code']),
                segment:           getSafeValue(grpMasterGr, ['segment']),
                zone_code:         getCode(grpMasterGr, ['zone', 'zone_code']),
                zone_name:         getName(grpMasterGr, ['zone_name', 'u_zone_name'], ['zone']),
                region_code:       getCode(grpMasterGr, ['region', 'region_code']),
                region_name:       getName(grpMasterGr, ['region_name', 'u_region_name'], ['region']),
                depot_code:        getCode(grpMasterGr, ['depot', 'depot_code']),
                depot_name:        getName(grpMasterGr, ['depot_name', 'u_depot_name'], ['depot']),
                // master fallback values (CRM did not enter)
                monthly_potential:  positiveNum(grpMasterGr, ['total_potential', 'monthly_potential']),
                expected_potential: positiveNum(grpMasterGr, ['expected_potential']),
                current_potential:  positiveNum(grpMasterGr, ['current_potential']),
                rate:               positiveNum(grpMasterGr, ['rate']),
                credit_tenor:       positiveNum(grpMasterGr, ['credit_tenor'])
            }));
        }

        // ---- locks: limit swap with approval = requested (donor/donee), and open request on the site ----
        var lockCodes = [], lockCust = {};
        sites.forEach(function(s) { lockCodes.push(s.site_code); if (s.cust_sys_id) lockCust[s.site_code] = s.cust_sys_id; });
        var swapLocks = getSwapLocks(lockCodes, lockCust);
        var reqLocks  = getOpenRequestLocks(lockCodes);

        // ---- GRANDPARENT-LEVEL locks: an open request / pending swap on ANY site of the Grandparent blocks ALL its sites ----
        var gpLk = getGpLocks(gpCode);

        var swapCount = 0, reqCount = 0;
        sites.forEach(function(s) {
            var sl = swapLocks[s.site_code];
            if (sl) { s.swap_locked = true; s.swap_ref = sl.ref; s.swap_role = sl.role; }
            else if (gpLk.swap) { s.swap_locked = true; s.gp_swap_lock = true; s.swap_ref = gpLk.swap.ref; s.swap_site = gpLk.swap.site; }
            if (s.swap_locked) swapCount++;

            var rl = reqLocks[s.site_code];
            if (rl) { s.req_locked = true; s.req_ref = rl; }
            else if (gpLk.req) { s.req_locked = true; s.gp_req_lock = true; s.req_ref = gpLk.req.ref; s.req_group = gpLk.req.group; }
            if (s.req_locked) reqCount++;
        });

        // selectable sites first, locked sites last
        var statusRank = { 'Pending SPOC': 0, 'No CRM Draft': 1, 'Processed': 2 };
        for (var si = 0; si < sites.length; si++) { sites[si]._i = si; }
        sites.sort(function(a, b) {
            var la = (a.swap_locked || a.req_locked) ? 10 : 0;
            var lb = (b.swap_locked || b.req_locked) ? 10 : 0;
            var ra = statusRank[a.status]; if (ra === undefined) ra = 3;
            var rb = statusRank[b.status]; if (rb === undefined) rb = 3;
            ra += la; rb += lb;
            if (ra !== rb) return ra - rb;
            return a._i - b._i;
        });

        // latest snapshot total_outstanding per site (shown on the site table, used for NOD)
        var osByCust = {};
        if (custSysIds.length > 0) {
            var oGr = new GlideRecord(TABLES.OUTSTANDING);
            oGr.addQuery('customer', 'IN', custSysIds.join(','));
            oGr.orderByDesc('snapshot_month');
            oGr.query();

            var seenOsCustomers = {};
            while (oGr.next()) {
                var cId = oGr.getValue('customer');
                if (!seenOsCustomers[cId]) {
                    seenOsCustomers[cId] = true;
                    osByCust[cId] = osTotal(oGr);
                }
            }
        }
        sites.forEach(function(s) { s.outstanding = osByCust[s.cust_sys_id] || 0; });

        data.groupedParameters = buildMatrixGroup();
        data.draftDetails = {
            staging_sys_ids: stagingSysIds,
            customer_name: custName,
            grandparent_code: gpCode,
            company_type: compType,
            crm_document_link: crmDocumentLink,
            crm_document_name: crmDocumentName,
            crm_document_view_url: crmDocumentViewUrl,
            crm_justification: crmJustification,
            crm_gp_request: crmGpReqId,
            crm_gp_request_number: crmGpReqNumber,
            crm_gp_request_state: crmGpReqState,
            crm_gp_request_submitted_by: crmGpReqSubmittedBy,
            swap_locked_count: swapCount,
            req_locked_count: reqCount,
            gp_req_lock: gpLk.req,
            gp_swap_lock: gpLk.swap,
            sites: sites
        };
      } catch (loadErr) {
        gs.error('Central SPOC widget - load_draft_by_group failed: ' + loadErr.message);
        data.error = loadErr.message;
      }
    }

    // ======================= SUBMIT =======================
    if (action === 'submit_spoc_request') {
        try {
            var targetGp = input.gpCode;
            var groupCodeSub = input.groupCode;
            var custNameSub = input.customerName || 'UltraTech Key Customer';
            var compTypeSub = input.companyType || 'Unlisted';

            var selSites = input.sites || [];
            if (selSites.length === 0) {
                data.success = false;
                data.error = 'No sites were selected.';
                return;
            }

            if (!new GlideRecord(TABLES.KEY_ZONAL).isValid()) {
                data.success = false;
                data.error = "Table '" + TABLES.KEY_ZONAL + "' was not found.";
                return;
            }
            if (!new GlideRecord(TABLES.KEY_SITE).isValid()) {
                data.success = false;
                data.error = "Table '" + TABLES.KEY_SITE + "' was not found.";
                return;
            }

            // ---- 1. sites must be valid Key sites (N00, not N09) of this GP / Group inside the user's segment / zone / region / depot ----
            var selCodes = selSites.map(function(s) { return (s.site_code || '').toString().trim(); });
            var custIdByCodeSub = {};
            var vm = new GlideRecord(TABLES.CUSTOMER_MASTER);
            applyScope(vm, ['grand_parent=' + targetGp, 'groupcode=' + groupCodeSub, 'customer_code_sapIN' + selCodes.join(',')]);
            vm.query();
            while (vm.next()) custIdByCodeSub[getSafeValue(vm, ['customer_code_sap'])] = vm.getUniqueValue();

            var badCodes = selCodes.filter(function(cd) { return !custIdByCodeSub[cd]; });
            if (badCodes.length) {
                data.success = false;
                data.error = 'These site codes are not valid Key sites of ' + targetGp + ' / ' + groupCodeSub + ' for your zone / region / depot and segment: ' + badCodes.join(', ');
                return;
            }

            // ---- 2. locks: pending limit swap (approval = requested), open request ----
            var swapLockSub = getSwapLocks(selCodes, custIdByCodeSub);
            var swapBad = Object.keys(swapLockSub);
            if (swapBad.length) {
                data.success = false;
                data.error = 'Limit swap pending (approval = requested). Remove these site(s) from the request: ' +
                    swapBad.map(function(cd) { return cd + ' (' + swapLockSub[cd].ref + ', ' + swapLockSub[cd].role + ')'; }).join(', ');
                return;
            }
            var reqLockSub = getOpenRequestLocks(selCodes);
            var reqBad = Object.keys(reqLockSub);
            if (reqBad.length) {
                data.success = false;
                data.error = 'These site(s) already have an open request: ' +
                    reqBad.map(function(cd) { return cd + ' (' + reqLockSub[cd] + ')'; }).join(', ');
                return;
            }

            // ---- 2b. GRANDPARENT-LEVEL locks: any open request / pending swap under this Grandparent blocks every site ----
            var gpLkSub = getGpLocks(targetGp);
            if (gpLkSub.swap) {
                data.success = false;
                data.error = 'A limit swap (' + gpLkSub.swap.ref + ') is in progress for site ' + gpLkSub.swap.site +
                    ' under Grandparent ' + targetGp + '. No request can be raised for any site of this Grandparent until the swap is Approved, Rejected or Returned.';
                return;
            }
            if (gpLkSub.req) {
                data.success = false;
                data.error = 'Request ' + gpLkSub.req.ref + (gpLkSub.req.group ? ' (Group ' + gpLkSub.req.group + ')' : '') +
                    ' is in process under Grandparent ' + targetGp + '. No new request can be raised for any site of this Grandparent until it is Approved, Rejected or Returned.';
                return;
            }

            // ---- 3. row validation ----
            var rowErrors = [];
            selSites.forEach(function(st) {
                rowErrors = rowErrors.concat(validateSiteRow(st));
            });
            if (rowErrors.length > 0) {
                data.success = false;
                data.error = 'Validation failed:\n' + rowErrors.join('\n');
                return;
            }

            var bizJust = (input.businessJustification || '').trim();
            var devJust = (input.deviationJustification || '').trim();

            var totalConsolidatedAsk = 0;
            var totalMonthly = 0;
            var totalCurrent = 0;
            var totalExpected = 0;
            var totalRate = 0;

            var zonalAgg = {};
            var zonalOsMap = {};

            selSites.forEach(function(st) {
                var reqLimit = parseFloat(st.requested_limit) || 0;
                var monthPot = parseFloat(st.monthly_potential) || 0;
                var currPot = parseFloat(st.current_potential) || 0;
                var expPot = parseFloat(st.expected_potential) || parseFloat(st.expected_sob_qty) || 0;
                var rate = parseFloat(st.order_rate) || 0;

                totalConsolidatedAsk += reqLimit;
                totalMonthly += monthPot;
                totalCurrent += currPot;
                totalExpected += expPot;
                totalRate += rate;

                var zc = (st.zonal_parent_code || '').toString().trim();
                if (zc && zc !== '-') {
                    if (!zonalAgg[zc]) {
                        zonalAgg[zc] = { monthly: 0, current: 0, expected: 0, limit: 0 };
                    }
                    zonalAgg[zc].monthly  += monthPot;
                    zonalAgg[zc].current  += currPot;
                    zonalAgg[zc].expected += expPot;
                    zonalAgg[zc].limit    += reqLimit;

                    zonalOsMap[zc] = (zonalOsMap[zc] || 0) + (parseFloat(st.outstanding) || 0);
                }
            });

            var avgOrderRate = selSites.length > 0 ? (totalRate / selSites.length) : 0;

            var firstSite = selSites[0] || {};
            var segName = firstSite.segment || 'Cement';

            // ---- 4. LIVE SAP position (site, group code, grandparent code). CRM draft values are never used ----
            var liveBySite = {};
            selSites.forEach(function(st) {
                var lv = getLiveCredit(st.site_code, st.salesorg, st.bg_expiry_raw || st.bgExpiry || '');
                liveBySite[st.site_code] = {
                    limit: lv.ok ? lv.limit    : (parseFloat(st.limit) || 0),
                    bg:    lv.ok ? lv.activeBg : (parseFloat(st.activeBg) || 0)
                };
            });

            var soMapSub = salesOrgByCodes([groupCodeSub, targetGp]);
            var fbSo = firstSite.salesorg || '';
            var grpLiveR = getLiveCredit(groupCodeSub, soMapSub[groupCodeSub] || segDefaultSalesOrg(segName) || fbSo, '');
            var gpLiveR  = getLiveCredit(targetGp,     soMapSub[targetGp]     || segDefaultSalesOrg(segName) || fbSo, '');

            // fallback: the live values the client fetched, only if the server API call failed
            var grpFb = input.grpLive || null, gpFb = input.gpLive || null;
            if (!grpLiveR.ok && !grpFb) { data.success = false; data.error = 'Could not fetch the live Group Code credit position from SAP. Please try again.'; return; }
            if (!gpLiveR.ok  && !gpFb)  { data.success = false; data.error = 'Could not fetch the live Grandparent credit position from SAP. Please try again.'; return; }
            var grpBase = grpLiveR.ok ? { limit: grpLiveR.limit, bg: grpLiveR.activeBg } : { limit: parseFloat(grpFb.limit) || 0, bg: parseFloat(grpFb.activeBg) || 0 };
            var gpBase  = gpLiveR.ok  ? { limit: gpLiveR.limit,  bg: gpLiveR.activeBg }  : { limit: parseFloat(gpFb.limit)  || 0, bg: parseFloat(gpFb.activeBg)  || 0 };

            // limit delta = total requested limit (added on top of the current Group / Grandparent limit)
            // Updated Group / Grandparent limit = sum of the updated CL of their sites (calculated on the screen).
            // Fallback (only if the screen values are missing): current limit + total requested limit.
            var limitDelta = 0;
            selSites.forEach(function(st) {
                limitDelta += (parseFloat(st.requested_limit) || 0);
            });
            var updGrpIn = parseFloat(input.updGrpLimit);
            var updGpIn  = parseFloat(input.updGpLimit);
            var updGrpLimitSub = isNaN(updGrpIn) ? (grpBase.limit + limitDelta) : updGrpIn;
            var updGpLimitSub  = isNaN(updGpIn)  ? (gpBase.limit + limitDelta)  : updGpIn;

            // Stage 1: Group Code Net Exposure (trigger check)
            var finalGrpNetExp = updGrpLimitSub - grpBase.bg;
            // Stage 2: Grandparent Net Exposure (deviation check / Rs 1.5 Cr override)
            var finalGpNetExp  = updGpLimitSub - gpBase.bg;

            var safeLimitVal = parseFloat((input.calc || {}).safeLimit) || 0;
            var segUpper = (segName || '').toUpperCase();
            var threshold = (segUpper === 'CEMENT') ? 5000000 : ((segUpper === 'RMC' || segUpper === 'BPD') ? 2500000 : 0);

            var triggerToolWorking = (threshold > 0) && (finalGrpNetExp >= threshold);
            var isDeviation = triggerToolWorking && (finalGpNetExp > safeLimitVal);
            var gpThresholdBreached = finalGpNetExp > 15000000;   // Rs 1.5 Cr

            if (!bizJust) {
                data.success = false;
                data.error = 'Grandparent Level Remarks / Justification is required.';
                return;
            }
            if (isDeviation && !devJust) {
                data.success = false;
                data.error = 'Deviation Justification is required because the Grandparent-Level Net Exposure exceeds the Safe Allowable Limit.';
                return;
            }

            // ================= GROUP CODE REQUEST =================
            var grpGr = new GlideRecord(TABLES.GROUP_REQ);
            grpGr.initialize();

            grpGr.setValue('grandparent_code', targetGp);
            grpGr.setValue('group_code', groupCodeSub);
            grpGr.setValue('segment', firstSite.segment || 'Cement');
            grpGr.setValue('company_type', compTypeSub);

            grpGr.setValue('business_justification', bizJust);
            grpGr.setValue('deviation_justification', isDeviation ? devJust : '');

            grpGr.setValue('monthly_potential', totalMonthly);
            grpGr.setValue('current_potential', totalCurrent);
            grpGr.setValue('expected_sob', totalExpected);
            grpGr.setValue('total_requested_limit', totalConsolidatedAsk);
            grpGr.setValue('order_rate', avgOrderRate);

            // LIVE values
            grpGr.setValue('grandparent_cl', gpBase.limit);
            grpGr.setValue('groupcode_cl', grpBase.limit);

            grpGr.setValue('u_document_link', input.crm_document_link || '');

            grpGr.setValue('u_tool_p1', (input.calc || {}).p1);
            grpGr.setValue('u_tool_p2', (input.calc || {}).p2);
            grpGr.setValue('u_tool_p3', (input.calc || {}).p3);
            grpGr.setValue('internal_rating', input.int_rating);
            grpGr.setValue('external_rating', input.ext_rating);

            grpGr.setValue('safe_allowable_limit', safeLimitVal);
            grpGr.setValue('is_deviation', isDeviation);
            grpGr.setValue('group_net_exposure', finalGrpNetExp);
            grpGr.setValue('grandparent_net_exposure', finalGpNetExp);

            // optional fields (create them on the table; ignored until they exist)
            setIfValid(grpGr, 'tool_working_triggered', triggerToolWorking);
            setIfValid(grpGr, 'gp_threshold_breached', gpThresholdBreached);
            setIfValid(grpGr, 'entered_external_rating', (input.enteredExtRating || ''));
            setIfValid(grpGr, 'u_p1_breakdown', JSON.stringify(input.p1Breakdown || []));
            setIfValid(grpGr, 'u_p2_breakdown', JSON.stringify(input.p2Breakdown || []));

            grpGr.setValue('state', 'Submitted');
            grpGr.setValue('initiator', currentUserId);

            var parentSysId = grpGr.insert();

            if (!parentSysId) {
                data.success = false;
                data.error = 'Failed to create the group code request record.';
                return;
            }

            if (input.fileData && input.fileName && input.fileType && parentSysId) {
                var attachment2 = new GlideSysAttachment();
                attachment2.writeBase64(grpGr, input.fileName, input.fileType, input.fileData);
            }

            var sourceGuid = input.attachmentGUID;
            if (sourceGuid && parentSysId) {
                var attachCopy = new GlideSysAttachment();
                attachCopy.copy(TABLES.GROUP_REQ, sourceGuid, TABLES.GROUP_REQ, parentSysId);

                var tmpAtt = new GlideRecord('sys_attachment');
                tmpAtt.addQuery('table_name', TABLES.GROUP_REQ);
                tmpAtt.addQuery('table_sys_id', sourceGuid);
                tmpAtt.query();
                while (tmpAtt.next()) {
                    attachCopy.deleteAttachment(tmpAtt.getUniqueValue());
                }
            }

            var generatedNumber = '';
            var fetchNumGr = new GlideRecord(TABLES.GROUP_REQ);
            if (fetchNumGr.get(parentSysId)) {
                generatedNumber = fetchNumGr.getValue('number');
                if (!generatedNumber) {
                    var fallbackStamp = new GlideDateTime().getNumericValue().toString().substring(5);
                    generatedNumber = 'REQ00' + fallbackStamp;
                    fetchNumGr.setValue('number', generatedNumber);
                    fetchNumGr.update();
                }
            }

            // ================= ZONAL LEVEL RECORDS (live zonal parent limit / BG) =================
            var zonalFallback = {};
            (input.zonals || []).forEach(function(zp) { if (zp && zp.code) zonalFallback[zp.code] = zp; });

            var zonalCodes = [], zonalSeg = {}, zonalSiteSo = {};
            selSites.forEach(function(st) {
                var zc = (st.zonal_parent_code || '').toString().trim();
                if (!zc || zc === '-') return;
                if (zonalCodes.indexOf(zc) === -1) {
                    zonalCodes.push(zc);
                    zonalSeg[zc] = st.segment || '';
                    zonalSiteSo[zc] = st.salesorg || '';
                }
            });

            var zonalSoMap = salesOrgByCodes(zonalCodes);
            var zonalSysIdByCode = {};

            zonalCodes.forEach(function(zc) {
                var fb = zonalFallback[zc] || {};
                var zSo = zonalSoMap[zc] || segDefaultSalesOrg(zonalSeg[zc]) || zonalSiteSo[zc] || fb.salesOrg || '';
                var zLive = getLiveCredit(zc, zSo, '');

                var zCl = zLive.ok ? zLive.limit    : (parseFloat(fb.limit) || 0);
                var zBg = zLive.ok ? zLive.activeBg : (parseFloat(fb.activeBg) || 0);
                var zExposure = zCl - zBg;
                var za = zonalAgg[zc] || { monthly: 0, current: 0, expected: 0, limit: 0 };

                var zGr = new GlideRecord(TABLES.KEY_ZONAL);
                zGr.initialize();

                setIfValid(zGr, 'zonal_code', zc);
                setRefOrText(zGr, 'group_request', parentSysId, generatedNumber);
                setRefOrText(zGr, 'group_code',    parentSysId, groupCodeSub);

                setIfValid(zGr, 'zonal_cl', zCl);
                setIfValid(zGr, 'zonal_bg', zBg);
                setIfValid(zGr, 'zonal_exposure', zExposure);
                setIfValid(zGr, 'zonal_outstanding', zonalOsMap[zc] || 0);

                setFirstValid(zGr, ['zonal_monthly_potential', 'zonal_monthly'], za.monthly);
                setIfValid(zGr, 'zonal_current_potential',  za.current);
                setIfValid(zGr, 'zonal_expected_potential', za.expected);
                setIfValid(zGr, 'zonal_desired_limit',      za.limit);

                zonalSysIdByCode[zc] = zGr.insert();
            });

            // ================= SITE LEVEL RECORDS (live site limit / BG) =================
            selSites.forEach(function(st) {
                var sCl = liveBySite[st.site_code].limit;
                var sBg = liveBySite[st.site_code].bg;
                var sNod = calcSiteNOD(st.cust_sys_id, st.segment, st.outstanding);
                if (!sNod) sNod = parseFloat(st.nod) || 0;

                var siteExposure = sCl - sBg;

                var szc = (st.zonal_parent_code || '').toString().trim();
                if (szc === '-') szc = '';
                var zRef = (szc && zonalSysIdByCode[szc]) ? zonalSysIdByCode[szc] : '';

                var siteExpected = parseFloat(st.expected_potential) || parseFloat(st.expected_sob_qty) || 0;

                var siteGr = new GlideRecord(TABLES.KEY_SITE);
                siteGr.initialize();
                setIfValid(siteGr, 'site_code', st.site_code);
                siteGr.setValue('customer_name', st.customer_name || custNameSub);
                setIfValid(siteGr, 'site_cl', sCl);
                setIfValid(siteGr, 'site_bg', sBg);
                setIfValid(siteGr, 'site_exposure', siteExposure);
                setIfValid(siteGr, 'site_nod', sNod);
                setIfValid(siteGr, 'site_justification', (st.site_justification || '').toString().trim());
                setIfValid(siteGr, 'site_outstanding', parseFloat(st.outstanding) || 0);

                // values confirmed by the Central SPOC (become stored potential once the request is Approved)
                setIfValid(siteGr, 'site_monthly_potential',  parseFloat(st.monthly_potential) || 0);
                setIfValid(siteGr, 'site_current_potential',  parseFloat(st.current_potential) || 0);
                setIfValid(siteGr, 'site_expected_potential', siteExpected);
                setIfValid(siteGr, 'site_rate',               parseFloat(st.order_rate) || 0);
                setFirstValid(siteGr, ['credit_tenor', 'site_credit_tenor'], parseInt(st.credit_tenor, 10) || 0);
                setIfValid(siteGr, 'site_desired_limit',      parseFloat(st.requested_limit) || 0);

                setRefOrText(siteGr, 'zonal_code',    zRef,        szc);
                setRefOrText(siteGr, 'group_request', parentSysId, generatedNumber);
                setRefOrText(siteGr, 'group_code',    parentSysId, groupCodeSub);

                siteGr.insert();
            });

            // ================= DRAFT DEMAND (processed) =================
            selSites.forEach(function(st) {
                var originalDraft = new GlideRecord(TABLES.DRAFT_DEMAND);
                var hasOriginal = (st.sys_id && originalDraft.get(st.sys_id));

                if (hasOriginal) {
                    originalDraft.setValue('status', 'Processed');
                    originalDraft.setValue('processed_by', currentUserId);
                    originalDraft.setValue('target_request', parentSysId);
                    originalDraft.update();
                }

                var siteJust = (st.site_justification || '').toString().trim();

                var spocDraft = new GlideRecord(TABLES.DRAFT_DEMAND);
                spocDraft.initialize();
                spocDraft.setValue('grandparent_code', targetGp);
                spocDraft.setValue('customer_name', hasOriginal ? originalDraft.getValue('customer_name') : (st.customer_name || custNameSub));
                spocDraft.setValue('group_code', groupCodeSub);
                spocDraft.setValue('zone_code', hasOriginal ? originalDraft.getValue('zone_code') : (st.zonal_parent_code || ''));
                spocDraft.setValue('site_code', st.site_code);
                spocDraft.setValue('segment', hasOriginal ? originalDraft.getValue('segment') : (st.segment || 'Cement'));
                if (hasOriginal) {
                    setIfValid(spocDraft, 'company_type', originalDraft.getValue('company_type'));
                    setIfValid(spocDraft, 'region', originalDraft.getValue('region'));
                } else {
                    setIfValid(spocDraft, 'company_type', compTypeSub);
                    setIfValid(spocDraft, 'region', st.region_code || '');
                }
                spocDraft.setValue('monthly_potential', st.monthly_potential);
                setFirstValid(spocDraft, ['current_potential', 'current_sob'], st.current_potential);
                setIfValid(spocDraft, 'expected_potential', st.expected_potential);
                spocDraft.setValue('expected_sob_qty', st.expected_sob_qty || 0);
                spocDraft.setValue('order_rate', st.order_rate);
                spocDraft.setValue('credit_tenor', st.credit_tenor);
                spocDraft.setValue('desired_limit', st.requested_limit);
                spocDraft.setValue('justification', siteJust ? siteJust : bizJust);
                spocDraft.setValue('deviation_justification', isDeviation ? devJust : '');
                spocDraft.setValue('u_document_link', hasOriginal ? originalDraft.getValue('u_document_link') : '');
                spocDraft.setValue('status', 'Processed');
                spocDraft.setValue('submitted_by', currentUserId);
                spocDraft.setValue('processed_by', currentUserId);
                spocDraft.setValue('target_request', parentSysId);

                var linkCrmReq = st.crm_gp_request || (hasOriginal ? originalDraft.getValue('crm_gp_request') : '');
                if (linkCrmReq) setIfValid(spocDraft, 'crm_gp_request', linkCrmReq);

                spocDraft.insert();
            });

            // ================= RISK MATRIX =================
            var mGrRec = new GlideRecord(TABLES.MATRIX);
            mGrRec.addQuery('grandparent_code', targetGp);
            mGrRec.query();
            if (!mGrRec.next()) {
                mGrRec.initialize();
                mGrRec.setValue('grandparent_code', targetGp);
                mGrRec.setValue('segment', firstSite.segment || 'Cement');
            }
            (input.riskParams || []).forEach(function(p) {
                setIfValid(mGrRec, p.k, p.val);
            });
            mGrRec.update();

            // Approval routing (+1 escalation, 1.5 Cr override, duplicate avoidance) is done by the Flow Designer
            // using group_net_exposure, grandparent_net_exposure and is_deviation saved above.

            data.success = true;
            data.requestNumber = generatedNumber;
        } catch (err) {
            data.success = false;
            data.error = err.message;
        } finally {
            input.fileData = '';
            input.fileName = '';
            input.fileType = '';
            input.sites = [];
            input.zonals = [];
            input.riskParams = [];
            delete data.fileData;
        }
    }

})();
